const e="shopping-cart",n=`status: complete
notes: All eighteen capabilities are built and working end to end — a dependency-free Node service (node:http + node:sqlite) with a vanilla-JS shop front, plus 64 passing tests (\`node --test "test/*.test.js"\`). The core is a single pure pricing function that recomputes the whole receipt on every read and every mutation, so no total, tax figure or discount is ever stored; money is integer minor units throughout with half-up rounding and largest-remainder allocation, and the currency/rounding rules are stated both in the README and on screen. Tax is a function of destination and product class (six jurisdictions, including UK zero-rating and NY's clothing threshold) and is applied to discounted amounts; shipping is quoted before checkout from zone, weight and post-discount value; coupons carry real eligibility rules and a written, enforced stacking policy (one per ITEM/ORDER/SHIPPING scope, those three stack, exclusive codes stand alone, refusals name the reason). Stock is checked at add, on every recompute, at checkout start and again immediately before the order is written; carts hold no stock, and a 15-minute reservation is taken only at checkout — the policy is stated in the UI rather than left implicit. Persistence is SQLite behind an opaque cookie: the cart survives reload, session end and a server restart (tested by restarting the server against the same database file), the guest cart merges into the account cart on sign-in (larger quantity wins rather than the sum, coupons re-evaluated, stale cookies follow the successor cart), and abandoned carts are listed and retrievable by recovery link. Two honest caveats: the front end was exercised by hand against a running server and is covered by static wiring checks and the API tests beneath it, but there is no browser in this environment so there is no rendered-DOM test; and the tax rates, shipping rates and the "Behind the scenes" admin controls (used to change stock and prices mid-session so the out-of-stock and price-change surfacing is demonstrable) are demo data with no authentication, as the README's "What this is not" section spells out along with the deliberate absence of payment and real authentication.
`,t=JSON.parse(`[{"path":"package.json","bytes":391,"text":"{\\n  \\"name\\": \\"shopping-cart\\",\\n  \\"version\\": \\"1.0.0\\",\\n  \\"private\\": true,\\n  \\"description\\": \\"A shopping cart: holds items, keeps the total honest, survives the customer leaving and coming back.\\",\\n  \\"type\\": \\"module\\",\\n  \\"engines\\": {\\n    \\"node\\": \\">=22.5.0\\"\\n  },\\n  \\"scripts\\": {\\n    \\"start\\": \\"node src/server.js\\",\\n    \\"test\\": \\"node --test \\\\\\"test/*.test.js\\\\\\"\\",\\n    \\"seed\\": \\"node scripts/seed.js\\"\\n  }\\n}\\n"},{"path":"public/app.js","bytes":21867,"text":"/**\\n * The shop front.\\n *\\n * One rule: the server owns the numbers. Every action posts to the API and gets\\n * a complete recomputed view back, which is re-rendered in place. Nothing is\\n * added up in the browser, and nothing here reloads the page — a quantity change\\n * is a fetch and a re-render of the affected regions.\\n */\\n\\nconst $ = (id) => document.getElementById(id);\\n\\nconst state = {\\n  view: null,\\n  catalog: null,\\n  pendingQty: new Map(), // lineId -> timer, for typed quantity changes\\n};\\n\\n// ── API ─────────────────────────────────────────────────────────────────────\\n\\nasync function api(method, path, body) {\\n  const res = await fetch(path, {\\n    method,\\n    headers: body ? { 'Content-Type': 'application/json' } : undefined,\\n    body: body ? JSON.stringify(body) : undefined,\\n  });\\n  let payload = null;\\n  try {\\n    payload = await res.json();\\n  } catch {\\n    payload = null;\\n  }\\n  if (!res.ok && payload?.error) {\\n    toast(payload.error.message, 'error');\\n    // 409s from checkout still carry a full view; render it so the cart is truthful.\\n    if (payload.receipt) apply(payload);\\n    return null;\\n  }\\n  if (!res.ok) {\\n    toast(\`Request failed (\${res.status})\`, 'error');\\n    return null;\\n  }\\n  return payload;\\n}\\n\\nfunction apply(payload) {\\n  if (!payload) return;\\n  if (payload.receipt) state.view = payload;\\n  if (payload.catalog) state.catalog = payload.catalog;\\n  render();\\n  for (const m of payload.messages ?? []) toast(m.message, m.level);\\n}\\n\\nasync function act(method, path, body) {\\n  document.body.classList.add('busy');\\n  try {\\n    const payload = await api(method, path, body);\\n    if (payload) apply(payload);\\n    return payload;\\n  } finally {\\n    document.body.classList.remove('busy');\\n  }\\n}\\n\\n// ── toasts ──────────────────────────────────────────────────────────────────\\n\\nfunction toast(message, level = 'info') {\\n  const el = document.createElement('div');\\n  el.className = \`toast toast--\${level}\`;\\n  el.textContent = message;\\n  $('toasts').append(el);\\n  setTimeout(() => {\\n    el.style.opacity = '0';\\n    setTimeout(() => el.remove(), 250);\\n  }, level === 'error' || level === 'warning' ? 7000 : 4200);\\n}\\n\\n// ── render ──────────────────────────────────────────────────────────────────\\n\\nfunction render() {\\n  if (!state.view) return;\\n  renderIdentity();\\n  renderCatalog();\\n  renderLines();\\n  renderAlerts();\\n  renderDestination();\\n  renderShipping();\\n  renderCoupons();\\n  renderTotals();\\n  renderReservation();\\n  renderPolicies();\\n  renderAdmin();\\n}\\n\\nfunction renderIdentity() {\\n  const { customer, cart } = state.view;\\n  $('identity').innerHTML = customer.signedIn\\n    ? \`Signed in as <strong>\${esc(customer.email)}</strong>\${customer.isNewCustomer ? ' · no orders yet' : ''}\`\\n    : 'Shopping as a guest';\\n  $('cart-count').textContent = state.view.receipt.itemCount;\\n  $('recovery-hint').innerHTML =\\n    \`This cart is saved server-side. Its recovery link is <a href=\\"\${cart.recoveryUrl}\\">\${esc(cart.recoveryUrl)}</a> — \` +\\n    'open it from any browser and the cart comes back.';\\n}\\n\\nfunction renderCatalog() {\\n  if (!state.catalog) return;\\n  const wrap = $('catalog');\\n  wrap.innerHTML = '';\\n  for (const product of state.catalog.products) {\\n    const el = document.createElement('article');\\n    el.className = 'product';\\n    el.innerHTML = \`\\n      <img class=\\"product__img\\" src=\\"\${product.variants[0].imageUrl}\\" alt=\\"\${esc(product.title)}\\" />\\n      <div>\\n        <div class=\\"product__brand\\">\${esc(product.brand)} · \${esc(product.productClass.replace('_', ' '))}</div>\\n        <div class=\\"product__title\\">\${esc(product.title)}</div>\\n        <p class=\\"product__desc\\">\${esc(product.description)}</p>\\n        <div class=\\"variants\\"></div>\\n      </div>\`;\\n    const variants = el.querySelector('.variants');\\n    for (const v of product.variants) {\\n      const row = document.createElement('div');\\n      row.className = \`variant\${v.inStock ? '' : ' variant--out'}\`;\\n      const swatchColour = swatchFor(v);\\n      row.innerHTML = \`\\n        <span class=\\"variant__label\\">\\n          \${swatchColour ? \`<span class=\\"swatch\\" style=\\"background:\${swatchColour}\\"></span>\` : ''}\\n          <span>\${esc(v.variantLabel)}</span>\\n          \${v.inStock\\n            ? v.low ? \`<span class=\\"stockflag stockflag--low\\">only \${v.available} left</span>\` : ''\\n            : '<span class=\\"stockflag stockflag--out\\">out of stock</span>'}\\n        </span>\\n        <span class=\\"variant__price num\\">\${esc(v.price.display)}</span>\\n        <button class=\\"btn btn--tiny\\" type=\\"button\\" \${v.inStock ? '' : 'disabled'}>Add</button>\`;\\n      row.querySelector('button').addEventListener('click', () =>\\n        act('POST', '/api/cart/items', { sku: v.sku, quantity: 1 }),\\n      );\\n      variants.append(row);\\n    }\\n    wrap.append(el);\\n  }\\n}\\n\\nconst SWATCHES = {\\n  Slate: '#5a6672', Rust: '#b4552f', Olive: '#5c6141', Navy: '#2c3a52', Yellow: '#e0b23c',\\n};\\nfunction swatchFor(v) {\\n  return SWATCHES[v.options.colour] ?? null;\\n}\\n\\nfunction renderLines() {\\n  const { receipt } = state.view;\\n  const wrap = $('lines');\\n  // Re-rendering replaces the quantity inputs, so remember where the cursor was.\\n  const focused = document.activeElement?.closest?.('.line');\\n  const focusedIndex = focused ? [...wrap.children].indexOf(focused) : -1;\\n  wrap.innerHTML = '';\\n  $('cart-summary').textContent = receipt.lineCount\\n    ? \`\${receipt.lineCount} line\${receipt.lineCount === 1 ? '' : 's'} · \${receipt.itemCount} item\${receipt.itemCount === 1 ? '' : 's'}\`\\n    : '';\\n\\n  if (receipt.lineCount === 0) {\\n    wrap.innerHTML = '<div class=\\"empty\\">Nothing here yet. Add something from the left.</div>';\\n    return;\\n  }\\n\\n  for (const line of receipt.lines) {\\n    const el = document.createElement('div');\\n    el.className = 'line';\\n    const priceWas = line.priceChange\\n      ? \`<span class=\\"line__was num\\">\${esc(line.priceChange.was.display)}</span>\`\\n      : '';\\n    const discount = line.discount.minor > 0\\n      ? \`<div class=\\"line__unit\\">Offer applied: −\${esc(line.discount.display)}</div>\`\\n      : '';\\n    el.innerHTML = \`\\n      <img class=\\"line__img\\" src=\\"\${line.imageUrl}\\" alt=\\"\${esc(line.productTitle)}\\" />\\n      <div>\\n        <div class=\\"line__top\\">\\n          <div>\\n            <div class=\\"line__title\\">\${esc(line.productTitle)}</div>\\n            <div class=\\"line__variant\\">\${esc(line.variantLabel)}</div>\\n            <div class=\\"line__unit\\">\${priceWas}\${esc(line.unitPrice.display)} each × \${line.quantity}</div>\\n            \${discount}\\n          </div>\\n          <div class=\\"line__linetotal num\\">\${esc(line.lineTotal.display)}</div>\\n        </div>\\n        <div class=\\"line__controls\\">\\n          <div class=\\"qty\\">\\n            <button type=\\"button\\" data-act=\\"dec\\" aria-label=\\"Decrease quantity\\">−</button>\\n            <input type=\\"number\\" min=\\"0\\" max=\\"99\\" value=\\"\${line.quantity}\\" aria-label=\\"Quantity\\" />\\n            <button type=\\"button\\" data-act=\\"inc\\" aria-label=\\"Increase quantity\\">+</button>\\n          </div>\\n          <button class=\\"linkbtn\\" type=\\"button\\" data-act=\\"remove\\">Remove</button>\\n        </div>\\n        \${line.notices.map((n) => \`<div class=\\"line__note note--\${n.level}\\">\${esc(n.message)}</div>\`).join('')}\\n      </div>\`;\\n\\n    const input = el.querySelector('input');\\n    el.querySelector('[data-act=\\"dec\\"]').addEventListener('click', () => changeQty(line.lineId, line.quantity - 1));\\n    el.querySelector('[data-act=\\"inc\\"]').addEventListener('click', () => changeQty(line.lineId, line.quantity + 1));\\n    el.querySelector('[data-act=\\"remove\\"]').addEventListener('click', () =>\\n      act('DELETE', \`/api/cart/items/\${encodeURIComponent(line.lineId)}\`),\\n    );\\n    // An empty box means \\"still typing\\", not \\"quantity zero\\" — don't delete the line.\\n    const typed = () => (input.value.trim() === '' ? null : Number(input.value));\\n    input.addEventListener('change', () => {\\n      const q = typed();\\n      if (q === null) input.value = String(line.quantity);\\n      else changeQty(line.lineId, q);\\n    });\\n    input.addEventListener('input', () => {\\n      clearTimeout(state.pendingQty.get(line.lineId));\\n      const q = typed();\\n      if (q === null) return;\\n      state.pendingQty.set(line.lineId, setTimeout(() => changeQty(line.lineId, q), 550));\\n    });\\n    wrap.append(el);\\n  }\\n\\n  if (focusedIndex >= 0 && wrap.children[focusedIndex]) {\\n    const input = wrap.children[focusedIndex].querySelector('input');\\n    input?.focus();\\n    input?.select();\\n  }\\n}\\n\\nfunction changeQty(lineId, quantity) {\\n  clearTimeout(state.pendingQty.get(lineId));\\n  state.pendingQty.delete(lineId);\\n  if (!Number.isFinite(quantity) || quantity < 0) return;\\n  if (quantity === 0) return act('DELETE', \`/api/cart/items/\${encodeURIComponent(lineId)}\`);\\n  return act('PATCH', \`/api/cart/items/\${encodeURIComponent(lineId)}\`, { quantity });\\n}\\n\\nfunction renderAlerts() {\\n  const { receipt } = state.view;\\n  const alerts = [];\\n  for (const b of receipt.blockers) alerts.push({ level: 'error', message: b.reason });\\n  for (const n of receipt.notices) alerts.push(n);\\n  for (const r of receipt.promotions.rejected) alerts.push({ level: 'warning', message: r.reason });\\n  const changed = receipt.lines.filter((l) => l.priceChange);\\n  if (changed.length) {\\n    alerts.push({\\n      level: 'warning',\\n      message: \`Price \${changed.length === 1 ? 'change' : 'changes'} since you added: \${changed\\n        .map((l) => \`\${l.productTitle} \${l.priceChange.was.display} → \${l.priceChange.now.display}\`)\\n        .join('; ')}.\`,\\n    });\\n  }\\n  $('alerts').innerHTML = alerts\\n    .map((a) => \`<div class=\\"alert alert--\${a.level}\\">\${esc(a.message)}</div>\`)\\n    .join('');\\n}\\n\\nfunction renderDestination() {\\n  if (!state.catalog) return;\\n  const select = $('destination');\\n  const current = state.view.cart.destination;\\n  const key = current ? (current.region ? \`\${current.country}-\${current.region}\` : current.country) : '';\\n  select.innerHTML =\\n    '<option value=\\"\\">Choose a destination…</option>' +\\n    state.catalog.destinations\\n      .map((d) => \`<option value=\\"\${d.key}\\" \${d.key === key ? 'selected' : ''}>\${esc(d.label)} — \${esc(d.taxName)}</option>\`)\\n      .join('');\\n}\\n\\nfunction renderShipping() {\\n  const { receipt } = state.view;\\n  const wrap = $('ship-methods');\\n  wrap.innerHTML = '';\\n  for (const opt of receipt.shipping.options) {\\n    const on = opt.id === receipt.shipping.methodId;\\n    const el = document.createElement('label');\\n    el.className = \`ship\${on ? ' ship--on' : ''}\`;\\n    el.innerHTML = \`\\n      <span>\\n        <input type=\\"radio\\" name=\\"ship\\" \${on ? 'checked' : ''} />\\n        <strong>\${esc(opt.label)}</strong>\\n        <span class=\\"ship__eta\\"> · \${esc(opt.eta)}</span>\\n      </span>\\n      <span class=\\"num\\">\${opt.quotable ? esc(opt.amount.display) : '—'}</span>\`;\\n    el.addEventListener('click', () => act('PUT', '/api/cart/shipping-method', { methodId: opt.id }));\\n    wrap.append(el);\\n  }\\n  $('ship-note').textContent = receipt.lineCount\\n    ? \`\${receipt.shipping.reason} Estimate only — the carrier's final charge is confirmed at checkout.\`\\n    : '';\\n}\\n\\nfunction renderCoupons() {\\n  const { receipt } = state.view;\\n  $('coupons-applied').innerHTML = receipt.promotions.applied\\n    .map(\\n      (c) => \`<span class=\\"chip\\" title=\\"\${esc(c.terms)}\\">\${esc(c.code)} −\${esc(c.amount.display)}\\n        <button type=\\"button\\" data-code=\\"\${esc(c.code)}\\" aria-label=\\"Remove \${esc(c.code)}\\">×</button></span>\`,\\n    )\\n    .join('');\\n  for (const btn of $('coupons-applied').querySelectorAll('button')) {\\n    btn.addEventListener('click', () => act('DELETE', \`/api/cart/coupons/\${encodeURIComponent(btn.dataset.code)}\`));\\n  }\\n\\n  if (!$('coupon-help').dataset.filled && state.catalog) {\\n    $('coupon-help').dataset.filled = '1';\\n    $('coupon-help').innerHTML =\\n      state.catalog.coupons\\n        .map((c) => \`<div><code>\${esc(c.code)}</code> — \${esc(c.label)}. <em>\${esc(c.scope)}</em> offer\${c.exclusive ? ', <strong>exclusive</strong>' : ''}. \${esc(c.terms)}</div>\`)\\n        .join('') +\\n      '<div><strong>Stacking:</strong> at most one item offer, one order offer and one shipping offer at a time — those three stack with each other. An offer marked exclusive must be the only one on the cart.</div>';\\n  }\\n}\\n\\nfunction renderTotals() {\\n  const { receipt } = state.view;\\n  const t = receipt.totals;\\n  const rows = [];\\n  rows.push(row('Items subtotal', t.subtotal.display));\\n\\n  for (const promo of receipt.promotions.applied.filter((p) => p.scope !== 'shipping')) {\\n    rows.push(row(\`\${promo.code} — \${promo.label}\`, \`−\${promo.amount.display}\`, 'trow--save'));\\n  }\\n  if (t.discountTotal.minor > 0) rows.push(row('Merchandise total', t.merchandiseTotal.display, 'trow--muted'));\\n\\n  const shipLabel = receipt.shipping.quotable\\n    ? \`Shipping — \${receipt.shipping.label}<small>\${esc(receipt.shipping.eta)}</small>\`\\n    : 'Shipping<small>choose a destination</small>';\\n  rows.push(row(shipLabel, receipt.shipping.quotable ? receipt.shipping.amount.display : '—', '', true));\\n  for (const promo of receipt.promotions.applied.filter((p) => p.scope === 'shipping')) {\\n    rows.push(row(\`\${promo.code} — \${promo.label}\`, \`−\${promo.amount.display}\`, 'trow--save'));\\n  }\\n\\n  if (receipt.tax.jurisdiction) {\\n    for (const band of receipt.tax.bands.filter((b) => b.rateBps > 0)) {\\n      rows.push(\\n        row(\\n          \`\${receipt.tax.jurisdiction.name} at \${band.rateLabel}<small>on \${band.taxableBase.display}</small>\`,\\n          band.amount.display,\\n          'trow--muted',\\n          true,\\n        ),\\n      );\\n    }\\n    const zero = receipt.tax.bands.find((b) => b.rateBps === 0);\\n    if (zero && zero.taxableBase.minor > 0) {\\n      rows.push(row(\`Zero-rated<small>on \${zero.taxableBase.display}</small>\`, zero.amount.display, 'trow--muted', true));\\n    }\\n    rows.push(row('Tax', t.tax.display));\\n  } else {\\n    rows.push(row('Tax<small>choose a destination</small>', '—', 'trow--muted', true));\\n  }\\n\\n  rows.push(row('Total', t.grandTotal.display, 'trow--grand'));\\n  if (t.savings.minor > 0) rows.push(row('You saved', t.savings.display, 'trow--save'));\\n\\n  $('totals').innerHTML = rows.join('');\\n  $('checkout').disabled = !receipt.checkoutReady;\\n  $('checkout-note').textContent = receipt.lineCount === 0\\n    ? 'Your cart is empty.'\\n    : receipt.checkoutReady\\n      ? \`Availability is re-checked when you press this, and stock is held for \${state.view.policy.reservation.windowMinutes} minutes.\`\\n      : 'Fix the flagged lines above to check out.';\\n}\\n\\nfunction row(label, value, cls = '', rawLabel = false) {\\n  return \`<div class=\\"trow \${cls}\\"><span class=\\"trow__label\\">\${rawLabel ? label : esc(label)}</span><span>\${esc(value)}</span></div>\`;\\n}\\n\\nfunction renderReservation() {\\n  const r = state.view.reservation;\\n  const el = $('reservation');\\n  if (!r || r.expiresInSeconds <= 0) {\\n    el.className = 'reservation';\\n    el.innerHTML = state.view.receipt.lineCount\\n      ? \`<span class=\\"muted\\">Items in your cart are <strong>not</strong> reserved — stock is first come, first served until checkout.</span>\`\\n      : '';\\n    return;\\n  }\\n  el.className = 'reservation reservation--on';\\n  const mins = Math.floor(r.expiresInSeconds / 60);\\n  const secs = String(r.expiresInSeconds % 60).padStart(2, '0');\\n  el.innerHTML = \`Stock held for you — <strong>\${mins}:\${secs}</strong> left. Confirm to place the order.\`;\\n}\\n\\nfunction renderPolicies() {\\n  const p = state.view.policy;\\n  const rules = state.view.receipt.currencyRules;\\n  $('policies').innerHTML = \`\\n    <div><strong>Reservation:</strong> \${esc(p.reservation.statement)}</div>\\n    <div><strong>Stock:</strong> checked when you add, on every recompute, when checkout starts, and again before the order is written.</div>\\n    <div><strong>Money:</strong> \${esc(rules.currency)}, held as \${esc(rules.representation)}; rounding \${esc(rules.rounding)}; \${esc(rules.allocation)}.</div>\\n    <div><strong>Totals:</strong> recomputed on every request from current catalogue prices — nothing is cached on the cart.</div>\\n    <div><strong>Abandonment:</strong> a cart is listed as abandoned after \${p.abandonedAfterMinutes} idle minutes and stays retrievable by its recovery link.</div>\`;\\n}\\n\\nfunction renderAdmin() {\\n  if (!state.catalog || $('admin').dataset.filled) return;\\n  $('admin').dataset.filled = '1';\\n  const skus = state.catalog.products.flatMap((p) =>\\n    p.variants.map((v) => ({ sku: v.sku, label: \`\${p.title} — \${v.variantLabel}\` })),\\n  );\\n  const options = skus.map((s) => \`<option value=\\"\${s.sku}\\">\${esc(s.label)}</option>\`).join('');\\n  $('admin').innerHTML = \`\\n    <div class=\\"admin__row\\">\\n      <select id=\\"admin-stock-sku\\">\${options}</select>\\n      <input id=\\"admin-stock-qty\\" type=\\"number\\" min=\\"0\\" value=\\"0\\" />\\n      <button class=\\"btn btn--tiny\\" id=\\"admin-stock-go\\" type=\\"button\\">Set stock</button>\\n    </div>\\n    <div class=\\"admin__row\\">\\n      <select id=\\"admin-price-sku\\">\${options}</select>\\n      <input id=\\"admin-price-val\\" type=\\"text\\" value=\\"19.99\\" />\\n      <button class=\\"btn btn--tiny\\" id=\\"admin-price-go\\" type=\\"button\\">Set price</button>\\n    </div>\`;\\n  $('admin-stock-go').addEventListener('click', () =>\\n    act('POST', '/api/admin/stock', { sku: $('admin-stock-sku').value, onHand: Number($('admin-stock-qty').value) }),\\n  );\\n  $('admin-price-go').addEventListener('click', () =>\\n    act('POST', '/api/admin/price', { sku: $('admin-price-sku').value, price: $('admin-price-val').value.trim() }),\\n  );\\n}\\n\\nasync function refreshAbandoned() {\\n  const minutes = Number($('abandon-minutes').value) || 0;\\n  const payload = await api('GET', \`/api/carts/abandoned?minutes=\${minutes}\`);\\n  if (!payload) return;\\n  $('abandoned').innerHTML = payload.carts.length\\n    ? payload.carts\\n        .map(\\n          (c) => \`<div class=\\"aband\\">\\n            <span>\${c.unitCount} item\${c.unitCount === 1 ? '' : 's'} · idle \${c.idleMinutes} min \${c.email ? \`· \${esc(c.email)}\` : '· guest'}<br><code>\${esc(c.cartId)}</code></span>\\n            <a class=\\"btn btn--tiny\\" href=\\"\${c.recoveryUrl}\\">Open recovery link</a>\\n          </div>\`,\\n        )\\n        .join('')\\n    : '<p class=\\"hint\\">No carts idle that long.</p>';\\n}\\n\\n// ── wiring ──────────────────────────────────────────────────────────────────\\n\\n$('destination').addEventListener('change', (e) => {\\n  const key = e.target.value;\\n  if (!key) return act('PUT', '/api/cart/destination', { country: null, region: null });\\n  const [country, region = null] = key.split('-');\\n  return act('PUT', '/api/cart/destination', { country, region });\\n});\\n\\n$('coupon-form').addEventListener('submit', async (e) => {\\n  e.preventDefault();\\n  const code = $('coupon-code').value.trim();\\n  if (!code) return;\\n  const ok = await act('POST', '/api/cart/coupons', { code });\\n  if (ok) $('coupon-code').value = '';\\n});\\n\\n$('signin-form').addEventListener('submit', async (e) => {\\n  e.preventDefault();\\n  const email = $('email').value.trim();\\n  if (!email) return;\\n  await act('POST', '/api/session/signin', { email });\\n});\\n\\n$('signout').addEventListener('click', () => act('POST', '/api/session/signout'));\\n\\n$('cart-jump').addEventListener('click', () => $('cart-panel').scrollIntoView({ behavior: 'smooth', block: 'start' }));\\n\\n$('abandon-refresh').addEventListener('click', refreshAbandoned);\\n$('behind').addEventListener('toggle', (e) => {\\n  if (e.target.open) refreshAbandoned();\\n});\\n\\n$('checkout').addEventListener('click', async () => {\\n  // Step 1: re-check stock and take the hold.\\n  const begun = await act('POST', '/api/checkout/begin');\\n  if (!begun || !begun.receipt.checkoutReady) return;\\n  // Step 2: confirm. (A real shop takes payment between these two calls.)\\n  const done = await act('POST', '/api/checkout/confirm', { email: begun.customer.email });\\n  if (done?.order) showOrder(done.order);\\n});\\n\\nfunction showOrder(order) {\\n  const t = order.receipt.totals;\\n  $('order-body').innerHTML = \`\\n    <h3>Order placed</h3>\\n    <p class=\\"muted\\">\${esc(order.id)}</p>\\n    <dl>\\n      <dt>Items</dt><dd>\${esc(t.subtotal.display)}</dd>\\n      <dt>Discounts</dt><dd>−\${esc(t.savings.display)}</dd>\\n      <dt>Shipping</dt><dd>\${esc(t.shippingNet.display)}</dd>\\n      <dt>Tax</dt><dd>\${esc(t.tax.display)}</dd>\\n      <dt><strong>Total</strong></dt><dd><strong>\${esc(t.grandTotal.display)}</strong></dd>\\n    </dl>\\n    <p class=\\"hint\\">Stock has been decremented and your cart is empty again.</p>\`;\\n  $('order-dialog').showModal();\\n}\\n\\n// The reservation clock ticks locally between fetches; the server is still the\\n// authority on whether the hold is live.\\nsetInterval(() => {\\n  const r = state.view?.reservation;\\n  if (!r || r.expiresInSeconds <= 0) return;\\n  r.expiresInSeconds -= 1;\\n  renderReservation();\\n}, 1000);\\n\\nfunction esc(s) {\\n  return String(s ?? '').replace(/[&<>\\"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\\"': '&quot;', \\"'\\": '&#39;' })[c]);\\n}\\n\\n// ── boot ────────────────────────────────────────────────────────────────────\\n\\n(async function boot() {\\n  const params = new URLSearchParams(location.search);\\n  const recover = params.get('recover');\\n  if (recover) {\\n    const payload = await api('POST', '/api/cart/recover', { recoveryToken: recover });\\n    history.replaceState({}, '', location.pathname);\\n    if (payload) {\\n      apply(payload);\\n      return;\\n    }\\n  }\\n  const payload = await api('GET', '/api/state');\\n  apply(payload);\\n})();\\n"},{"path":"public/index.html","bytes":5208,"text":"<!doctype html>\\n<html lang=\\"en\\">\\n  <head>\\n    <meta charset=\\"utf-8\\" />\\n    <meta name=\\"viewport\\" content=\\"width=device-width, initial-scale=1\\" />\\n    <title>Northline — Cart</title>\\n    <link rel=\\"icon\\" href=\\"/img/TEE-M-SLATE.svg\\" />\\n    <link rel=\\"stylesheet\\" href=\\"/styles.css\\" />\\n  </head>\\n  <body>\\n    <header class=\\"topbar\\">\\n      <div class=\\"topbar__inner\\">\\n        <div class=\\"brand\\">\\n          <span class=\\"brand__mark\\" aria-hidden=\\"true\\"></span>\\n          <span class=\\"brand__name\\">Northline</span>\\n        </div>\\n        <div class=\\"topbar__right\\">\\n          <div id=\\"identity\\" class=\\"identity\\"></div>\\n          <button id=\\"cart-jump\\" class=\\"pill\\" type=\\"button\\">\\n            Cart <span id=\\"cart-count\\" class=\\"pill__count\\">0</span>\\n          </button>\\n        </div>\\n      </div>\\n    </header>\\n\\n    <div id=\\"toasts\\" class=\\"toasts\\" role=\\"status\\" aria-live=\\"polite\\"></div>\\n\\n    <main class=\\"layout\\">\\n      <section class=\\"col col--catalog\\" aria-label=\\"Catalogue\\">\\n        <h1 class=\\"page-title\\">Shop</h1>\\n        <p class=\\"page-sub\\">\\n          Pick a size and a colour — each variant is its own line. Adding the same variant twice merges the lines.\\n        </p>\\n        <div id=\\"catalog\\" class=\\"catalog\\"></div>\\n\\n        <details class=\\"panel panel--muted\\" id=\\"behind\\">\\n          <summary><strong>Behind the scenes</strong> — move the world under your own feet</summary>\\n          <div class=\\"panel__body\\">\\n            <p class=\\"hint\\">\\n              These controls exist so you can see the honest-cart behaviour: change stock or a price\\n              <em>after</em> adding something, then look at the cart.\\n            </p>\\n            <div id=\\"admin\\" class=\\"admin\\"></div>\\n            <h3 class=\\"sub\\">Abandoned carts</h3>\\n            <p class=\\"hint\\">\\n              Carts with items that have gone quiet. Each row is a recovery link — open it in a private window to\\n              become that shopper again.\\n            </p>\\n            <div class=\\"row row--tight\\">\\n              <label class=\\"field field--inline\\">\\n                <span>Idle for at least</span>\\n                <input id=\\"abandon-minutes\\" type=\\"number\\" min=\\"0\\" value=\\"0\\" step=\\"1\\" />\\n                <span>minutes</span>\\n              </label>\\n              <button id=\\"abandon-refresh\\" class=\\"btn btn--ghost\\" type=\\"button\\">Refresh</button>\\n            </div>\\n            <div id=\\"abandoned\\" class=\\"abandoned\\"></div>\\n            <h3 class=\\"sub\\">Rules in force</h3>\\n            <div id=\\"policies\\" class=\\"policies\\"></div>\\n          </div>\\n        </details>\\n      </section>\\n\\n      <section class=\\"col col--cart\\" id=\\"cart-panel\\" aria-label=\\"Your cart\\">\\n        <div class=\\"cart card\\">\\n          <div class=\\"card__head\\">\\n            <h2>Your cart</h2>\\n            <span id=\\"cart-summary\\" class=\\"muted\\"></span>\\n          </div>\\n\\n          <div id=\\"alerts\\" class=\\"alerts\\"></div>\\n          <div id=\\"lines\\" class=\\"lines\\"></div>\\n\\n          <div class=\\"card__section\\">\\n            <h3 class=\\"sub\\">Deliver to</h3>\\n            <div class=\\"row\\">\\n              <label class=\\"field\\">\\n                <span class=\\"field__label\\">Destination</span>\\n                <select id=\\"destination\\"></select>\\n              </label>\\n            </div>\\n            <div id=\\"ship-methods\\" class=\\"ship-methods\\"></div>\\n            <p id=\\"ship-note\\" class=\\"hint\\"></p>\\n          </div>\\n\\n          <div class=\\"card__section\\">\\n            <h3 class=\\"sub\\">Offers</h3>\\n            <form id=\\"coupon-form\\" class=\\"row row--tight\\">\\n              <input id=\\"coupon-code\\" type=\\"text\\" placeholder=\\"Coupon code\\" autocomplete=\\"off\\" spellcheck=\\"false\\" />\\n              <button class=\\"btn\\" type=\\"submit\\">Apply</button>\\n            </form>\\n            <div id=\\"coupons-applied\\" class=\\"chips\\"></div>\\n            <details class=\\"mini\\">\\n              <summary>Codes you can try &amp; how they stack</summary>\\n              <div id=\\"coupon-help\\" class=\\"coupon-help\\"></div>\\n            </details>\\n          </div>\\n\\n          <div class=\\"card__section totals\\" id=\\"totals\\"></div>\\n\\n          <div class=\\"card__section\\">\\n            <div id=\\"reservation\\" class=\\"reservation\\"></div>\\n            <button id=\\"checkout\\" class=\\"btn btn--primary btn--wide\\" type=\\"button\\">Check out</button>\\n            <p id=\\"checkout-note\\" class=\\"hint\\"></p>\\n          </div>\\n\\n          <div class=\\"card__section\\">\\n            <h3 class=\\"sub\\">Account</h3>\\n            <form id=\\"signin-form\\" class=\\"row row--tight\\">\\n              <input id=\\"email\\" type=\\"email\\" placeholder=\\"you@example.com\\" autocomplete=\\"email\\" />\\n              <button class=\\"btn\\" type=\\"submit\\">Sign in</button>\\n            </form>\\n            <p class=\\"hint\\">\\n              Sign in with a cart already in hand: the guest cart merges into the saved account cart instead of\\n              vanishing. <button id=\\"signout\\" class=\\"linkbtn\\" type=\\"button\\">Sign out</button>\\n            </p>\\n            <p class=\\"hint\\" id=\\"recovery-hint\\"></p>\\n          </div>\\n        </div>\\n      </section>\\n    </main>\\n\\n    <dialog id=\\"order-dialog\\" class=\\"dialog\\">\\n      <div id=\\"order-body\\"></div>\\n      <form method=\\"dialog\\"><button class=\\"btn btn--primary\\">Done</button></form>\\n    </dialog>\\n\\n    <script type=\\"module\\" src=\\"/app.js\\"><\/script>\\n  </body>\\n</html>\\n"},{"path":"public/styles.css","bytes":14271,"text":":root {\\n  color-scheme: light dark;\\n\\n  --bg: #f6f7f9;\\n  --surface: #ffffff;\\n  --surface-2: #f0f2f5;\\n  --ink: #16191d;\\n  --ink-2: #5a6470;\\n  --line: #dfe3e8;\\n  --accent: #1f5f8b;\\n  --accent-ink: #ffffff;\\n  --ok: #1f7a4d;\\n  --warn: #8a5a00;\\n  --warn-bg: #fdf3e0;\\n  --err: #a3242a;\\n  --err-bg: #fdeceb;\\n  --ok-bg: #e9f6ef;\\n  --info-bg: #eaf1f7;\\n  --radius: 12px;\\n  --shadow: 0 1px 2px rgb(16 24 40 / 6%), 0 8px 24px rgb(16 24 40 / 6%);\\n}\\n\\n@media (prefers-color-scheme: dark) {\\n  :root {\\n    --bg: #0f1216;\\n    --surface: #161a20;\\n    --surface-2: #1d222a;\\n    --ink: #e8ecf1;\\n    --ink-2: #9aa5b1;\\n    --line: #2a313a;\\n    --accent: #63a6d6;\\n    --accent-ink: #0c1116;\\n    --ok: #6fd39b;\\n    --warn: #e3b566;\\n    --warn-bg: #2e2415;\\n    --err: #f08a8a;\\n    --err-bg: #331c1c;\\n    --ok-bg: #14291f;\\n    --info-bg: #16222c;\\n    --shadow: 0 1px 2px rgb(0 0 0 / 40%), 0 10px 30px rgb(0 0 0 / 30%);\\n  }\\n}\\n\\n* { box-sizing: border-box; }\\n\\nbody {\\n  margin: 0;\\n  background: var(--bg);\\n  color: var(--ink);\\n  font: 15px/1.5 ui-sans-serif, system-ui, -apple-system, \\"Segoe UI\\", Roboto, sans-serif;\\n  -webkit-font-smoothing: antialiased;\\n}\\n\\nh1, h2, h3 { line-height: 1.25; margin: 0; }\\n.sub { font-size: 13px; text-transform: uppercase; letter-spacing: .06em; color: var(--ink-2); margin: 0 0 8px; }\\n.muted { color: var(--ink-2); }\\n.hint { color: var(--ink-2); font-size: 13px; margin: 8px 0 0; }\\n.num { font-variant-numeric: tabular-nums; }\\n\\n/* ── top bar ─────────────────────────────────────────────────────────────── */\\n.topbar {\\n  position: sticky; top: 0; z-index: 20;\\n  background: color-mix(in oklab, var(--surface) 88%, transparent);\\n  backdrop-filter: blur(8px);\\n  border-bottom: 1px solid var(--line);\\n}\\n.topbar__inner {\\n  max-width: 1180px; margin: 0 auto; padding: 12px 20px;\\n  display: flex; align-items: center; justify-content: space-between; gap: 16px;\\n}\\n.brand { display: flex; align-items: center; gap: 10px; font-weight: 650; letter-spacing: -.01em; }\\n.brand__mark { width: 20px; height: 20px; border-radius: 6px; background: linear-gradient(135deg, #2f6f9f, #7fb3d5); }\\n.topbar__right { display: flex; align-items: center; gap: 14px; }\\n.identity { font-size: 13px; color: var(--ink-2); }\\n.identity strong { color: var(--ink); }\\n\\n.pill {\\n  border: 1px solid var(--line); background: var(--surface); color: var(--ink);\\n  border-radius: 999px; padding: 6px 14px; font: inherit; font-size: 14px; cursor: pointer;\\n  display: inline-flex; align-items: center; gap: 8px;\\n}\\n.pill__count {\\n  min-width: 22px; height: 22px; border-radius: 999px; background: var(--accent); color: var(--accent-ink);\\n  display: inline-grid; place-items: center; font-size: 12px; font-weight: 650; padding: 0 6px;\\n}\\n\\n/* ── layout ──────────────────────────────────────────────────────────────── */\\n.layout {\\n  max-width: 1180px; margin: 0 auto; padding: 24px 20px 80px;\\n  display: grid; grid-template-columns: minmax(0, 1fr) 400px; gap: 28px; align-items: start;\\n}\\n@media (max-width: 940px) { .layout { grid-template-columns: 1fr; } }\\n\\n.page-title { font-size: 26px; letter-spacing: -.02em; }\\n.page-sub { color: var(--ink-2); margin: 6px 0 20px; max-width: 58ch; }\\n\\n.card {\\n  background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); box-shadow: var(--shadow);\\n}\\n.card__head { padding: 16px 18px; border-bottom: 1px solid var(--line); display: flex; justify-content: space-between; align-items: baseline; gap: 10px; }\\n.card__head h2 { font-size: 17px; }\\n.card__section { padding: 16px 18px; border-top: 1px solid var(--line); }\\n.col--cart { position: sticky; top: 74px; }\\n@media (max-width: 940px) { .col--cart { position: static; } }\\n\\n/* ── catalogue ───────────────────────────────────────────────────────────── */\\n.catalog { display: grid; gap: 16px; }\\n.product {\\n  background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius);\\n  padding: 16px; display: grid; grid-template-columns: 104px minmax(0, 1fr); gap: 16px; box-shadow: var(--shadow);\\n}\\n.product__img { width: 104px; height: 104px; border-radius: 10px; object-fit: cover; background: var(--surface-2); }\\n.product__title { font-size: 16px; font-weight: 640; }\\n.product__brand { font-size: 12px; text-transform: uppercase; letter-spacing: .06em; color: var(--ink-2); }\\n.product__desc { color: var(--ink-2); font-size: 14px; margin: 6px 0 10px; }\\n.variants { display: grid; gap: 6px; }\\n.variant {\\n  display: grid; grid-template-columns: minmax(0, 1fr) auto auto; gap: 10px; align-items: center;\\n  padding: 7px 8px; border: 1px solid var(--line); border-radius: 9px; background: var(--surface-2);\\n}\\n.variant--out { opacity: .62; }\\n.variant__label { font-size: 14px; display: flex; align-items: center; gap: 8px; min-width: 0; }\\n.swatch { width: 12px; height: 12px; border-radius: 4px; border: 1px solid rgb(0 0 0 / 20%); flex: none; }\\n.variant__price { font-variant-numeric: tabular-nums; font-size: 14px; }\\n.stockflag { font-size: 11px; padding: 2px 7px; border-radius: 999px; white-space: nowrap; }\\n.stockflag--low { background: var(--warn-bg); color: var(--warn); }\\n.stockflag--out { background: var(--err-bg); color: var(--err); }\\n\\n/* ── buttons & fields ────────────────────────────────────────────────────── */\\n.btn {\\n  font: inherit; font-size: 14px; border: 1px solid var(--line); background: var(--surface); color: var(--ink);\\n  border-radius: 9px; padding: 7px 13px; cursor: pointer;\\n}\\n.btn:hover:not(:disabled) { border-color: var(--accent); }\\n.btn:disabled { opacity: .5; cursor: not-allowed; }\\n.btn--primary { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); font-weight: 600; }\\n.btn--ghost { background: transparent; }\\n.btn--wide { width: 100%; padding: 11px; font-size: 15px; }\\n.btn--tiny { padding: 3px 8px; font-size: 12px; border-radius: 7px; }\\n.linkbtn { background: none; border: 0; color: var(--accent); font: inherit; font-size: 13px; padding: 0; cursor: pointer; text-decoration: underline; }\\n\\ninput, select {\\n  font: inherit; font-size: 14px; color: var(--ink); background: var(--surface);\\n  border: 1px solid var(--line); border-radius: 9px; padding: 7px 10px; min-width: 0;\\n}\\ninput:focus-visible, select:focus-visible, .btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }\\n.row { display: flex; gap: 10px; align-items: flex-end; flex-wrap: wrap; }\\n.row--tight { gap: 8px; align-items: center; }\\n.row--tight input { flex: 1 1 140px; }\\n.field { display: grid; gap: 4px; flex: 1 1 160px; }\\n.field--inline { display: flex; align-items: center; gap: 6px; flex: 0 0 auto; font-size: 13px; color: var(--ink-2); }\\n.field--inline input { width: 72px; }\\n.field__label { font-size: 12px; color: var(--ink-2); }\\n\\n/* ── cart lines ──────────────────────────────────────────────────────────── */\\n.lines { padding: 6px 18px 12px; display: grid; gap: 2px; }\\n.line { display: grid; grid-template-columns: 60px minmax(0, 1fr); gap: 12px; padding: 12px 0; border-bottom: 1px dashed var(--line); }\\n.line:last-child { border-bottom: 0; }\\n.line__img { width: 60px; height: 60px; border-radius: 9px; object-fit: cover; background: var(--surface-2); }\\n.line__top { display: flex; justify-content: space-between; gap: 10px; align-items: baseline; }\\n.line__title { font-weight: 600; font-size: 14px; }\\n.line__variant { font-size: 12.5px; color: var(--ink-2); margin-top: 1px; }\\n.line__unit { font-size: 12.5px; color: var(--ink-2); margin-top: 3px; font-variant-numeric: tabular-nums; }\\n.line__linetotal { font-variant-numeric: tabular-nums; font-weight: 620; white-space: nowrap; }\\n.line__was { color: var(--ink-2); text-decoration: line-through; font-weight: 400; font-size: 12.5px; margin-right: 6px; }\\n.line__controls { display: flex; align-items: center; gap: 10px; margin-top: 8px; }\\n.qty { display: inline-flex; align-items: center; border: 1px solid var(--line); border-radius: 8px; overflow: hidden; }\\n.qty button { border: 0; background: var(--surface-2); color: var(--ink); font: inherit; width: 28px; height: 28px; cursor: pointer; }\\n.qty button:hover:not(:disabled) { background: var(--accent); color: var(--accent-ink); }\\n.qty button:disabled { opacity: .4; cursor: not-allowed; }\\n.qty input { border: 0; width: 44px; text-align: center; padding: 4px; border-radius: 0; background: var(--surface); }\\n.line__note { font-size: 12.5px; border-radius: 7px; padding: 5px 8px; margin-top: 7px; }\\n.note--error { background: var(--err-bg); color: var(--err); }\\n.note--warning { background: var(--warn-bg); color: var(--warn); }\\n.note--info { background: var(--info-bg); color: var(--ink-2); }\\n.empty { padding: 26px 18px; text-align: center; color: var(--ink-2); }\\n\\n/* ── totals ──────────────────────────────────────────────────────────────── */\\n.totals { display: grid; gap: 7px; }\\n.trow { display: flex; justify-content: space-between; gap: 12px; font-size: 14px; font-variant-numeric: tabular-nums; }\\n.trow--muted { color: var(--ink-2); font-size: 13px; }\\n.trow--save { color: var(--ok); }\\n.trow--grand { font-size: 18px; font-weight: 700; border-top: 1px solid var(--line); padding-top: 10px; margin-top: 4px; }\\n.trow__label small { display: block; color: var(--ink-2); font-weight: 400; font-size: 12px; }\\n\\n/* ── chips, alerts, toasts ───────────────────────────────────────────────── */\\n.chips { display: flex; flex-wrap: wrap; gap: 7px; margin-top: 10px; }\\n.chip {\\n  display: inline-flex; align-items: center; gap: 7px; font-size: 12.5px;\\n  background: var(--ok-bg); color: var(--ok); border-radius: 999px; padding: 4px 6px 4px 11px;\\n}\\n.chip button { border: 0; background: rgb(0 0 0 / 8%); color: inherit; border-radius: 999px; width: 18px; height: 18px; cursor: pointer; line-height: 1; font-size: 13px; }\\n.alerts { display: grid; gap: 8px; padding: 0 18px; }\\n.alerts:not(:empty) { padding-top: 14px; }\\n.alert { border-radius: 9px; padding: 9px 11px; font-size: 13px; }\\n.alert--error { background: var(--err-bg); color: var(--err); }\\n.alert--warning { background: var(--warn-bg); color: var(--warn); }\\n.alert--info { background: var(--info-bg); color: var(--ink-2); }\\n.alert--success { background: var(--ok-bg); color: var(--ok); }\\n\\n.toasts { position: fixed; right: 18px; top: 68px; z-index: 60; display: grid; gap: 8px; max-width: 380px; }\\n.toast {\\n  background: var(--surface); border: 1px solid var(--line); border-left-width: 4px; border-radius: 9px;\\n  padding: 10px 13px; font-size: 13.5px; box-shadow: var(--shadow); animation: pop .18s ease-out;\\n}\\n.toast--success { border-left-color: var(--ok); }\\n.toast--error { border-left-color: var(--err); }\\n.toast--warning { border-left-color: var(--warn); }\\n.toast--info { border-left-color: var(--accent); }\\n@keyframes pop { from { opacity: 0; transform: translateY(-6px); } to { opacity: 1; transform: none; } }\\n\\n/* ── shipping methods ────────────────────────────────────────────────────── */\\n.ship-methods { display: grid; gap: 7px; margin-top: 10px; }\\n.ship {\\n  display: flex; justify-content: space-between; gap: 10px; align-items: center;\\n  border: 1px solid var(--line); border-radius: 9px; padding: 8px 11px; cursor: pointer; font-size: 13.5px;\\n}\\n.ship--on { border-color: var(--accent); background: var(--info-bg); }\\n.ship__eta { color: var(--ink-2); font-size: 12.5px; }\\n.ship input { display: none; }\\n\\n/* ── panels ──────────────────────────────────────────────────────────────── */\\n.panel { margin-top: 22px; background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); }\\n.panel summary { padding: 13px 16px; cursor: pointer; font-size: 14px; }\\n.panel__body { padding: 0 16px 16px; }\\n.mini summary { font-size: 12.5px; color: var(--ink-2); cursor: pointer; margin-top: 10px; }\\n.coupon-help { font-size: 12.5px; color: var(--ink-2); margin-top: 8px; display: grid; gap: 6px; }\\n.coupon-help code { background: var(--surface-2); border-radius: 5px; padding: 1px 5px; color: var(--ink); }\\n.admin { display: grid; gap: 8px; margin: 10px 0 6px; }\\n.admin__row { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; font-size: 13px; }\\n.admin__row select { flex: 1 1 200px; }\\n.admin__row input { width: 96px; }\\n.abandoned { display: grid; gap: 8px; margin-top: 10px; }\\n.aband {\\n  display: flex; justify-content: space-between; align-items: center; gap: 10px; flex-wrap: wrap;\\n  border: 1px solid var(--line); border-radius: 9px; padding: 9px 11px; font-size: 13px;\\n}\\n.aband code { font-size: 12px; color: var(--ink-2); }\\n.policies { display: grid; gap: 8px; font-size: 13px; color: var(--ink-2); }\\n.policies strong { color: var(--ink); }\\n.reservation { font-size: 13px; margin-bottom: 10px; }\\n.reservation--on { background: var(--info-bg); border-radius: 9px; padding: 9px 11px; }\\n\\n.dialog { border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); color: var(--ink); max-width: 460px; padding: 22px; box-shadow: var(--shadow); }\\n.dialog::backdrop { background: rgb(0 0 0 / 45%); }\\n.dialog h3 { margin-bottom: 8px; }\\n.dialog dl { display: grid; grid-template-columns: auto 1fr; gap: 4px 14px; font-size: 14px; margin: 14px 0; }\\n.dialog dd { margin: 0; text-align: right; font-variant-numeric: tabular-nums; }\\n.busy { opacity: .55; pointer-events: none; transition: opacity .1s; }\\n"},{"path":"README.md","bytes":15329,"text":"# Shopping Cart\\n\\nHolds items, keeps the total honest, and survives the customer leaving and coming back.\\n\\nA small shop — catalogue, cart, coupons, tax, shipping, stock, checkout — built as a Node HTTP\\nservice with a browser front end. **No dependencies**: the database is \`node:sqlite\`, the server is\\n\`node:http\`, the tests are \`node:test\`, the UI is vanilla ES modules. Nothing to install.\\n\\n---\\n\\n## Run it\\n\\nRequires **Node 22.5+** (uses the built-in \`node:sqlite\`). Developed on Node 24.\\n\\n\`\`\`bash\\nnode src/server.js          # http://localhost:8787\\nnode scripts/seed.js        # optional: plant a returning customer + an abandoned cart\\nnode --test \\"test/*.test.js\\"  # 64 tests\\n\`\`\`\\n\\nOr via npm scripts: \`npm start\`, \`npm run seed\`, \`npm test\`.\\n\\n| Environment variable | Default        | Meaning                                     |\\n| -------------------- | -------------- | ------------------------------------------- |\\n| \`PORT\`               | \`8787\`         | HTTP port                                   |\\n| \`CART_DB\`            | \`data/cart.db\` | SQLite file. Delete it to start from clean. |\\n\\nOpen <http://localhost:8787>. The left column is the shop; the right column is the cart. Everything\\nin the cart is server-computed — the page never adds anything up itself.\\n\\n---\\n\\n## Try the interesting bits\\n\\nThe panel **“Behind the scenes”** at the bottom of the shop column exists so you can move the world\\nunder your own feet — set a SKU's stock or price *after* putting it in your cart.\\n\\n| To see…                            | Do this                                                                                                                                              |\\n| ---------------------------------- | ---------------------------------------------------------------------------------------------------------------------------------------------------- |\\n| **Variants kept distinct**         | Add *Harbour Tee* in M/Slate and L/Slate. Two lines, two prices, two images.                                                                            |\\n| **Duplicate lines merged**         | Add M/Slate again. One line, quantity 2, and a message saying so.                                                                                       |\\n| **Tax by destination and class**   | Put a tee, a book and a box of caramels in the cart, then switch destination. UK: 20% on the tee, 0% on the book and the sweets. Oregon: nothing at all. New York: the tee is exempt (clothing under $110), the book is not. |\\n| **Shipping estimate**              | Pick a destination; Standard/Express are both priced from weight and zone. Push the merchandise total over $75 domestically and Standard goes free.      |\\n| **Coupon eligibility**             | \`WELCOME10\` under $50 tells you how much more you need. \`SPRING24\` is expired. \`FREESHIP\` on Express tells you it only covers Standard.                  |\\n| **Stacking policy**                | \`BOOKS20\` + \`TENOFF\` + \`SHIPHALF\` all apply together (one per scope). Now try \`SAVE15\` — it is exclusive and refuses to share, naming what to remove.     |\\n| **Stock changing underneath you**  | Add 2 of something, then set its stock to 0 in the panel. The line goes red, checkout is blocked, and the reason is on the line.                         |\\n| **Price changing underneath you**  | Add something, then set a new price. The cart shows the old price struck through, the new price charged, and a banner.                                   |\\n| **The reservation window**         | Press *Check out*: stock is held for 15 minutes with a visible countdown, and a second browser can no longer take the last one.                          |\\n| **Surviving reload / session end** | Reload. Quit the browser. Restart the server (\`Ctrl-C\`, \`node src/server.js\`). The cart is still there — it lives in SQLite, not in the page.            |\\n| **The lost-cart bug, not present** | Add things as a guest, then sign in as \`returning@example.com\` (after \`npm run seed\`). The guest cart merges into the saved account cart; nothing is lost. |\\n| **Abandoned cart retrieval**       | *Behind the scenes → Abandoned carts*. Open a recovery link in a private window — you are that shopper, cart intact.                                     |\\n\\n---\\n\\n## How it is put together\\n\\n\`\`\`\\nsrc/money.js        integer-minor-unit Money, rounding, largest-remainder allocation\\nsrc/catalog.js      products, variants (= SKUs), product classes, seed stock, SVG product images\\nsrc/tax.js          jurisdictions; rate = f(destination, product class[, price band])\\nsrc/shipping.js     zones, methods, weight- and value-based estimate\\nsrc/promotions.js   coupon catalogue, eligibility checks, the stacking policy\\nsrc/pricing.js      the one pure function: cart state -> full receipt\\nsrc/cart-service.js cart operations (add/update/remove, coupons, sign-in merge, checkout)\\nsrc/store.js        SQLite schema and all persistence\\nsrc/server.js       HTTP: JSON API + static files + product images\\npublic/             the shop front (index.html, app.js, styles.css)\\ntest/               59 tests: money, pricing, promotions, cart/checkout, end-to-end HTTP\\nscripts/seed.js     demo data (returning customer, abandoned cart)\\n\`\`\`\\n\\n### Totals are computed, never stored\\n\\n\`price()\` in \`src/pricing.js\` takes the cart's rows and returns a whole receipt. It is called on\\n**every** read and every mutation. No total, tax figure or discount is ever written to the database,\\nso none of them can go stale. The cart stores only what the customer chose: SKU, quantity,\\ndestination, shipping method, coupon codes — plus the unit price *at the time of adding*, used\\nsolely to detect and report a price change.\\n\\nOrder of operations, fixed:\\n\\n1. line subtotal = **current** catalogue unit price × quantity\\n2. cart subtotal = Σ line subtotals\\n3. discounts: item-scope coupons, then order-scope, allocated back onto lines\\n4. merchandise total = subtotal − discounts\\n5. shipping quote (destination, billable weight, merchandise total, method), then shipping coupon\\n6. tax, per line, on its **discounted** amount at the rate for (destination, product class); plus tax\\n   on the net shipping charge where the jurisdiction taxes shipping\\n7. grand total = merchandise total + net shipping + tax\\n\\n### Currency and rounding rules\\n\\n* One currency per cart. The catalogue is **USD**; mixing currencies throws rather than guesses.\\n* Money is an **integer number of minor units** (cents) in a \`Money\` value object. There is no\\n  floating-point money anywhere: prices are authored as decimal strings and parsed, quantities\\n  multiply exactly, and JSON carries \`{minor, currency, decimal, display}\` — never a float.\\n* Percentages (tax, % coupons) are **integer basis points**; 2000 bps = 20%.\\n* Rounding is **half-up (away from zero)**, applied once, when an amount becomes a receipt line.\\n* When one rounded amount is split over several lines (an order-level discount), it is split by\\n  **largest remainder**, so the parts always sum back to the whole. \`test/money.test.js\` pins this.\\n\\n### Stacking policy\\n\\nEvery coupon has one scope: **ITEM**, **ORDER** or **SHIPPING**.\\n\\n1. At most one coupon per scope. A second in the same scope is refused, naming the incumbent.\\n2. The three scopes stack with each other — up to three coupons at once.\\n3. A coupon marked \`exclusive\` (e.g. \`SAVE15\`) must be the only one on the cart, in either direction.\\n4. Application order is fixed — ITEM, then ORDER on the item-discounted amount, then SHIPPING — so\\n   the result does not depend on the order the codes were typed.\\n5. No discount can take a line, or the shipping charge, below zero.\\n6. Eligibility is re-checked on every recompute. A coupon that stops qualifying is deactivated and\\n   **reported**, never silently kept or silently dropped. A code that cannot apply when entered is\\n   not left sitting in the cart pretending to work.\\n\\nCodes in the demo catalogue: \`WELCOME10\` (order, first-order only, min $50), \`SAVE15\` (order,\\n**exclusive**, min $100), \`TENOFF\` ($10 off over $80), \`BOOKS20\` (item, books), \`TEE5\` (item, $5 per\\ntee), \`FREESHIP\` (shipping, Standard only, min $60), \`SHIPHALF\` (shipping, any method), \`SPRING24\`\\n(expired, kept so expiry is demonstrable).\\n\\n### Stock and the reservation window\\n\\nAvailability is checked **at add**, on **every recompute** while the cart sits there, when\\n**checkout begins**, and **again** immediately before the order is written. Stock genuinely moves\\nbetween those points, and each check reports rather than silently trims.\\n\\nThe reservation policy, stated plainly in the UI:\\n\\n> Items in the cart are **not** reserved — stock is first come, first served. A **15-minute** hold is\\n> placed only when you start checkout, and is released automatically if you do not finish in time.\\n\\nAvailability for a cart = on-hand − units held by *other* carts' live holds. Expired holds are\\nreleased lazily on every availability read, so a stalled checkout returns stock by itself.\\n\\n### Persistence, sign-in merge, abandonment\\n\\nThe browser holds one httpOnly cookie containing an opaque cart token (30-day Max-Age). Every line,\\ncoupon, destination and reservation is in SQLite. Reload, new tab, browser restart and server\\nrestart all resolve to the same cart — \`test/api.test.js\` restarts the server against the same\\ndatabase file and checks the cart is still there.\\n\\nOn **sign-in** the guest cart is merged into the account's saved cart:\\n\\n* a SKU in both keeps the **larger** quantity, not the sum — someone who added the same thing on two\\n  devices meant \\"one of these\\", and summing is the classic way to ship a surprise double order;\\n* SKUs only in the guest cart are moved across;\\n* quantities are clamped to what is actually available, and any clamp is reported;\\n* coupon codes from both carts come across and are re-evaluated, so any that now conflict under the\\n  stacking policy are dropped **loudly**;\\n* the guest's destination and shipping choice win, being the more recent intent;\\n* the guest cart is marked \`merged\` and points at its successor, so a stale cookie still lands on\\n  the right cart instead of an empty one.\\n\\nA cart with items that has been idle for 30 minutes is listed as **abandoned** at\\n\`GET /api/carts/abandoned\`. Every cart also carries a permanent recovery token — \`/?recover=<token>\`\\nis the link you would put in a recovery email; opening it adopts that cart in any browser.\\n\\n---\\n\\n## HTTP API\\n\\nAll responses are the same shape: \`{ cart, customer, receipt, reservation, policy, messages }\`\\n(plus \`catalog\` where the catalogue may have changed). \`receipt\` holds the fully recomputed totals.\\n\\n| Method   | Path                          | Purpose                                             |\\n| -------- | ----------------------------- | --------------------------------------------------- |\\n| \`GET\`    | \`/api/state\`                  | Cart + catalogue in one call (what the page boots on)|\\n| \`GET\`    | \`/api/cart\`                   | Current cart and receipt                            |\\n| \`POST\`   | \`/api/cart/items\`             | \`{sku, quantity}\` — add (merges with an existing line)|\\n| \`PATCH\`  | \`/api/cart/items/:lineId\`     | \`{quantity}\` — set quantity (0 removes)             |\\n| \`DELETE\` | \`/api/cart/items/:lineId\`     | Remove a line                                       |\\n| \`PUT\`    | \`/api/cart/destination\`       | \`{country, region}\`                                 |\\n| \`PUT\`    | \`/api/cart/shipping-method\`   | \`{methodId}\` — \`standard\` \\\\| \`express\`              |\\n| \`POST\`   | \`/api/cart/coupons\`           | \`{code}\` — apply, or refuse with a reason           |\\n| \`DELETE\` | \`/api/cart/coupons/:code\`     | Remove a coupon                                     |\\n| \`POST\`   | \`/api/session/signin\`         | \`{email}\` — sign in and merge the guest cart        |\\n| \`POST\`   | \`/api/session/signout\`        | Leave the account cart saved, start a guest cart    |\\n| \`POST\`   | \`/api/checkout/begin\`         | Re-check stock, take the 15-minute hold             |\\n| \`POST\`   | \`/api/checkout/confirm\`       | Re-check again, decrement stock, write the order    |\\n| \`GET\`    | \`/api/orders/:id\`             | The stored receipt for an order                     |\\n| \`GET\`    | \`/api/carts/abandoned?minutes=\` | Abandoned carts with recovery links               |\\n| \`POST\`   | \`/api/cart/recover\`           | \`{recoveryToken}\` — adopt an abandoned cart         |\\n| \`POST\`   | \`/api/admin/stock\`            | Demo: \`{sku, onHand}\`                               |\\n| \`POST\`   | \`/api/admin/price\`            | Demo: \`{sku, price}\` (decimal string)               |\\n| \`GET\`    | \`/img/:sku.svg\`               | Generated product image                             |\\n\\nErrors are \`{error: {code, message}}\` with a real status code (\`409 out_of_stock\`,\\n\`404 unknown_coupon\`, …). Where a 409 still has a meaningful cart — a stock re-check failing at\\ncheckout — the full view rides along so the page can show the truth rather than a dead end.\\n\\n---\\n\\n## Tests\\n\\n\`\`\`\\nnode --test \\"test/*.test.js\\"      # 64 passing\\n\`\`\`\\n\\n* \`money.test.js\` — parsing, half-up rounding, allocation that never loses a cent, currency safety.\\n* \`pricing.test.js\` — line/cart/grand totals, tax by destination *and* class, tax on discounted\\n  amounts, shipping thresholds, price-change detection, stock blockers.\\n* \`promotions.test.js\` — every eligibility rule and every branch of the stacking policy.\\n* \`cart.test.js\` — add/update/remove, merging, availability at add, rehydration from the database,\\n  the sign-in merge, abandonment, reservation expiry, and both checkout stock re-checks.\\n* \`api.test.js\` — end-to-end over HTTP with a real cookie jar: reload, **server restart**, guest-cart\\n  merge, recovery link, 409s, and money crossing the wire as integers.\\n* \`frontend.test.js\` — static checks on the page: every element \`app.js\` reaches for exists (the\\n  failure that would otherwise be a silent blank page), and the front end does no money arithmetic\\n  of its own.\\n\\nThere is no browser in the test environment, so the front end is covered by those static checks plus\\nthe API tests underneath it, not by a rendered-DOM test. It was exercised by hand against a running\\nserver.\\n\\n---\\n\\n## What this is not\\n\\nDeliberate omissions, so nothing here reads as a claim it does not make:\\n\\n* **No payment.** \`POST /api/checkout/confirm\` is where an authorisation would go; it writes the\\n  order and decrements stock instead.\\n* **Authentication is an email box.** Sign-in takes an address and creates the account if new. That\\n  is enough to demonstrate the cart merge and nothing more — no password, no session security.\\n* **The tax table is plausible, not authoritative.** Six jurisdictions with real-looking rules\\n  (including NY's clothing threshold and UK zero-rating). A real shop calls a tax service; the point\\n  here is that the rate is a function of destination *and* product class, and that it is applied to\\n  the discounted amount.\\n* **Shipping rates are invented** and labelled as estimates in the UI.\\n* **The admin panel has no auth** — it is a demo control, and it says so.\\n* **Single currency.** The \`Money\` type is multi-currency-capable (exponent per currency, JPY\\n  included in the tests) but the catalogue is USD and a cart cannot mix currencies.\\n"},{"path":"scripts/seed.js","bytes":2473,"text":"/**\\n * Plants demo data so the persistence stories are visible without waiting:\\n *   - an account (returning@example.com) that already has an order, so\\n *     first-order coupons correctly refuse it, and a saved cart to merge into;\\n *   - an abandoned guest cart, backdated two hours, with a live recovery link.\\n *\\n *   node scripts/seed.js            (uses data/cart.db, or $CART_DB)\\n */\\n\\nimport { Store } from '../src/store.js';\\nimport * as svc from '../src/cart-service.js';\\n\\nconst dbFile = process.env.CART_DB ?? 'data/cart.db';\\nconst store = new Store(dbFile);\\nconst reload = (c) => store.cartById(c.id);\\n\\n// ── a returning customer with a saved cart ──────────────────────────────────\\nconst email = 'returning@example.com';\\nconst account = store.accountByEmail(email) ?? store.createAccount(email);\\nlet saved = store.activeCartForAccount(account.id);\\nif (!saved) {\\n  saved = store.createCart({ accountId: account.id, email: account.email });\\n  svc.addItem(store, reload(saved), { sku: 'BOOK-TIDES-HB', quantity: 1 });\\n  svc.addItem(store, reload(saved), { sku: 'KID-6-YELLOW', quantity: 1 });\\n  svc.setDestination(store, reload(saved), { country: 'GB' });\\n  store.recordOrder({\\n    cartId: 'seed-historic-order',\\n    accountId: account.id,\\n    email: account.email,\\n    receipt: { note: 'seeded history so WELCOME10 correctly refuses this account' },\\n    totalMinor: 4200,\\n    currency: 'USD',\\n  });\\n}\\n\\n// ── an abandoned guest cart ─────────────────────────────────────────────────\\nconst abandoned = store.createCart({});\\nsvc.addItem(store, abandoned, { sku: 'JKT-M-OLIVE', quantity: 1 });\\nsvc.addItem(store, reload(abandoned), { sku: 'CAR-BOX24', quantity: 2 });\\nconst twoHoursAgo = new Date(Date.now() - 2 * 60 * 60 * 1000).toISOString();\\nstore.db.prepare('UPDATE carts SET updated_at = ? WHERE id = ?').run(twoHoursAgo, abandoned.id);\\n\\nconsole.log(\`\\n  Seeded \${dbFile}\\n\\n  Returning customer : \${account.email}\\n      sign in with this address after adding things as a guest to watch the merge.\\n      It has an order in its history, so WELCOME10 will (correctly) refuse it.\\n\\n  Abandoned cart     : \${store.cartById(abandoned.id).lines.length} lines, idle 120 minutes\\n      recovery link  : http://localhost:\${process.env.PORT ?? 8787}/?recover=\${abandoned.recoveryToken}\\n\`);\\n\\nstore.close();\\n"},{"path":"src/cart-service.js","bytes":19283,"text":"/**\\n * Cart operations. Everything the HTTP layer can do to a cart lives here, so the\\n * tests can drive the same code paths without a socket.\\n *\\n * Every mutation returns a fresh, fully recomputed view. There is no partial\\n * update and no client-side total: the browser renders whatever the last view\\n * said, which is why the totals cannot drift.\\n */\\n\\nimport { VARIANTS, PRODUCTS, CATALOG_CURRENCY } from './catalog.js';\\nimport { Money } from './money.js';\\nimport { price } from './pricing.js';\\nimport { findCoupon, publicCoupons } from './promotions.js';\\nimport { methodById, DEFAULT_METHOD } from './shipping.js';\\nimport { DESTINATIONS, JURISDICTIONS } from './tax.js';\\nimport { RESERVATION_WINDOW_MINUTES, ABANDONED_AFTER_MINUTES } from './store.js';\\n\\nexport const MAX_QTY_PER_LINE = 99;\\n\\nexport class CartError extends Error {\\n  constructor(message, status = 400, code = 'bad_request') {\\n    super(message);\\n    this.status = status;\\n    this.code = code;\\n  }\\n}\\n\\n/** The full view the browser renders: cart, receipt, and anything advisory. */\\nexport function view(store, cart, { now = new Date(), messages = [] } = {}) {\\n  const account = store.accountById(cart.accountId);\\n  const customer = {\\n    accountId: cart.accountId,\\n    email: cart.email,\\n    signedIn: Boolean(cart.accountId),\\n    isNewCustomer: store.orderCountForAccount(cart.accountId) === 0,\\n  };\\n  const availability = store.availability(cart.id, now);\\n  const receipt = price({ ...cart, customer }, { availability, now });\\n  const reservation = store.activeReservation(cart.id, now);\\n\\n  return {\\n    cart: {\\n      id: cart.id,\\n      token: cart.token,\\n      recoveryToken: cart.recoveryToken,\\n      recoveryUrl: \`/?recover=\${cart.recoveryToken}\`,\\n      status: cart.status,\\n      destination: cart.destination,\\n      shippingMethodId: cart.shippingMethodId,\\n      createdAt: cart.createdAt,\\n      updatedAt: cart.updatedAt,\\n    },\\n    customer,\\n    receipt,\\n    reservation: reservation\\n      ? { ...reservation, windowMinutes: RESERVATION_WINDOW_MINUTES, expiresInSeconds: Math.max(0, Math.round((new Date(reservation.expiresAt) - now) / 1000)) }\\n      : null,\\n    policy: {\\n      reservation: {\\n        holdsStockInCart: false,\\n        windowMinutes: RESERVATION_WINDOW_MINUTES,\\n        statement:\\n          \`Items in the cart are NOT reserved — stock is first come, first served. A \${RESERVATION_WINDOW_MINUTES}-minute \` +\\n          'hold is placed only when you start checkout, and is released if you do not finish in time.',\\n      },\\n      abandonedAfterMinutes: ABANDONED_AFTER_MINUTES,\\n    },\\n    messages,\\n  };\\n}\\n\\nexport function catalogView(store, cart, now = new Date()) {\\n  const availability = store.availability(cart?.id ?? null, now);\\n  return {\\n    currency: CATALOG_CURRENCY,\\n    products: PRODUCTS.map((p) => ({\\n      id: p.id,\\n      title: p.title,\\n      brand: p.brand,\\n      description: p.description,\\n      productClass: p.productClass,\\n      options: p.options,\\n      variants: p.variants.map((v) => {\\n        const meta = VARIANTS.get(v.sku);\\n        const available = availability.get(v.sku) ?? 0;\\n        return {\\n          sku: v.sku,\\n          options: v.options,\\n          variantLabel: meta.variantLabel,\\n          price: Money.parse(v.price, CATALOG_CURRENCY),\\n          weightGrams: v.weightGrams,\\n          imageUrl: meta.imageUrl,\\n          available,\\n          inStock: available > 0,\\n          low: available > 0 && available <= 3,\\n        };\\n      }),\\n    })),\\n    destinations: DESTINATIONS.map((d) => ({ ...d, taxName: JURISDICTIONS[d.key].name })),\\n    coupons: publicCoupons(),\\n  };\\n}\\n\\n// ── items ───────────────────────────────────────────────────────────────────\\n\\nexport function addItem(store, cart, { sku, quantity = 1, now = new Date() }) {\\n  const variant = VARIANTS.get(sku);\\n  if (!variant) throw new CartError(\`No such product: \${sku}\`, 404, 'unknown_sku');\\n  const qty = normaliseQty(quantity);\\n\\n  const availability = store.availability(cart.id, now);\\n  const available = availability.get(sku) ?? 0;\\n  const existing = store.findLine(cart.id, sku);\\n  const currentQty = existing?.quantity ?? 0;\\n  const messages = [];\\n\\n  // Availability checked at add. (It is checked again at checkout — stock moves.)\\n  if (available <= 0) {\\n    throw new CartError(\`\${variant.productTitle} (\${variant.variantLabel}) is out of stock.\`, 409, 'out_of_stock');\\n  }\\n  let wanted = currentQty + qty;\\n  if (wanted > available) {\\n    wanted = available;\\n    messages.push({\\n      level: 'warning',\\n      kind: 'stock-clamped',\\n      message: \`Only \${available} of \${variant.productTitle} (\${variant.variantLabel}) left — quantity set to \${available}.\`,\\n    });\\n  }\\n  if (wanted > MAX_QTY_PER_LINE) {\\n    wanted = MAX_QTY_PER_LINE;\\n    messages.push({ level: 'warning', kind: 'max-qty', message: \`Limit of \${MAX_QTY_PER_LINE} per line.\` });\\n  }\\n\\n  const unitPriceMinor = Money.parse(variant.priceDecimal, CATALOG_CURRENCY).minor;\\n\\n  if (existing) {\\n    // Merge duplicate lines rather than repeat them.\\n    store.updateLineQuantity(cart.id, existing.lineId, wanted);\\n    if (wanted > currentQty) {\\n      messages.unshift({\\n        level: 'info',\\n        kind: 'merged',\\n        message: \`\${variant.productTitle} (\${variant.variantLabel}) was already in your cart — quantity is now \${wanted}.\`,\\n      });\\n    }\\n  } else {\\n    store.insertLine(cart.id, { sku, quantity: wanted, unitPriceMinor, now });\\n    messages.unshift({\\n      level: 'success',\\n      kind: 'added',\\n      message: \`Added \${variant.productTitle} (\${variant.variantLabel}).\`,\\n    });\\n  }\\n\\n  return view(store, store.cartById(cart.id), { now, messages });\\n}\\n\\nexport function setQuantity(store, cart, { lineId, quantity, now = new Date() }) {\\n  const line = store.lineById(cart.id, lineId);\\n  if (!line) throw new CartError('That line is no longer in your cart.', 404, 'unknown_line');\\n  const variant = VARIANTS.get(line.sku);\\n  const messages = [];\\n\\n  if (quantity === 0) return removeItem(store, cart, { lineId, now });\\n  let qty = normaliseQty(quantity);\\n\\n  const available = store.availability(cart.id, now).get(line.sku) ?? 0;\\n  if (qty > available) {\\n    if (available === 0) {\\n      throw new CartError(\`\${variant.productTitle} (\${variant.variantLabel}) has just sold out.\`, 409, 'out_of_stock');\\n    }\\n    qty = available;\\n    messages.push({\\n      level: 'warning',\\n      kind: 'stock-clamped',\\n      message: \`Only \${available} left — quantity set to \${available}.\`,\\n    });\\n  }\\n  if (qty > MAX_QTY_PER_LINE) {\\n    qty = MAX_QTY_PER_LINE;\\n    messages.push({ level: 'warning', kind: 'max-qty', message: \`Limit of \${MAX_QTY_PER_LINE} per line.\` });\\n  }\\n\\n  store.updateLineQuantity(cart.id, lineId, qty);\\n  return view(store, store.cartById(cart.id), { now, messages });\\n}\\n\\nexport function removeItem(store, cart, { lineId, now = new Date() }) {\\n  const line = store.lineById(cart.id, lineId);\\n  if (!line) throw new CartError('That line is no longer in your cart.', 404, 'unknown_line');\\n  const variant = VARIANTS.get(line.sku);\\n  store.deleteLine(cart.id, lineId);\\n  return view(store, store.cartById(cart.id), {\\n    now,\\n    messages: [\\n      {\\n        level: 'info',\\n        kind: 'removed',\\n        message: \`Removed \${variant ? \`\${variant.productTitle} (\${variant.variantLabel})\` : line.sku}.\`,\\n      },\\n    ],\\n  });\\n}\\n\\nfunction normaliseQty(quantity) {\\n  const qty = Number(quantity);\\n  if (!Number.isInteger(qty) || qty < 1) throw new CartError('Quantity must be a whole number of at least 1.', 400, 'bad_quantity');\\n  return Math.min(qty, MAX_QTY_PER_LINE);\\n}\\n\\n// ── destination, shipping, coupons ───────────────────────────────────────────\\n\\nexport function setDestination(store, cart, { country, region = null, now = new Date() }) {\\n  if (country && !JURISDICTIONS[region ? \`\${country}-\${region}\` : country]) {\\n    throw new CartError(\`We do not ship to \${region ? \`\${country}-\${region}\` : country} yet.\`, 400, 'unsupported_destination');\\n  }\\n  store.setDestination(cart.id, country ? { country, region } : null);\\n  return view(store, store.cartById(cart.id), { now });\\n}\\n\\nexport function setShippingMethod(store, cart, { methodId, now = new Date() }) {\\n  if (!methodById(methodId)) throw new CartError(\`Unknown shipping method: \${methodId}\`, 400, 'unknown_method');\\n  store.setShippingMethod(cart.id, methodId ?? DEFAULT_METHOD);\\n  return view(store, store.cartById(cart.id), { now });\\n}\\n\\nexport function applyCoupon(store, cart, { code, now = new Date() }) {\\n  const normalised = String(code ?? '').trim().toUpperCase();\\n  if (!normalised) throw new CartError('Enter a coupon code.', 400, 'empty_code');\\n  const coupon = findCoupon(normalised);\\n  if (!coupon) throw new CartError(\`\${normalised} is not a valid code.\`, 404, 'unknown_coupon');\\n  if (cart.couponCodes.includes(normalised)) {\\n    return view(store, cart, { now, messages: [{ level: 'info', kind: 'coupon', message: \`\${normalised} is already applied.\` }] });\\n  }\\n\\n  store.addCoupon(cart.id, normalised, now);\\n  const next = view(store, store.cartById(cart.id), { now });\\n\\n  // The engine is the authority on whether it stuck. If it did not, say why and\\n  // do not leave a dead code sitting in the cart.\\n  const rejection = next.receipt.promotions.rejected.find((r) => r.code === normalised);\\n  if (rejection) {\\n    store.removeCoupon(cart.id, normalised);\\n    return view(store, store.cartById(cart.id), {\\n      now,\\n      messages: [{ level: 'error', kind: 'coupon-rejected', message: rejection.reason }],\\n    });\\n  }\\n  const applied = next.receipt.promotions.applied.find((a) => a.code === normalised);\\n  next.messages = [\\n    {\\n      level: 'success',\\n      kind: 'coupon-applied',\\n      message: \`\${normalised} applied — \${applied.amount.format()} off. \${coupon.terms}\`,\\n    },\\n  ];\\n  return next;\\n}\\n\\nexport function removeCoupon(store, cart, { code, now = new Date() }) {\\n  const normalised = String(code ?? '').trim().toUpperCase();\\n  const removed = store.removeCoupon(cart.id, normalised);\\n  return view(store, store.cartById(cart.id), {\\n    now,\\n    messages: removed ? [{ level: 'info', kind: 'coupon-removed', message: \`\${normalised} removed.\` }] : [],\\n  });\\n}\\n\\n// ── identity: sign-in and the guest-cart merge ───────────────────────────────\\n\\n/**\\n * Sign in, and do not lose the guest cart.\\n *\\n * If the account already has a cart, the guest cart is merged into it:\\n *   - a SKU in both carts keeps the *larger* quantity, not the sum, because the\\n *     shopper picking the same thing on two devices meant \\"one of these\\", not two\\n *     (and the sum is the classic way to surprise someone with a double order);\\n *   - a SKU only in the guest cart is moved across;\\n *   - quantities are clamped to what is actually available;\\n *   - coupon codes from both carts are carried over and re-evaluated, so any\\n *     that now conflict under the stacking policy are reported, not silently kept;\\n *   - the guest's destination/shipping choice wins if they made one.\\n * The guest cart is then marked \`merged\` and points at its successor.\\n */\\nexport function signIn(store, guestCart, { email, now = new Date() }) {\\n  const clean = String(email ?? '').trim().toLowerCase();\\n  if (!/^[^@\\\\s]+@[^@\\\\s]+\\\\.[^@\\\\s]+$/.test(clean)) throw new CartError('Enter a valid email address.', 400, 'bad_email');\\n\\n  const account = store.accountByEmail(clean) ?? store.createAccount(clean, now);\\n  const accountCart = store.activeCartForAccount(account.id);\\n  const messages = [];\\n\\n  if (!accountCart) {\\n    // No cart on the account: the guest cart simply becomes the account's cart.\\n    store.setCartAccount(guestCart.id, account.id, account.email);\\n    messages.push({\\n      level: 'success',\\n      kind: 'signed-in',\\n      message: \`Signed in as \${account.email}. Your cart came with you.\`,\\n    });\\n    return view(store, store.cartById(guestCart.id), { now, messages });\\n  }\\n\\n  if (accountCart.id === guestCart.id) {\\n    return view(store, accountCart, { now, messages: [{ level: 'info', kind: 'signed-in', message: \`Already signed in as \${account.email}.\` }] });\\n  }\\n\\n  const availability = store.availability(accountCart.id, now);\\n  const moved = [];\\n  const bumped = [];\\n  const clamped = [];\\n\\n  for (const gLine of guestCart.lines) {\\n    const variant = VARIANTS.get(gLine.sku);\\n    if (!variant) continue;\\n    const available = availability.get(gLine.sku) ?? 0;\\n    const existing = store.findLine(accountCart.id, gLine.sku);\\n    const target = Math.max(gLine.quantity, existing?.quantity ?? 0);\\n    const finalQty = Math.max(0, Math.min(target, available, MAX_QTY_PER_LINE));\\n    if (finalQty === 0) {\\n      clamped.push(\`\${variant.productTitle} (\${variant.variantLabel}) — out of stock, not carried over\`);\\n      continue;\\n    }\\n    if (finalQty < target) clamped.push(\`\${variant.productTitle} (\${variant.variantLabel}) — only \${finalQty} available\`);\\n    if (existing) {\\n      if (finalQty !== existing.quantity) {\\n        store.updateLineQuantity(accountCart.id, existing.lineId, finalQty);\\n        bumped.push(\`\${variant.productTitle} (\${variant.variantLabel}) x\${finalQty}\`);\\n      }\\n    } else {\\n      store.insertLine(accountCart.id, {\\n        sku: gLine.sku,\\n        quantity: finalQty,\\n        unitPriceMinor: gLine.unitPriceMinorAtAdd,\\n        now,\\n      });\\n      moved.push(\`\${variant.productTitle} (\${variant.variantLabel}) x\${finalQty}\`);\\n    }\\n  }\\n\\n  for (const code of guestCart.couponCodes) store.addCoupon(accountCart.id, code, now);\\n  if (guestCart.destination) store.setDestination(accountCart.id, guestCart.destination);\\n  if (guestCart.shippingMethodId) store.setShippingMethod(accountCart.id, guestCart.shippingMethodId);\\n\\n  store.setCartStatus(guestCart.id, 'merged', accountCart.id);\\n  store.releaseReservations(guestCart.id);\\n\\n  messages.push({\\n    level: 'success',\\n    kind: 'signed-in',\\n    message: \`Signed in as \${account.email}. Your guest cart was merged with the \${guestCart.lines.length === 0 ? 'saved' : 'existing saved'} cart on this account.\`,\\n  });\\n  if (moved.length) messages.push({ level: 'info', kind: 'merge', message: \`Brought over: \${moved.join(', ')}.\` });\\n  if (bumped.length) messages.push({ level: 'info', kind: 'merge', message: \`Quantity updated: \${bumped.join(', ')}.\` });\\n  if (clamped.length) messages.push({ level: 'warning', kind: 'merge', message: \`Stock limited: \${clamped.join('; ')}.\` });\\n\\n  const merged = view(store, store.cartById(accountCart.id), { now, messages });\\n  for (const rejected of merged.receipt.promotions.rejected) {\\n    // A coupon that came across but cannot stack is dropped, loudly.\\n    store.removeCoupon(accountCart.id, rejected.code);\\n  }\\n  if (merged.receipt.promotions.rejected.length) {\\n    const dropped = merged.receipt.promotions.rejected.map((r) => r.reason);\\n    return view(store, store.cartById(accountCart.id), {\\n      now,\\n      messages: [...messages, { level: 'warning', kind: 'merge-coupons', message: dropped.join(' ') }],\\n    });\\n  }\\n  return merged;\\n}\\n\\n// ── checkout ────────────────────────────────────────────────────────────────\\n\\n/**\\n * Step 1 of checkout: re-check availability (stock moves between add and here)\\n * and, only now, take a hold on the stock for RESERVATION_WINDOW_MINUTES.\\n */\\nexport function beginCheckout(store, cart, { now = new Date() } = {}) {\\n  const current = view(store, cart, { now });\\n  if (current.receipt.lineCount === 0) throw new CartError('Your cart is empty.', 409, 'empty_cart');\\n\\n  if (current.receipt.blockers.length > 0) {\\n    return {\\n      ok: false,\\n      reason: 'stock',\\n      view: {\\n        ...current,\\n        messages: [\\n          {\\n            level: 'error',\\n            kind: 'stock-recheck',\\n            message: \`Stock changed while you were shopping: \${current.receipt.blockers.map((b) => b.reason).join(' ')}\`,\\n          },\\n        ],\\n      },\\n    };\\n  }\\n\\n  const priceChanges = current.receipt.lines.filter((l) => l.priceChange);\\n  const hold = store.reserve(\\n    cart.id,\\n    current.receipt.lines.map((l) => ({ sku: l.sku, quantity: l.quantity })),\\n    now,\\n  );\\n\\n  const messages = [\\n    {\\n      level: 'info',\\n      kind: 'reserved',\\n      message: \`Stock held for \${hold.windowMinutes} minutes while you check out.\`,\\n    },\\n  ];\\n  if (priceChanges.length) {\\n    messages.push({\\n      level: 'warning',\\n      kind: 'price-change',\\n      message: \`Prices changed since you added: \${priceChanges\\n        .map((l) => \`\${l.productTitle} \${l.priceChange.was.format()} → \${l.priceChange.now.format()}\`)\\n        .join('; ')}. The totals below are current.\`,\\n    });\\n  }\\n  return { ok: true, hold, view: view(store, store.cartById(cart.id), { now, messages }) };\\n}\\n\\n/**\\n * Step 2: re-check *again* (the hold may have expired, or the customer may have\\n * skipped step 1), decrement stock, write the order, and hand back a fresh cart.\\n */\\nexport function confirmCheckout(store, cart, { now = new Date(), email = null } = {}) {\\n  const current = view(store, cart, { now });\\n  if (current.receipt.lineCount === 0) throw new CartError('Your cart is empty.', 409, 'empty_cart');\\n\\n  const hold = store.activeReservation(cart.id, now);\\n  if (!hold) {\\n    // Either checkout was never begun or the window closed. Re-check and re-hold.\\n    const restart = beginCheckout(store, cart, { now });\\n    if (!restart.ok) return { ok: false, reason: restart.reason, view: restart.view };\\n  }\\n\\n  const recheck = view(store, store.cartById(cart.id), { now });\\n  if (recheck.receipt.blockers.length > 0) {\\n    store.releaseReservations(cart.id);\\n    return {\\n      ok: false,\\n      reason: 'stock',\\n      view: {\\n        ...recheck,\\n        messages: [\\n          {\\n            level: 'error',\\n            kind: 'stock-recheck',\\n            message: \`Stock changed before payment: \${recheck.receipt.blockers.map((b) => b.reason).join(' ')} Nothing has been charged.\`,\\n          },\\n        ],\\n      },\\n    };\\n  }\\n\\n  const items = recheck.receipt.lines.map((l) => ({ sku: l.sku, quantity: l.quantity }));\\n  store.decrementStock(items);\\n  store.consumeReservations(cart.id);\\n\\n  const orderId = store.recordOrder({\\n    cartId: cart.id,\\n    accountId: cart.accountId,\\n    email: email ?? cart.email,\\n    receipt: JSON.parse(JSON.stringify(recheck.receipt)),\\n    totalMinor: recheck.receipt.totals.grandTotal.minor,\\n    currency: recheck.receipt.currency,\\n    now,\\n  });\\n  store.setCartStatus(cart.id, 'ordered');\\n\\n  const fresh = store.createCart({ accountId: cart.accountId, email: email ?? cart.email, now });\\n  if (cart.destination) store.setDestination(fresh.id, cart.destination);\\n\\n  return {\\n    ok: true,\\n    orderId,\\n    order: store.orderById(orderId),\\n    view: view(store, store.cartById(fresh.id), {\\n      now,\\n      messages: [\\n        {\\n          level: 'success',\\n          kind: 'ordered',\\n          message: \`Order \${orderId} placed — \${recheck.receipt.totals.grandTotal.format()}. Your cart is empty again.\`,\\n        },\\n      ],\\n    }),\\n  };\\n}\\n"},{"path":"src/catalog.js","bytes":7100,"text":"/**\\n * The catalogue: products, their variants (each variant is a distinct SKU) and\\n * the seed stock levels.\\n *\\n * A *variant* is a concrete buyable thing: \\"Harbour Tee, size M, colour Slate\\".\\n * Two variants of the same product are different SKUs and therefore different\\n * cart lines — never merged. Two adds of the *same* SKU merge into one line.\\n *\\n * Prices are decimal strings and are parsed into integer minor units on load,\\n * so no price ever exists as a float.\\n */\\n\\n/** Tax classes. The tax engine maps (destination, class) -> rate. */\\nexport const PRODUCT_CLASS = {\\n  STANDARD: 'standard',\\n  APPAREL: 'apparel',\\n  CHILDRENS_APPAREL: 'childrens_apparel',\\n  BOOK: 'book',\\n  GROCERY: 'grocery',\\n  DIGITAL: 'digital',\\n};\\n\\nexport const CATALOG_CURRENCY = 'USD';\\n\\n/**\\n * Seed data. \`price\` is a decimal string in CATALOG_CURRENCY.\\n * \`weightGrams\` feeds the shipping estimate. \`stock\` is the on-hand count.\\n */\\nexport const PRODUCTS = [\\n  {\\n    id: 'harbour-tee',\\n    title: 'Harbour Tee',\\n    brand: 'Northline',\\n    description: 'Heavyweight cotton tee, garment dyed.',\\n    productClass: PRODUCT_CLASS.APPAREL,\\n    options: ['size', 'colour'],\\n    variants: [\\n      { sku: 'TEE-S-SLATE', price: '24.00', weightGrams: 220, stock: 12, options: { size: 'S', colour: 'Slate' }, swatch: '#5a6672' },\\n      { sku: 'TEE-M-SLATE', price: '24.00', weightGrams: 235, stock: 8, options: { size: 'M', colour: 'Slate' }, swatch: '#5a6672' },\\n      { sku: 'TEE-L-SLATE', price: '24.00', weightGrams: 250, stock: 3, options: { size: 'L', colour: 'Slate' }, swatch: '#5a6672' },\\n      { sku: 'TEE-M-RUST', price: '26.50', weightGrams: 235, stock: 5, options: { size: 'M', colour: 'Rust' }, swatch: '#b4552f' },\\n      { sku: 'TEE-L-RUST', price: '26.50', weightGrams: 250, stock: 0, options: { size: 'L', colour: 'Rust' }, swatch: '#b4552f' },\\n    ],\\n  },\\n  {\\n    id: 'field-jacket',\\n    title: 'Field Jacket',\\n    brand: 'Northline',\\n    description: 'Waxed canvas, four pockets, storm cuffs.',\\n    productClass: PRODUCT_CLASS.APPAREL,\\n    options: ['size', 'colour'],\\n    variants: [\\n      { sku: 'JKT-M-OLIVE', price: '189.00', weightGrams: 1400, stock: 4, options: { size: 'M', colour: 'Olive' }, swatch: '#5c6141' },\\n      { sku: 'JKT-L-OLIVE', price: '189.00', weightGrams: 1500, stock: 2, options: { size: 'L', colour: 'Olive' }, swatch: '#5c6141' },\\n      { sku: 'JKT-M-NAVY', price: '189.00', weightGrams: 1400, stock: 1, options: { size: 'M', colour: 'Navy' }, swatch: '#2c3a52' },\\n    ],\\n  },\\n  {\\n    id: 'kids-rain-mac',\\n    title: \\"Kids' Rain Mac\\",\\n    brand: 'Northline',\\n    description: 'Seam-sealed, reflective piping, ages 5-10.',\\n    productClass: PRODUCT_CLASS.CHILDRENS_APPAREL,\\n    options: ['size', 'colour'],\\n    variants: [\\n      { sku: 'KID-6-YELLOW', price: '42.00', weightGrams: 400, stock: 9, options: { size: '5-6y', colour: 'Yellow' }, swatch: '#e0b23c' },\\n      { sku: 'KID-8-YELLOW', price: '44.00', weightGrams: 430, stock: 6, options: { size: '7-8y', colour: 'Yellow' }, swatch: '#e0b23c' },\\n    ],\\n  },\\n  {\\n    id: 'atlas-of-tides',\\n    title: 'The Atlas of Tides',\\n    brand: 'Cormorant Press',\\n    description: 'Hardback, 320 pages, 60 charts.',\\n    productClass: PRODUCT_CLASS.BOOK,\\n    options: ['format'],\\n    variants: [\\n      { sku: 'BOOK-TIDES-HB', price: '32.00', weightGrams: 900, stock: 15, options: { format: 'Hardback' }, swatch: '#3f5d6b' },\\n      { sku: 'BOOK-TIDES-PB', price: '18.00', weightGrams: 380, stock: 22, options: { format: 'Paperback' }, swatch: '#7c94a1' },\\n    ],\\n  },\\n  {\\n    id: 'sea-salt-caramels',\\n    title: 'Sea Salt Caramels',\\n    brand: 'Quay Confectionery',\\n    description: 'Box of 24, made in small batches.',\\n    productClass: PRODUCT_CLASS.GROCERY,\\n    options: ['size'],\\n    variants: [\\n      { sku: 'CAR-BOX24', price: '14.50', weightGrams: 500, stock: 30, options: { size: 'Box of 24' }, swatch: '#a9743f' },\\n    ],\\n  },\\n  {\\n    id: 'tide-tables-app',\\n    title: 'Tide Tables (digital)',\\n    brand: 'Cormorant Press',\\n    description: 'Downloadable tide tables, ten-year almanac.',\\n    productClass: PRODUCT_CLASS.DIGITAL,\\n    options: ['licence'],\\n    variants: [\\n      { sku: 'DIG-TIDES-1Y', price: '9.00', weightGrams: 0, stock: 999, options: { licence: '1 year' }, swatch: '#4a6f8a' },\\n    ],\\n  },\\n];\\n\\n/** SKU -> { ...variant, product fields } */\\nexport function buildVariantIndex(products = PRODUCTS) {\\n  const index = new Map();\\n  for (const p of products) {\\n    for (const v of p.variants) {\\n      index.set(v.sku, {\\n        sku: v.sku,\\n        productId: p.id,\\n        productTitle: p.title,\\n        brand: p.brand,\\n        description: p.description,\\n        productClass: p.productClass,\\n        optionNames: p.options,\\n        options: v.options,\\n        variantLabel: p.options.map((o) => \`\${o}: \${v.options[o]}\`).join(' · '),\\n        priceDecimal: v.price,\\n        weightGrams: v.weightGrams,\\n        swatch: v.swatch,\\n        seedStock: v.stock,\\n        imageUrl: \`/img/\${v.sku}.svg\`,\\n        isDigital: p.productClass === PRODUCT_CLASS.DIGITAL,\\n      });\\n    }\\n  }\\n  return index;\\n}\\n\\nexport const VARIANTS = buildVariantIndex();\\n\\n/**\\n * Change a variant's price at runtime (the demo \\"the shop repriced this\\" button;\\n * a real shop would get this from the merchandising system). The change is\\n * persisted by the store, and carts pick it up on their next recompute — which\\n * is every read, so a cart that is open at the time sees it immediately.\\n */\\nexport function setVariantPrice(sku, priceDecimal) {\\n  const v = VARIANTS.get(sku);\\n  if (!v) return false;\\n  v.priceDecimal = priceDecimal;\\n  for (const p of PRODUCTS) {\\n    const raw = p.variants.find((x) => x.sku === sku);\\n    if (raw) raw.price = priceDecimal;\\n  }\\n  return true;\\n}\\n\\n/**\\n * Product images. Rather than ship binaries we render a deterministic SVG per\\n * SKU from its colour swatch, so every line item really does have an image.\\n */\\nexport function variantImageSvg(sku) {\\n  const v = VARIANTS.get(sku);\\n  const swatch = v?.swatch ?? '#8a8a8a';\\n  const label = v ? v.productTitle : 'Unknown';\\n  const sub = v ? Object.values(v.options).join(' / ') : sku;\\n  const esc = (s) => String(s).replace(/[&<>\\"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\\"': '&quot;' })[c]);\\n  return \`<svg xmlns=\\"http://www.w3.org/2000/svg\\" viewBox=\\"0 0 200 200\\" role=\\"img\\" aria-label=\\"\${esc(label)} \${esc(sub)}\\">\\n  <defs>\\n    <linearGradient id=\\"g\\" x1=\\"0\\" y1=\\"0\\" x2=\\"1\\" y2=\\"1\\">\\n      <stop offset=\\"0%\\" stop-color=\\"\${swatch}\\" stop-opacity=\\"0.95\\"/>\\n      <stop offset=\\"100%\\" stop-color=\\"\${swatch}\\" stop-opacity=\\"0.55\\"/>\\n    </linearGradient>\\n  </defs>\\n  <rect width=\\"200\\" height=\\"200\\" fill=\\"url(#g)\\"/>\\n  <circle cx=\\"150\\" cy=\\"52\\" r=\\"34\\" fill=\\"#ffffff\\" fill-opacity=\\"0.16\\"/>\\n  <rect x=\\"0\\" y=\\"140\\" width=\\"200\\" height=\\"60\\" fill=\\"#0d1117\\" fill-opacity=\\"0.55\\"/>\\n  <text x=\\"14\\" y=\\"164\\" font-family=\\"ui-sans-serif,system-ui,sans-serif\\" font-size=\\"15\\" fill=\\"#ffffff\\">\${esc(label.slice(0, 20))}</text>\\n  <text x=\\"14\\" y=\\"184\\" font-family=\\"ui-sans-serif,system-ui,sans-serif\\" font-size=\\"12\\" fill=\\"#ffffff\\" fill-opacity=\\"0.8\\">\${esc(sub.slice(0, 26))}</text>\\n</svg>\`;\\n}\\n"},{"path":"src/money.js","bytes":7004,"text":"/**\\n * Money.\\n *\\n * RULES (also stated in README.md — keep the two in sync):\\n *  1. Money is *never* a float. Every amount is an integer number of minor units\\n *     (cents/pence) carried in a plain JS number. JS integers are exact up to\\n *     2^53-1, which is ~90 trillion dollars, so no precision is lost.\\n *  2. A cart has exactly one currency. Mixing currencies throws.\\n *  3. Rounding is half-up on the absolute value (\\"round half away from zero\\"),\\n *     which is what invoices and tax authorities expect for positive amounts.\\n *  4. Percentage maths (tax, percent-off coupons) is done on integer minor units\\n *     and rounded once, at the point the amount becomes a line on the receipt.\\n *  5. When one rounded amount has to be split across several lines (an order-level\\n *     discount, say) we use largest-remainder allocation so the parts always sum\\n *     back to the whole — no stray cent.\\n */\\n\\nexport const CURRENCIES = {\\n  USD: { code: 'USD', exponent: 2, symbol: '$', locale: 'en-US' },\\n  GBP: { code: 'GBP', exponent: 2, symbol: '£', locale: 'en-GB' },\\n  EUR: { code: 'EUR', exponent: 2, symbol: '€', locale: 'de-DE' },\\n  JPY: { code: 'JPY', exponent: 0, symbol: '¥', locale: 'ja-JP' },\\n};\\n\\nexport class MoneyError extends Error {}\\n\\n/** A money amount: integer minor units + currency code. Immutable. */\\nexport class Money {\\n  constructor(minor, currency = 'USD') {\\n    if (!Number.isInteger(minor)) {\\n      throw new MoneyError(\`Money must be whole minor units, got \${minor}\`);\\n    }\\n    if (!CURRENCIES[currency]) throw new MoneyError(\`Unknown currency \${currency}\`);\\n    this.minor = minor;\\n    this.currency = currency;\\n    Object.freeze(this);\\n  }\\n\\n  static zero(currency = 'USD') {\\n    return new Money(0, currency);\\n  }\\n\\n  /** From a major-unit decimal *string* (\\"12.99\\"). Strings only — never a float. */\\n  static parse(text, currency = 'USD') {\\n    const spec = CURRENCIES[currency];\\n    if (!spec) throw new MoneyError(\`Unknown currency \${currency}\`);\\n    const m = /^(-)?(\\\\d+)(?:\\\\.(\\\\d+))?$/.exec(String(text).trim());\\n    if (!m) throw new MoneyError(\`Cannot parse money: \${text}\`);\\n    const [, sign, whole, frac = ''] = m;\\n    if (frac.length > spec.exponent) {\\n      throw new MoneyError(\`\${text} has more precision than \${currency} allows\`);\\n    }\\n    const padded = frac.padEnd(spec.exponent, '0');\\n    const minor = Number(whole) * 10 ** spec.exponent + Number(padded || '0');\\n    return new Money(sign ? -minor : minor, currency);\\n  }\\n\\n  #same(other) {\\n    if (this.currency !== other.currency) {\\n      throw new MoneyError(\`Currency mismatch: \${this.currency} vs \${other.currency}\`);\\n    }\\n  }\\n\\n  plus(other) {\\n    this.#same(other);\\n    return new Money(this.minor + other.minor, this.currency);\\n  }\\n\\n  minus(other) {\\n    this.#same(other);\\n    return new Money(this.minor - other.minor, this.currency);\\n  }\\n\\n  /** Multiply by an exact integer (a quantity). No rounding needed. */\\n  times(n) {\\n    if (!Number.isInteger(n)) throw new MoneyError(\`times() takes an integer, got \${n}\`);\\n    return new Money(this.minor * n, this.currency);\\n  }\\n\\n  /**\\n   * Scale by a rational number given as numerator/denominator, rounded half-up.\\n   * Rates are passed as integer basis points elsewhere so this stays exact.\\n   */\\n  scale(numerator, denominator) {\\n    if (!Number.isInteger(numerator) || !Number.isInteger(denominator)) {\\n      throw new MoneyError('scale() takes integers');\\n    }\\n    if (denominator === 0) throw new MoneyError('scale() denominator is zero');\\n    return new Money(roundHalfUp(this.minor * numerator, denominator), this.currency);\\n  }\\n\\n  /** Percentage in basis points: 2000 bps = 20%. */\\n  percentBps(bps) {\\n    return this.scale(bps, 10_000);\\n  }\\n\\n  negate() {\\n    return new Money(-this.minor, this.currency);\\n  }\\n\\n  /** Clamp to >= 0. Discounts must never make a line negative. */\\n  clampAtZero() {\\n    return this.minor < 0 ? Money.zero(this.currency) : this;\\n  }\\n\\n  isZero() {\\n    return this.minor === 0;\\n  }\\n\\n  isNegative() {\\n    return this.minor < 0;\\n  }\\n\\n  lessThan(other) {\\n    this.#same(other);\\n    return this.minor < other.minor;\\n  }\\n\\n  atLeast(other) {\\n    this.#same(other);\\n    return this.minor >= other.minor;\\n  }\\n\\n  equals(other) {\\n    return other instanceof Money && this.minor === other.minor && this.currency === other.currency;\\n  }\\n\\n  /** Plain decimal string, e.g. \\"1234.05\\". Safe for JSON and for re-parsing. */\\n  toDecimalString() {\\n    const { exponent } = CURRENCIES[this.currency];\\n    const sign = this.minor < 0 ? '-' : '';\\n    const abs = String(Math.abs(this.minor)).padStart(exponent + 1, '0');\\n    if (exponent === 0) return sign + abs;\\n    return \`\${sign}\${abs.slice(0, -exponent)}.\${abs.slice(-exponent)}\`;\\n  }\\n\\n  /** Display string, e.g. \\"$1,234.05\\". */\\n  format() {\\n    const spec = CURRENCIES[this.currency];\\n    return new Intl.NumberFormat(spec.locale, {\\n      style: 'currency',\\n      currency: this.currency,\\n      minimumFractionDigits: spec.exponent,\\n      maximumFractionDigits: spec.exponent,\\n    }).format(this.minor / 10 ** spec.exponent);\\n  }\\n\\n  /** The wire shape. Clients get the exact integer *and* pre-formatted text. */\\n  toJSON() {\\n    return {\\n      minor: this.minor,\\n      currency: this.currency,\\n      decimal: this.toDecimalString(),\\n      display: this.format(),\\n    };\\n  }\\n}\\n\\n/** Round a rational n/d to the nearest integer, halves away from zero. */\\nexport function roundHalfUp(n, d) {\\n  if (d < 0) {\\n    n = -n;\\n    d = -d;\\n  }\\n  const negative = n < 0;\\n  const abs = Math.abs(n);\\n  const q = Math.floor(abs / d);\\n  const rem = abs - q * d;\\n  const rounded = rem * 2 >= d ? q + 1 : q;\\n  return negative ? -rounded : rounded;\\n}\\n\\nexport function sum(amounts, currency = 'USD') {\\n  return amounts.reduce((acc, m) => acc.plus(m), Money.zero(currency));\\n}\\n\\n/**\\n * Split \`total\` across \`weights\` so the parts sum *exactly* back to \`total\`.\\n * Largest-remainder method: floor everything, then hand out the leftover minor\\n * units to the entries with the biggest fractional part (ties -> lowest index).\\n */\\nexport function allocate(total, weights) {\\n  const currency = total.currency;\\n  const n = weights.length;\\n  if (n === 0) return [];\\n  const weightSum = weights.reduce((a, b) => a + b, 0);\\n  if (weightSum <= 0) {\\n    // Nothing to weight by: everything lands on the first slot.\\n    return weights.map((_, i) => (i === 0 ? total : Money.zero(currency)));\\n  }\\n  const sign = total.minor < 0 ? -1 : 1;\\n  const abs = Math.abs(total.minor);\\n  const parts = [];\\n  let handedOut = 0;\\n  for (let i = 0; i < n; i++) {\\n    const exact = abs * weights[i];\\n    const floor = Math.floor(exact / weightSum);\\n    parts.push({ i, floor, remainder: exact - floor * weightSum });\\n    handedOut += floor;\\n  }\\n  let leftover = abs - handedOut;\\n  const order = [...parts].sort((a, b) => b.remainder - a.remainder || a.i - b.i);\\n  for (const p of order) {\\n    if (leftover <= 0) break;\\n    p.floor += 1;\\n    leftover -= 1;\\n  }\\n  return parts.map((p) => new Money(sign * p.floor, currency));\\n}\\n"},{"path":"src/pricing.js","bytes":11084,"text":"/**\\n * The pricing engine: one pure function from cart state to a full receipt.\\n *\\n * Nothing here is stored. \`price()\` is called on every read and every mutation,\\n * so a total can never go stale: if the catalogue price moved, or stock moved, or\\n * a coupon stopped qualifying, the next recompute says so.\\n *\\n * Order of operations (fixed, and printed in the README):\\n *   1. line subtotal   = current unit price x quantity      (exact integers)\\n *   2. cart subtotal   = sum of line subtotals\\n *   3. discounts       = item-scope coupons, then order-scope, allocated to lines\\n *   4. merchandise net = subtotal - discounts\\n *   5. shipping        = quote(destination, weight, merchandise net, method)\\n *                        then any shipping-scope coupon\\n *   6. tax             = per line on its net amount at rate(destination, class),\\n *                        plus tax on the net shipping charge where taxable\\n *   7. grand total     = merchandise net + shipping net + tax\\n */\\n\\nimport { Money, sum } from './money.js';\\nimport { VARIANTS, CATALOG_CURRENCY } from './catalog.js';\\nimport { jurisdictionFor, rateFor, shippingRateFor, formatBps } from './tax.js';\\nimport { quote, quoteAll, DEFAULT_METHOD } from './shipping.js';\\nimport { evaluatePromotions, applyShippingDiscount, findCoupon } from './promotions.js';\\n\\nexport const CURRENCY_RULES = {\\n  currency: CATALOG_CURRENCY,\\n  minorUnitsPerMajor: 100,\\n  representation: 'integer minor units (cents); never a binary float',\\n  rounding: 'half-up (away from zero), applied once per receipt line',\\n  allocation: 'largest-remainder, so split discounts sum back exactly',\\n  display: 'Intl.NumberFormat, en-US, 2 decimal places',\\n};\\n\\n/**\\n * @param {object} cart  { lines, destination, shippingMethodId, couponCodes, customer }\\n * @param {object} [opts] { availability: Map<sku, number>, now: Date }\\n */\\nexport function price(cart, opts = {}) {\\n  const currency = CATALOG_CURRENCY;\\n  const now = opts.now ?? new Date();\\n  const availability = opts.availability ?? new Map();\\n  const notices = [];\\n\\n  // ── 1. Lines ──────────────────────────────────────────────────────────────\\n  const priced = [];\\n  for (const line of cart.lines) {\\n    const v = VARIANTS.get(line.sku);\\n    if (!v) {\\n      notices.push({\\n        level: 'error',\\n        kind: 'discontinued',\\n        lineId: line.lineId,\\n        message: \`\${line.sku} is no longer sold and has been left out of the totals.\`,\\n      });\\n      continue;\\n    }\\n    const unitPrice = Money.parse(v.priceDecimal, currency);\\n    const quantity = line.quantity;\\n    const lineSubtotal = unitPrice.times(quantity);\\n\\n    const available = availability.has(v.sku) ? availability.get(v.sku) : v.seedStock;\\n    const lineNotices = [];\\n\\n    // Price change since the item was added — surfaced, never silently absorbed.\\n    let priceChange = null;\\n    if (Number.isInteger(line.unitPriceMinorAtAdd) && line.unitPriceMinorAtAdd !== unitPrice.minor) {\\n      const was = new Money(line.unitPriceMinorAtAdd, currency);\\n      priceChange = { was, now: unitPrice, direction: unitPrice.minor > was.minor ? 'up' : 'down' };\\n      lineNotices.push({\\n        level: unitPrice.minor > was.minor ? 'warning' : 'info',\\n        kind: 'price-change',\\n        message:\\n          unitPrice.minor > was.minor\\n            ? \`Price went up from \${was.format()} to \${unitPrice.format()} since you added this.\`\\n            : \`Good news — price dropped from \${was.format()} to \${unitPrice.format()}.\`,\\n      });\\n    }\\n\\n    // Stock, checked here on every read as well as at add and at checkout.\\n    let stockState = 'in_stock';\\n    if (available <= 0) {\\n      stockState = 'out_of_stock';\\n      lineNotices.push({\\n        level: 'error',\\n        kind: 'out-of-stock',\\n        message: 'Out of stock. Remove it to check out.',\\n      });\\n    } else if (available < quantity) {\\n      stockState = 'partial';\\n      lineNotices.push({\\n        level: 'error',\\n        kind: 'insufficient-stock',\\n        message: \`Only \${available} left — reduce the quantity to check out.\`,\\n      });\\n    } else if (available <= 3) {\\n      stockState = 'low';\\n      lineNotices.push({ level: 'info', kind: 'low-stock', message: \`Only \${available} left.\` });\\n    }\\n\\n    priced.push({\\n      lineId: line.lineId,\\n      sku: v.sku,\\n      productId: v.productId,\\n      productTitle: v.productTitle,\\n      brand: v.brand,\\n      productClass: v.productClass,\\n      variantLabel: v.variantLabel,\\n      options: v.options,\\n      imageUrl: v.imageUrl,\\n      isDigital: v.isDigital,\\n      weightGrams: v.weightGrams,\\n      quantity,\\n      unitPrice,\\n      lineSubtotal,\\n      available,\\n      stockState,\\n      priceChange,\\n      notices: lineNotices,\\n      addedAt: line.addedAt,\\n    });\\n  }\\n\\n  // ── 2. Subtotal ───────────────────────────────────────────────────────────\\n  const subtotal = sum(priced.map((l) => l.lineSubtotal), currency);\\n  const hasPhysical = priced.some((l) => !l.isDigital);\\n  const allDigital = priced.length > 0 && !hasPhysical;\\n\\n  // ── 3. Promotions ─────────────────────────────────────────────────────────\\n  const customer = cart.customer ?? { isNewCustomer: true, accountId: null };\\n  const promo = evaluatePromotions(cart.couponCodes ?? [], {\\n    currency,\\n    lines: priced,\\n    customer,\\n    now,\\n    hasPhysical,\\n  });\\n\\n  for (const l of priced) {\\n    l.discount = promo.lineDiscounts.get(l.lineId) ?? Money.zero(currency);\\n    l.lineTotal = l.lineSubtotal.minus(l.discount).clampAtZero();\\n  }\\n\\n  const itemDiscountTotal = sum(priced.map((l) => l.discount), currency);\\n  const merchandiseTotal = subtotal.minus(itemDiscountTotal).clampAtZero();\\n\\n  // ── 4/5. Shipping ─────────────────────────────────────────────────────────\\n  const weightGrams = priced.reduce((g, l) => g + l.weightGrams * l.quantity, 0);\\n  const methodId = cart.shippingMethodId ?? DEFAULT_METHOD;\\n  const shipArgs = {\\n    destination: cart.destination,\\n    weightGrams,\\n    merchandiseTotal,\\n    allDigital,\\n    currency,\\n  };\\n  const shippingQuote = priced.length === 0\\n    ? { amount: Money.zero(currency), methodId, label: '—', eta: '—', reason: 'Cart is empty.', quotable: true, freeThreshold: null }\\n    : quote({ ...shipArgs, methodId });\\n\\n  const shipDiscount = applyShippingDiscount(promo.shippingCoupon, shippingQuote, currency);\\n  if (promo.shippingCoupon) {\\n    if (shipDiscount.note) {\\n      promo.rejected.push({ code: promo.shippingCoupon.code, reason: shipDiscount.note });\\n    } else {\\n      promo.applied.push({\\n        code: promo.shippingCoupon.code,\\n        label: promo.shippingCoupon.label,\\n        scope: promo.shippingCoupon.scope,\\n        exclusive: promo.shippingCoupon.exclusive,\\n        terms: promo.shippingCoupon.terms,\\n        amount: shipDiscount.discount,\\n      });\\n    }\\n  }\\n  const shippingNet = shippingQuote.amount.minus(shipDiscount.discount).clampAtZero();\\n\\n  // ── 6. Tax ────────────────────────────────────────────────────────────────\\n  const jurisdiction = jurisdictionFor(cart.destination);\\n  const taxBands = new Map();\\n  let taxTotal = Money.zero(currency);\\n\\n  for (const l of priced) {\\n    const bps = rateFor(jurisdiction, l.productClass, l.unitPrice.minor);\\n    const taxable = l.lineTotal;\\n    const taxAmount = taxable.percentBps(bps);\\n    l.taxRateBps = bps;\\n    l.tax = taxAmount;\\n    taxTotal = taxTotal.plus(taxAmount);\\n    if (!taxable.isZero() || bps > 0) addBand(taxBands, bps, taxable, taxAmount, currency);\\n  }\\n\\n  const shippingTaxBps = shippingRateFor(jurisdiction);\\n  const shippingTax = shippingNet.percentBps(shippingTaxBps);\\n  if (!shippingTax.isZero()) {\\n    taxTotal = taxTotal.plus(shippingTax);\\n    addBand(taxBands, shippingTaxBps, shippingNet, shippingTax, currency);\\n  }\\n\\n  if (!jurisdiction && priced.length > 0) {\\n    notices.push({\\n      level: 'info',\\n      kind: 'no-destination',\\n      message: 'Tax and shipping are estimated once you pick a destination.',\\n    });\\n  }\\n\\n  // ── 7. Grand total ────────────────────────────────────────────────────────\\n  const grandTotal = merchandiseTotal.plus(shippingNet).plus(taxTotal);\\n  const savings = itemDiscountTotal.plus(shipDiscount.discount);\\n\\n  const blockers = [];\\n  for (const l of priced) {\\n    if (l.stockState === 'out_of_stock' || l.stockState === 'partial') {\\n      blockers.push({ lineId: l.lineId, sku: l.sku, reason: l.notices.find((n) => n.level === 'error').message });\\n    }\\n  }\\n\\n  return {\\n    currency,\\n    currencyRules: CURRENCY_RULES,\\n    lines: priced,\\n    itemCount: priced.reduce((n, l) => n + l.quantity, 0),\\n    lineCount: priced.length,\\n    totals: {\\n      subtotal,\\n      discountTotal: itemDiscountTotal,\\n      merchandiseTotal,\\n      shipping: shippingQuote.amount,\\n      shippingDiscount: shipDiscount.discount,\\n      shippingNet,\\n      tax: taxTotal,\\n      grandTotal,\\n      savings,\\n    },\\n    shipping: {\\n      methodId: shippingQuote.methodId,\\n      label: shippingQuote.label,\\n      eta: shippingQuote.eta,\\n      reason: shippingQuote.reason,\\n      quotable: shippingQuote.quotable,\\n      amount: shippingQuote.amount,\\n      discount: shipDiscount.discount,\\n      net: shippingNet,\\n      weightGrams,\\n      options: priced.length === 0 ? [] : quoteAll(shipArgs),\\n      estimateOnly: true,\\n    },\\n    tax: {\\n      jurisdiction: jurisdiction\\n        ? { key: jurisdiction.key, label: jurisdiction.label, name: jurisdiction.name }\\n        : null,\\n      total: taxTotal,\\n      shippingTaxed: !shippingTax.isZero(),\\n      bands: [...taxBands.values()].map((b) => ({\\n        rateBps: b.rateBps,\\n        rateLabel: formatBps(b.rateBps),\\n        taxableBase: b.base,\\n        amount: b.amount,\\n      })),\\n    },\\n    promotions: {\\n      applied: promo.applied,\\n      rejected: promo.rejected,\\n      activeCodes: promo.applied.map((a) => a.code),\\n    },\\n    notices,\\n    blockers,\\n    checkoutReady: priced.length > 0 && blockers.length === 0,\\n  };\\n}\\n\\nfunction addBand(bands, rateBps, base, amount, currency) {\\n  const key = String(rateBps);\\n  const existing = bands.get(key) ?? { rateBps, base: Money.zero(currency), amount: Money.zero(currency) };\\n  existing.base = existing.base.plus(base);\\n  existing.amount = existing.amount.plus(amount);\\n  bands.set(key, existing);\\n}\\n\\n/** Wire shape for the browser. Money instances serialise via toJSON(). */\\nexport function toJSON(receipt) {\\n  return JSON.parse(JSON.stringify(receipt));\\n}\\n\\nexport { findCoupon };\\n"},{"path":"src/promotions.js","bytes":13122,"text":"/**\\n * Coupons, eligibility, and the stacking policy.\\n *\\n * ── STACKING POLICY (the rule the shop actually enforces) ────────────────────\\n *  1. A coupon belongs to exactly one scope: ITEM, ORDER or SHIPPING.\\n *  2. At most one coupon per scope may be active. Applying a second coupon in a\\n *     scope is refused with a message naming the coupon already holding it.\\n *  3. Scopes stack with each other: ITEM + ORDER + SHIPPING can all be live at\\n *     once (max three coupons).\\n *  4. A coupon marked \`exclusive\` is the only coupon allowed on the cart. It\\n *     cannot be added while another coupon is applied, and no other coupon can\\n *     be added while it is applied.\\n *  5. Application order is fixed and independent of the order the customer typed\\n *     the codes in: ITEM first, then ORDER on the item-discounted amount, then\\n *     SHIPPING on the shipping quote.\\n *  6. A discount can never push a line, or the shipping charge, below zero.\\n *  7. Eligibility is re-checked on every recompute. A coupon that stops\\n *     qualifying (cart dropped below the minimum, its items were removed) is\\n *     deactivated and reported, not silently kept or silently dropped.\\n * ─────────────────────────────────────────────────────────────────────────────\\n */\\n\\nimport { Money, allocate, sum } from './money.js';\\nimport { PRODUCT_CLASS } from './catalog.js';\\n\\nexport const SCOPE = { ITEM: 'item', ORDER: 'order', SHIPPING: 'shipping' };\\n\\n/**\\n * benefit kinds:\\n *   percent            { bps }                 – % off the scope's base\\n *   amountOff          { amount }              – fixed money off the scope's base\\n *   amountOffPerUnit   { amount }              – fixed money off each matching unit\\n *   freeShipping       { methods? }            – shipping to zero (optionally only some methods)\\n */\\nexport const COUPONS = [\\n  {\\n    code: 'WELCOME10',\\n    label: '10% off your first order',\\n    scope: SCOPE.ORDER,\\n    exclusive: false,\\n    benefit: { kind: 'percent', bps: 1000 },\\n    eligibility: {\\n      minSubtotal: '50.00',\\n      newCustomersOnly: true,\\n      excludeClasses: [PRODUCT_CLASS.DIGITAL],\\n    },\\n    terms: 'First order only. Minimum $50 of merchandise. Does not apply to digital goods.',\\n  },\\n  {\\n    code: 'SAVE15',\\n    label: '15% off everything',\\n    scope: SCOPE.ORDER,\\n    exclusive: true,\\n    benefit: { kind: 'percent', bps: 1500 },\\n    eligibility: { minSubtotal: '100.00' },\\n    terms: 'Minimum $100 of merchandise. Cannot be combined with any other offer.',\\n  },\\n  {\\n    code: 'TENOFF',\\n    label: '$10 off orders over $80',\\n    scope: SCOPE.ORDER,\\n    exclusive: false,\\n    benefit: { kind: 'amountOff', amount: '10.00' },\\n    eligibility: { minSubtotal: '80.00' },\\n    terms: 'Minimum $80 of merchandise.',\\n  },\\n  {\\n    code: 'BOOKS20',\\n    label: '20% off books',\\n    scope: SCOPE.ITEM,\\n    exclusive: false,\\n    benefit: { kind: 'percent', bps: 2000 },\\n    eligibility: { productClasses: [PRODUCT_CLASS.BOOK] },\\n    terms: 'Applies to books only.',\\n  },\\n  {\\n    code: 'TEE5',\\n    label: '$5 off each Harbour Tee',\\n    scope: SCOPE.ITEM,\\n    exclusive: false,\\n    benefit: { kind: 'amountOffPerUnit', amount: '5.00' },\\n    eligibility: { productIds: ['harbour-tee'] },\\n    terms: 'Applies to each Harbour Tee in the cart.',\\n  },\\n  {\\n    code: 'FREESHIP',\\n    label: 'Free standard shipping',\\n    scope: SCOPE.SHIPPING,\\n    exclusive: false,\\n    benefit: { kind: 'freeShipping', methods: ['standard'] },\\n    eligibility: { minSubtotal: '60.00', requiresPhysical: true },\\n    terms: 'Standard shipping only. Minimum $60 of merchandise. Physical goods only.',\\n  },\\n  {\\n    code: 'SHIPHALF',\\n    label: 'Half-price shipping, any method',\\n    scope: SCOPE.SHIPPING,\\n    exclusive: false,\\n    benefit: { kind: 'percent', bps: 5000 },\\n    eligibility: { requiresPhysical: true },\\n    terms: 'Applies to whichever shipping method you choose. Physical goods only.',\\n  },\\n  {\\n    code: 'SPRING24',\\n    label: '25% off (expired)',\\n    scope: SCOPE.ORDER,\\n    exclusive: false,\\n    benefit: { kind: 'percent', bps: 2500 },\\n    eligibility: { expiresAt: '2024-06-30T23:59:59.000Z' },\\n    terms: 'Expired 30 June 2024. Kept in the catalogue so expiry is demonstrable.',\\n  },\\n];\\n\\nconst BY_CODE = new Map(COUPONS.map((c) => [c.code, c]));\\n\\nexport function findCoupon(code) {\\n  return BY_CODE.get(String(code ?? '').trim().toUpperCase()) ?? null;\\n}\\n\\nexport function publicCoupons() {\\n  return COUPONS.map((c) => ({\\n    code: c.code,\\n    label: c.label,\\n    scope: c.scope,\\n    exclusive: c.exclusive,\\n    terms: c.terms,\\n  }));\\n}\\n\\n/** Does this line match the coupon's item filters? */\\nfunction lineMatches(coupon, line) {\\n  const e = coupon.eligibility ?? {};\\n  if (e.productClasses && !e.productClasses.includes(line.productClass)) return false;\\n  if (e.productIds && !e.productIds.includes(line.productId)) return false;\\n  if (e.skus && !e.skus.includes(line.sku)) return false;\\n  if (e.excludeClasses && e.excludeClasses.includes(line.productClass)) return false;\\n  return true;\\n}\\n\\n/**\\n * Check a coupon on its own terms (ignoring stacking).\\n * @returns {{ok: true} | {ok: false, reason: string}}\\n */\\nexport function checkEligibility(coupon, ctx) {\\n  const e = coupon.eligibility ?? {};\\n  const { currency, lines, customer, now, hasPhysical } = ctx;\\n\\n  if (e.expiresAt && new Date(e.expiresAt).getTime() < now.getTime()) {\\n    return { ok: false, reason: \`\${coupon.code} expired on \${new Date(e.expiresAt).toISOString().slice(0, 10)}.\` };\\n  }\\n  if (e.newCustomersOnly && !customer.isNewCustomer) {\\n    return { ok: false, reason: \`\${coupon.code} is for first orders only, and this account has ordered before.\` };\\n  }\\n  if (e.requiresPhysical && !hasPhysical) {\\n    return { ok: false, reason: \`\${coupon.code} applies to shipping, and this cart has nothing to ship.\` };\\n  }\\n\\n  const matching = lines.filter((l) => lineMatches(coupon, l));\\n  if (matching.length === 0) {\\n    if (coupon.scope === SCOPE.ITEM) {\\n      return { ok: false, reason: \`\${coupon.code} does not apply to anything in this cart.\` };\\n    }\\n    if (e.productClasses || e.productIds || e.skus || e.excludeClasses) {\\n      return { ok: false, reason: \`\${coupon.code} does not apply to anything in this cart.\` };\\n    }\\n  }\\n\\n  if (e.minSubtotal) {\\n    const min = Money.parse(e.minSubtotal, currency);\\n    const base = sum(matching.map((l) => l.lineSubtotal), currency);\\n    if (base.lessThan(min)) {\\n      const short = min.minus(base);\\n      return {\\n        ok: false,\\n        reason: \`\${coupon.code} needs \${min.format()} of eligible merchandise — \${short.format()} more to go.\`,\\n      };\\n    }\\n  }\\n  return { ok: true };\\n}\\n\\n/**\\n * Decide which of the requested codes are live, and compute item- and\\n * order-level discounts. Shipping coupons are recorded here and applied later by\\n * applyShippingDiscount(), because they need the shipping quote, which in turn\\n * needs the merchandise total after these discounts.\\n *\\n * @param {string[]} codes    codes the customer has applied, in the order applied\\n * @param {object} ctx        { currency, lines, customer, now, hasPhysical }\\n * @returns {{\\n *   applied: Array<{code,label,scope,amount:Money,exclusive:boolean,terms:string}>,\\n *   rejected: Array<{code, reason}>,\\n *   lineDiscounts: Map<string, Money>,   // lineId -> total item+order discount\\n *   shippingCoupon: object|null,\\n * }}\\n */\\nexport function evaluatePromotions(codes, ctx) {\\n  const { currency, lines } = ctx;\\n  const applied = [];\\n  const rejected = [];\\n  const scopesTaken = new Map();\\n  let exclusiveHolder = null;\\n  const accepted = [];\\n\\n  const seen = new Set();\\n  for (const raw of codes) {\\n    const code = String(raw ?? '').trim().toUpperCase();\\n    if (!code || seen.has(code)) continue;\\n    seen.add(code);\\n\\n    const coupon = findCoupon(code);\\n    if (!coupon) {\\n      rejected.push({ code, reason: \`\${code} is not a valid code.\` });\\n      continue;\\n    }\\n    const eligible = checkEligibility(coupon, ctx);\\n    if (!eligible.ok) {\\n      rejected.push({ code, reason: eligible.reason });\\n      continue;\\n    }\\n    // Stacking policy, rules 2-4.\\n    if (exclusiveHolder) {\\n      rejected.push({\\n        code,\\n        reason: \`\${exclusiveHolder} cannot be combined with other offers, so \${code} was not applied.\`,\\n      });\\n      continue;\\n    }\\n    if (coupon.exclusive && accepted.length > 0) {\\n      rejected.push({\\n        code,\\n        reason: \`\${code} cannot be combined with other offers — remove \${accepted.map((c) => c.code).join(', ')} first.\`,\\n      });\\n      continue;\\n    }\\n    if (scopesTaken.has(coupon.scope)) {\\n      rejected.push({\\n        code,\\n        reason: \`Only one \${coupon.scope} offer at a time — \${scopesTaken.get(coupon.scope)} is already applied.\`,\\n      });\\n      continue;\\n    }\\n    scopesTaken.set(coupon.scope, coupon.code);\\n    if (coupon.exclusive) exclusiveHolder = coupon.code;\\n    accepted.push(coupon);\\n  }\\n\\n  const lineDiscounts = new Map(lines.map((l) => [l.lineId, Money.zero(currency)]));\\n\\n  // ── ITEM scope ────────────────────────────────────────────────────────────\\n  const itemCoupon = accepted.find((c) => c.scope === SCOPE.ITEM);\\n  if (itemCoupon) {\\n    let total = Money.zero(currency);\\n    for (const line of lines) {\\n      if (!lineMatches(itemCoupon, line)) continue;\\n      let cut;\\n      if (itemCoupon.benefit.kind === 'percent') {\\n        cut = line.lineSubtotal.percentBps(itemCoupon.benefit.bps);\\n      } else if (itemCoupon.benefit.kind === 'amountOffPerUnit') {\\n        cut = Money.parse(itemCoupon.benefit.amount, currency).times(line.quantity);\\n      } else {\\n        cut = Money.parse(itemCoupon.benefit.amount, currency);\\n      }\\n      if (cut.minor > line.lineSubtotal.minor) cut = line.lineSubtotal; // rule 6\\n      lineDiscounts.set(line.lineId, lineDiscounts.get(line.lineId).plus(cut));\\n      total = total.plus(cut);\\n    }\\n    if (total.isZero()) {\\n      rejected.push({ code: itemCoupon.code, reason: \`\${itemCoupon.code} discounts nothing in this cart.\` });\\n    } else {\\n      applied.push(couponSummary(itemCoupon, total));\\n    }\\n  }\\n\\n  // ── ORDER scope ───────────────────────────────────────────────────────────\\n  const orderCoupon = accepted.find((c) => c.scope === SCOPE.ORDER);\\n  if (orderCoupon) {\\n    const eligibleLines = lines.filter((l) => lineMatches(orderCoupon, l));\\n    const netOf = (l) => l.lineSubtotal.minus(lineDiscounts.get(l.lineId));\\n    const base = sum(eligibleLines.map(netOf), currency);\\n    let total;\\n    if (orderCoupon.benefit.kind === 'percent') {\\n      total = base.percentBps(orderCoupon.benefit.bps);\\n    } else {\\n      total = Money.parse(orderCoupon.benefit.amount, currency);\\n      if (total.minor > base.minor) total = base; // rule 6\\n    }\\n    if (total.isZero()) {\\n      rejected.push({ code: orderCoupon.code, reason: \`\${orderCoupon.code} discounts nothing in this cart.\` });\\n    } else {\\n      // Spread across the eligible lines so per-line maths and tax stay honest.\\n      const shares = allocate(total, eligibleLines.map((l) => netOf(l).minor));\\n      eligibleLines.forEach((l, i) => {\\n        lineDiscounts.set(l.lineId, lineDiscounts.get(l.lineId).plus(shares[i]));\\n      });\\n      applied.push(couponSummary(orderCoupon, total));\\n    }\\n  }\\n\\n  const shippingCoupon = accepted.find((c) => c.scope === SCOPE.SHIPPING) ?? null;\\n\\n  return { applied, rejected, lineDiscounts, shippingCoupon, acceptedCodes: accepted.map((c) => c.code) };\\n}\\n\\n/** Apply a shipping-scope coupon to a quote. Returns { discount, note }. */\\nexport function applyShippingDiscount(coupon, shippingQuote, currency) {\\n  if (!coupon) return { discount: Money.zero(currency), note: null };\\n  const charge = shippingQuote.amount;\\n  if (charge.isZero()) {\\n    return {\\n      discount: Money.zero(currency),\\n      note: \`\${coupon.code} had nothing to discount — shipping is already free.\`,\\n    };\\n  }\\n  if (coupon.benefit.kind === 'freeShipping') {\\n    if (coupon.benefit.methods && !coupon.benefit.methods.includes(shippingQuote.methodId)) {\\n      return {\\n        discount: Money.zero(currency),\\n        note: \`\${coupon.code} covers \${coupon.benefit.methods.join('/')} shipping only — you have chosen \${shippingQuote.label}.\`,\\n      };\\n    }\\n    return { discount: charge, note: null };\\n  }\\n  if (coupon.benefit.kind === 'percent') {\\n    return { discount: charge.percentBps(coupon.benefit.bps), note: null };\\n  }\\n  const flat = Money.parse(coupon.benefit.amount, currency);\\n  return { discount: flat.minor > charge.minor ? charge : flat, note: null };\\n}\\n\\nfunction couponSummary(coupon, amount) {\\n  return {\\n    code: coupon.code,\\n    label: coupon.label,\\n    scope: coupon.scope,\\n    exclusive: coupon.exclusive,\\n    terms: coupon.terms,\\n    amount,\\n  };\\n}\\n"},{"path":"src/server.js","bytes":13503,"text":"/**\\n * HTTP layer: a small JSON API plus the static shop front. No framework, no\\n * dependencies — node:http and the standard library.\\n *\\n * Cart identity is a single httpOnly cookie holding an opaque cart token. Nothing\\n * about the cart's contents lives in the browser, so the cart survives a reload,\\n * a new tab, a browser restart and a server restart.\\n */\\n\\nimport { createServer } from 'node:http';\\nimport { readFile } from 'node:fs/promises';\\nimport { extname, join, normalize, resolve } from 'node:path';\\nimport { fileURLToPath } from 'node:url';\\n\\nimport { Store } from './store.js';\\nimport { variantImageSvg, VARIANTS } from './catalog.js';\\nimport * as cartService from './cart-service.js';\\nimport { CartError } from './cart-service.js';\\n\\nconst ROOT = fileURLToPath(new URL('..', import.meta.url));\\nconst PUBLIC_DIR = join(ROOT, 'public');\\nconst COOKIE_NAME = 'cart_token';\\nconst COOKIE_MAX_AGE = 60 * 60 * 24 * 30; // 30 days — the cart outlives the session\\n\\nconst MIME = {\\n  '.html': 'text/html; charset=utf-8',\\n  '.js': 'text/javascript; charset=utf-8',\\n  '.css': 'text/css; charset=utf-8',\\n  '.svg': 'image/svg+xml',\\n  '.ico': 'image/x-icon',\\n  '.json': 'application/json; charset=utf-8',\\n};\\n\\nexport function createApp({ dbFile = process.env.CART_DB ?? 'data/cart.db' } = {}) {\\n  const store = new Store(dbFile);\\n\\n  const server = createServer(async (req, res) => {\\n    try {\\n      await route(req, res, store);\\n    } catch (err) {\\n      if (err instanceof CartError) {\\n        sendJson(res, err.status, { error: { code: err.code, message: err.message } });\\n      } else {\\n        console.error(err);\\n        sendJson(res, 500, { error: { code: 'internal', message: 'Something went wrong on our side.' } });\\n      }\\n    }\\n  });\\n\\n  server.on('close', () => store.close());\\n  return { server, store };\\n}\\n\\nasync function route(req, res, store) {\\n  const url = new URL(req.url, \`http://\${req.headers.host ?? 'localhost'}\`);\\n  const path = url.pathname;\\n  const method = req.method.toUpperCase();\\n\\n  // ── images ────────────────────────────────────────────────────────────────\\n  if (method === 'GET' && path.startsWith('/img/')) {\\n    const sku = decodeURIComponent(path.slice('/img/'.length).replace(/\\\\.svg$/, ''));\\n    res.writeHead(VARIANTS.has(sku) ? 200 : 404, {\\n      'Content-Type': 'image/svg+xml',\\n      'Cache-Control': 'public, max-age=300',\\n    });\\n    res.end(variantImageSvg(sku));\\n    return;\\n  }\\n\\n  // ── static ────────────────────────────────────────────────────────────────\\n  if (!path.startsWith('/api/')) {\\n    await serveStatic(path, res);\\n    return;\\n  }\\n\\n  const body = ['POST', 'PUT', 'PATCH', 'DELETE'].includes(method) ? await readJson(req) : {};\\n\\n  // Every API call resolves (or creates) the caller's cart from the cookie.\\n  const { cart, setCookie } = resolveCart(req, store, url);\\n  const withCookie = (payload, status = 200) => {\\n    if (setCookie) res.setHeader('Set-Cookie', cookie(setCookie));\\n    sendJson(res, status, payload);\\n  };\\n  const respond = (v, status = 200) => withCookie(v, status);\\n\\n  const segments = path.split('/').filter(Boolean); // ['api', ...]\\n\\n  // GET /api/state — everything the page needs in one call\\n  if (method === 'GET' && path === '/api/state') {\\n    return respond({\\n      ...cartService.view(store, cart),\\n      catalog: cartService.catalogView(store, cart),\\n    });\\n  }\\n\\n  if (method === 'GET' && path === '/api/catalog') {\\n    return respond(cartService.catalogView(store, cart));\\n  }\\n\\n  if (method === 'GET' && path === '/api/cart') {\\n    return respond(cartService.view(store, cart));\\n  }\\n\\n  // POST /api/cart/items { sku, quantity }\\n  if (method === 'POST' && path === '/api/cart/items') {\\n    return respond(cartService.addItem(store, cart, { sku: body.sku, quantity: body.quantity ?? 1 }));\\n  }\\n\\n  // PATCH/DELETE /api/cart/items/:lineId\\n  if (segments[0] === 'api' && segments[1] === 'cart' && segments[2] === 'items' && segments[3]) {\\n    const lineId = decodeURIComponent(segments[3]);\\n    if (method === 'PATCH') {\\n      return respond(cartService.setQuantity(store, cart, { lineId, quantity: body.quantity }));\\n    }\\n    if (method === 'DELETE') {\\n      return respond(cartService.removeItem(store, cart, { lineId }));\\n    }\\n  }\\n\\n  if (method === 'PUT' && path === '/api/cart/destination') {\\n    return respond(cartService.setDestination(store, cart, { country: body.country, region: body.region ?? null }));\\n  }\\n\\n  if (method === 'PUT' && path === '/api/cart/shipping-method') {\\n    return respond(cartService.setShippingMethod(store, cart, { methodId: body.methodId }));\\n  }\\n\\n  if (method === 'POST' && path === '/api/cart/coupons') {\\n    return respond(cartService.applyCoupon(store, cart, { code: body.code }));\\n  }\\n\\n  if (segments.join('/') === 'api/cart/coupons' && method === 'DELETE' && body.code) {\\n    return respond(cartService.removeCoupon(store, cart, { code: body.code }));\\n  }\\n  if (segments[0] === 'api' && segments[1] === 'cart' && segments[2] === 'coupons' && segments[3] && method === 'DELETE') {\\n    return respond(cartService.removeCoupon(store, cart, { code: decodeURIComponent(segments[3]) }));\\n  }\\n\\n  // ── identity ──────────────────────────────────────────────────────────────\\n  if (method === 'POST' && path === '/api/session/signin') {\\n    const v = cartService.signIn(store, cart, { email: body.email });\\n    res.setHeader('Set-Cookie', cookie(v.cart.token)); // sign-in may switch carts\\n    return sendJson(res, 200, v);\\n  }\\n\\n  if (method === 'POST' && path === '/api/session/signout') {\\n    const fresh = store.createCart({});\\n    res.setHeader('Set-Cookie', cookie(fresh.token));\\n    return sendJson(res, 200, {\\n      ...cartService.view(store, fresh, {\\n        messages: [\\n          {\\n            level: 'info',\\n            kind: 'signed-out',\\n            message: 'Signed out. Your account cart is saved and will be there when you sign back in.',\\n          },\\n        ],\\n      }),\\n      catalog: cartService.catalogView(store, fresh),\\n    });\\n  }\\n\\n  // ── checkout ──────────────────────────────────────────────────────────────\\n  if (method === 'POST' && path === '/api/checkout/begin') {\\n    const result = cartService.beginCheckout(store, cart);\\n    // The hold changes what everyone else can see, so the catalogue rides along.\\n    return respond({ ...result.view, catalog: cartService.catalogView(store, cart) }, result.ok ? 200 : 409);\\n  }\\n\\n  if (method === 'POST' && path === '/api/checkout/confirm') {\\n    const result = cartService.confirmCheckout(store, cart, { email: body.email ?? null });\\n    if (!result.ok) return respond({ ...result.view, catalog: cartService.catalogView(store, cart) }, 409);\\n    res.setHeader('Set-Cookie', cookie(result.view.cart.token)); // a fresh cart follows the order\\n    return sendJson(res, 200, {\\n      ...result.view,\\n      catalog: cartService.catalogView(store, store.cartById(result.view.cart.id)),\\n      order: { id: result.orderId, ...result.order },\\n    });\\n  }\\n\\n  if (segments[0] === 'api' && segments[1] === 'orders' && segments[2] && method === 'GET') {\\n    const order = store.orderById(decodeURIComponent(segments[2]));\\n    if (!order) return sendJson(res, 404, { error: { code: 'not_found', message: 'No such order.' } });\\n    return sendJson(res, 200, order);\\n  }\\n\\n  // ── abandoned carts ───────────────────────────────────────────────────────\\n  if (method === 'GET' && path === '/api/carts/abandoned') {\\n    const raw = url.searchParams.get('minutes');\\n    const minutes = raw !== null && Number.isFinite(Number(raw)) ? Number(raw) : undefined;\\n    return respond({ carts: store.abandonedCarts(minutes) });\\n  }\\n\\n  if (method === 'POST' && path === '/api/cart/recover') {\\n    const found = store.cartByRecoveryToken(String(body.recoveryToken ?? '').trim());\\n    if (!found) return sendJson(res, 404, { error: { code: 'not_found', message: 'That recovery link is not valid.' } });\\n    res.setHeader('Set-Cookie', cookie(found.token));\\n    return sendJson(res, 200, {\\n      ...cartService.view(store, found, {\\n        messages: [{ level: 'success', kind: 'recovered', message: 'Welcome back — your cart is exactly as you left it.' }],\\n      }),\\n      catalog: cartService.catalogView(store, found),\\n    });\\n  }\\n\\n  // ── demo controls: move the world under the customer's feet ───────────────\\n  if (method === 'POST' && path === '/api/admin/stock') {\\n    if (!VARIANTS.has(body.sku)) return sendJson(res, 404, { error: { code: 'unknown_sku', message: 'No such SKU.' } });\\n    store.setStock(body.sku, Number(body.onHand ?? 0));\\n    return respond({\\n      ...cartService.view(store, store.cartById(cart.id), {\\n        messages: [{ level: 'warning', kind: 'stock-changed', message: \`Stock for \${body.sku} is now \${Number(body.onHand ?? 0)}.\` }],\\n      }),\\n      catalog: cartService.catalogView(store, cart),\\n    });\\n  }\\n\\n  if (method === 'POST' && path === '/api/admin/price') {\\n    if (!store.setPrice(body.sku, String(body.price))) {\\n      return sendJson(res, 404, { error: { code: 'unknown_sku', message: 'No such SKU.' } });\\n    }\\n    return respond({\\n      ...cartService.view(store, store.cartById(cart.id), {\\n        messages: [{ level: 'warning', kind: 'price-changed', message: \`\${body.sku} is now $\${body.price}.\` }],\\n      }),\\n      catalog: cartService.catalogView(store, cart),\\n    });\\n  }\\n\\n  sendJson(res, 404, { error: { code: 'not_found', message: \`No route for \${method} \${path}\` } });\\n}\\n\\n/**\\n * Find the caller's cart. Order of preference:\\n *   1. ?recover=<token> in the URL (an abandoned-cart email link)\\n *   2. the cart_token cookie, if it still points at an active cart\\n *   3. the successor cart, if this one was merged away at sign-in\\n *   4. a brand new guest cart\\n */\\nfunction resolveCart(req, store, url) {\\n  const recover = url.searchParams.get('recover');\\n  if (recover) {\\n    const found = store.cartByRecoveryToken(recover);\\n    if (found) return { cart: found, setCookie: found.token };\\n  }\\n\\n  const token = parseCookies(req.headers.cookie).get(COOKIE_NAME);\\n  let cart = store.cartByToken(token);\\n\\n  if (cart && cart.status === 'merged' && cart.mergedInto) {\\n    const successor = store.cartById(cart.mergedInto);\\n    if (successor) return { cart: successor, setCookie: successor.token };\\n  }\\n  if (cart && cart.status === 'ordered') {\\n    const fresh = store.createCart({ accountId: cart.accountId, email: cart.email });\\n    return { cart: fresh, setCookie: fresh.token };\\n  }\\n  if (!cart) {\\n    cart = store.createCart({});\\n    return { cart, setCookie: cart.token };\\n  }\\n  return { cart, setCookie: null };\\n}\\n\\nfunction cookie(token) {\\n  return \`\${COOKIE_NAME}=\${token}; Path=/; HttpOnly; SameSite=Lax; Max-Age=\${COOKIE_MAX_AGE}\`;\\n}\\n\\nfunction parseCookies(header) {\\n  const map = new Map();\\n  for (const part of String(header ?? '').split(';')) {\\n    const i = part.indexOf('=');\\n    if (i === -1) continue;\\n    map.set(part.slice(0, i).trim(), decodeURIComponent(part.slice(i + 1).trim()));\\n  }\\n  return map;\\n}\\n\\nasync function readJson(req) {\\n  const chunks = [];\\n  let size = 0;\\n  for await (const chunk of req) {\\n    size += chunk.length;\\n    if (size > 256 * 1024) throw new CartError('Request too large.', 413, 'too_large');\\n    chunks.push(chunk);\\n  }\\n  if (chunks.length === 0) return {};\\n  const text = Buffer.concat(chunks).toString('utf8').trim();\\n  if (!text) return {};\\n  try {\\n    return JSON.parse(text);\\n  } catch {\\n    throw new CartError('Body must be JSON.', 400, 'bad_json');\\n  }\\n}\\n\\nfunction sendJson(res, status, payload) {\\n  const text = JSON.stringify(payload);\\n  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });\\n  res.end(text);\\n}\\n\\nasync function serveStatic(path, res) {\\n  const rel = path === '/' ? 'index.html' : normalize(path).replace(/^([/\\\\\\\\])+/, '');\\n  const file = join(PUBLIC_DIR, rel);\\n  if (!file.startsWith(PUBLIC_DIR)) {\\n    res.writeHead(403).end('Forbidden');\\n    return;\\n  }\\n  try {\\n    const data = await readFile(file);\\n    res.writeHead(200, { 'Content-Type': MIME[extname(file)] ?? 'application/octet-stream', 'Cache-Control': 'no-cache' });\\n    res.end(data);\\n  } catch {\\n    // Unknown paths fall back to the single page (so /?recover=… works).\\n    try {\\n      const data = await readFile(join(PUBLIC_DIR, 'index.html'));\\n      res.writeHead(200, { 'Content-Type': MIME['.html'] }).end(data);\\n    } catch {\\n      res.writeHead(404, { 'Content-Type': 'text/plain' }).end('Not found');\\n    }\\n  }\\n}\\n\\n// Started directly? Listen.\\nif (process.argv[1] && fileURLToPath(import.meta.url) === resolve(process.argv[1])) {\\n  const port = Number(process.env.PORT ?? 8787);\\n  const { server } = createApp();\\n  server.listen(port, () => {\\n    console.log(\`\\\\n  Shopping cart running at http://localhost:\${port}\`);\\n    console.log(\`  Database: \${process.env.CART_DB ?? 'data/cart.db'}  (delete it to start fresh)\\\\n\`);\\n  });\\n}\\n"},{"path":"src/shipping.js","bytes":4614,"text":"/**\\n * Shipping estimate — quoted in the cart, before checkout.\\n *\\n * The estimate is a function of (destination zone, billable weight, post-discount\\n * merchandise value, chosen method). It is an *estimate*: the carrier's number is\\n * only fixed once an address is entered at checkout, and the UI says so.\\n *\\n * A cart of only digital items ships free by every method, and no method choice\\n * is offered.\\n */\\n\\nimport { Money } from './money.js';\\n\\nexport const ZONES = {\\n  DOMESTIC: 'domestic', // US\\n  EUROPE: 'europe',     // GB, DE\\n  REST: 'rest',\\n};\\n\\nexport function zoneFor(destination) {\\n  if (!destination?.country) return null;\\n  if (destination.country === 'US') return ZONES.DOMESTIC;\\n  if (['GB', 'DE', 'FR', 'IE', 'NL', 'ES', 'IT'].includes(destination.country)) return ZONES.EUROPE;\\n  return ZONES.REST;\\n}\\n\\n/**\\n * base: flat charge. perKg: added per whole kilogram of billable weight\\n * (rounded up). freeOver: merchandise total at or above which the method is free\\n * (null = never free automatically).\\n */\\nexport const METHODS = [\\n  {\\n    id: 'standard',\\n    label: 'Standard',\\n    etaDays: [4, 7],\\n    rates: {\\n      [ZONES.DOMESTIC]: { base: '4.95', perKg: '0.90', freeOver: '75.00' },\\n      [ZONES.EUROPE]: { base: '12.00', perKg: '2.50', freeOver: '150.00' },\\n      [ZONES.REST]: { base: '18.00', perKg: '4.00', freeOver: null },\\n    },\\n  },\\n  {\\n    id: 'express',\\n    label: 'Express',\\n    etaDays: [1, 2],\\n    rates: {\\n      [ZONES.DOMESTIC]: { base: '12.95', perKg: '1.80', freeOver: null },\\n      [ZONES.EUROPE]: { base: '28.00', perKg: '4.50', freeOver: null },\\n      [ZONES.REST]: { base: '42.00', perKg: '7.00', freeOver: null },\\n    },\\n  },\\n];\\n\\nexport const DEFAULT_METHOD = 'standard';\\n\\nexport function methodById(id) {\\n  return METHODS.find((m) => m.id === id) ?? null;\\n}\\n\\n/**\\n * @param {object} args\\n * @param {object|null} args.destination  { country, region }\\n * @param {string} args.methodId\\n * @param {number} args.weightGrams       total billable weight of physical goods\\n * @param {Money}  args.merchandiseTotal  merchandise *after* item/order discounts\\n * @param {boolean} args.allDigital\\n * @param {string} args.currency\\n * @returns {{ amount: Money, methodId: string, label: string, eta: string,\\n *             reason: string, quotable: boolean, freeThreshold: Money|null }}\\n */\\nexport function quote({ destination, methodId, weightGrams, merchandiseTotal, allDigital, currency }) {\\n  const method = methodById(methodId) ?? methodById(DEFAULT_METHOD);\\n\\n  if (allDigital) {\\n    return {\\n      amount: Money.zero(currency),\\n      methodId: method.id,\\n      label: 'Digital delivery',\\n      eta: 'Immediate download',\\n      reason: 'Nothing in this cart ships physically.',\\n      quotable: true,\\n      freeThreshold: null,\\n    };\\n  }\\n\\n  const zone = zoneFor(destination);\\n  if (!zone) {\\n    return {\\n      amount: Money.zero(currency),\\n      methodId: method.id,\\n      label: method.label,\\n      eta: \`\${method.etaDays[0]}-\${method.etaDays[1]} business days\`,\\n      reason: 'Choose a destination to see a shipping estimate.',\\n      quotable: false,\\n      freeThreshold: null,\\n    };\\n  }\\n\\n  const rate = method.rates[zone];\\n  const base = Money.parse(rate.base, currency);\\n  const perKg = Money.parse(rate.perKg, currency);\\n  const billableKg = Math.max(1, Math.ceil(weightGrams / 1000));\\n  const freeThreshold = rate.freeOver ? Money.parse(rate.freeOver, currency) : null;\\n\\n  if (freeThreshold && merchandiseTotal.atLeast(freeThreshold)) {\\n    return {\\n      amount: Money.zero(currency),\\n      methodId: method.id,\\n      label: method.label,\\n      eta: \`\${method.etaDays[0]}-\${method.etaDays[1]} business days\`,\\n      reason: \`Free \${method.label.toLowerCase()} shipping over \${freeThreshold.format()}.\`,\\n      quotable: true,\\n      freeThreshold,\\n    };\\n  }\\n\\n  const amount = base.plus(perKg.times(billableKg));\\n  return {\\n    amount,\\n    methodId: method.id,\\n    label: method.label,\\n    eta: \`\${method.etaDays[0]}-\${method.etaDays[1]} business days\`,\\n    reason: \`\${base.format()} + \${perKg.format()}/kg on \${billableKg} kg billable weight to \${zoneLabel(zone)}.\`,\\n    quotable: true,\\n    freeThreshold,\\n  };\\n}\\n\\nexport function zoneLabel(zone) {\\n  return { [ZONES.DOMESTIC]: 'US', [ZONES.EUROPE]: 'Europe', [ZONES.REST]: 'rest of world' }[zone] ?? zone;\\n}\\n\\n/** All method options priced for the current cart, for the UI's method picker. */\\nexport function quoteAll(args) {\\n  return METHODS.map((m) => {\\n    const q = quote({ ...args, methodId: m.id });\\n    return { id: m.id, label: m.label, eta: q.eta, amount: q.amount, reason: q.reason, quotable: q.quotable };\\n  });\\n}\\n"},{"path":"src/store.js","bytes":17071,"text":"/**\\n * Persistence. SQLite via node:sqlite (built into Node 22.5+/24 — no native build,\\n * no dependencies). The database file is the durability story: a cart survives a\\n * page reload, a browser restart, a server restart, and the end of a session.\\n *\\n * The browser holds nothing but a cart token in a cookie. Every line, coupon,\\n * destination and reservation lives in the database.\\n */\\n\\nimport { DatabaseSync } from 'node:sqlite';\\nimport { randomUUID } from 'node:crypto';\\nimport { mkdirSync } from 'node:fs';\\nimport { dirname } from 'node:path';\\nimport { VARIANTS, setVariantPrice } from './catalog.js';\\n\\nexport const RESERVATION_WINDOW_MINUTES = 15;\\nexport const ABANDONED_AFTER_MINUTES = 30;\\n\\nexport class Store {\\n  /** @param {string} file  path to the sqlite file, or ':memory:' for tests */\\n  constructor(file = 'data/cart.db') {\\n    if (file !== ':memory:') mkdirSync(dirname(file), { recursive: true });\\n    this.db = new DatabaseSync(file);\\n    this.db.exec('PRAGMA journal_mode = WAL');\\n    this.db.exec('PRAGMA foreign_keys = ON');\\n    this.#migrate();\\n    this.#seedStock();\\n    this.applyPriceOverrides();\\n  }\\n\\n  close() {\\n    this.db.close();\\n  }\\n\\n  #migrate() {\\n    this.db.exec(\`\\n      CREATE TABLE IF NOT EXISTS accounts (\\n        id          TEXT PRIMARY KEY,\\n        email       TEXT UNIQUE NOT NULL,\\n        created_at  TEXT NOT NULL\\n      );\\n\\n      CREATE TABLE IF NOT EXISTS carts (\\n        id             TEXT PRIMARY KEY,\\n        token          TEXT UNIQUE NOT NULL,\\n        recovery_token TEXT UNIQUE NOT NULL,\\n        account_id     TEXT REFERENCES accounts(id),\\n        email          TEXT,\\n        status         TEXT NOT NULL DEFAULT 'active',   -- active | merged | ordered\\n        merged_into    TEXT,\\n        dest_country   TEXT,\\n        dest_region    TEXT,\\n        shipping_method TEXT NOT NULL DEFAULT 'standard',\\n        created_at     TEXT NOT NULL,\\n        updated_at     TEXT NOT NULL\\n      );\\n\\n      CREATE TABLE IF NOT EXISTS cart_lines (\\n        line_id       TEXT PRIMARY KEY,\\n        cart_id       TEXT NOT NULL REFERENCES carts(id) ON DELETE CASCADE,\\n        sku           TEXT NOT NULL,\\n        quantity      INTEGER NOT NULL CHECK (quantity > 0),\\n        unit_price_minor_at_add INTEGER NOT NULL,\\n        added_at      TEXT NOT NULL,\\n        UNIQUE (cart_id, sku)                    -- one line per SKU: duplicates merge\\n      );\\n\\n      CREATE TABLE IF NOT EXISTS cart_coupons (\\n        cart_id    TEXT NOT NULL REFERENCES carts(id) ON DELETE CASCADE,\\n        code       TEXT NOT NULL,\\n        applied_at TEXT NOT NULL,\\n        PRIMARY KEY (cart_id, code)\\n      );\\n\\n      CREATE TABLE IF NOT EXISTS stock (\\n        sku      TEXT PRIMARY KEY,\\n        on_hand  INTEGER NOT NULL\\n      );\\n\\n      CREATE TABLE IF NOT EXISTS price_overrides (\\n        sku           TEXT PRIMARY KEY,\\n        price_decimal TEXT NOT NULL,\\n        changed_at    TEXT NOT NULL\\n      );\\n\\n      CREATE TABLE IF NOT EXISTS reservations (\\n        id         TEXT PRIMARY KEY,\\n        cart_id    TEXT NOT NULL REFERENCES carts(id) ON DELETE CASCADE,\\n        sku        TEXT NOT NULL,\\n        quantity   INTEGER NOT NULL,\\n        created_at TEXT NOT NULL,\\n        expires_at TEXT NOT NULL,\\n        state      TEXT NOT NULL DEFAULT 'held'   -- held | consumed | released\\n      );\\n\\n      CREATE TABLE IF NOT EXISTS orders (\\n        id          TEXT PRIMARY KEY,\\n        cart_id     TEXT NOT NULL,\\n        account_id  TEXT,\\n        email       TEXT,\\n        placed_at   TEXT NOT NULL,\\n        total_minor INTEGER NOT NULL,\\n        currency    TEXT NOT NULL,\\n        receipt     TEXT NOT NULL\\n      );\\n\\n      CREATE INDEX IF NOT EXISTS idx_lines_cart ON cart_lines(cart_id);\\n      CREATE INDEX IF NOT EXISTS idx_res_sku ON reservations(sku, state);\\n      CREATE INDEX IF NOT EXISTS idx_carts_account ON carts(account_id, status);\\n    \`);\\n  }\\n\\n  #seedStock() {\\n    const insert = this.db.prepare('INSERT OR IGNORE INTO stock (sku, on_hand) VALUES (?, ?)');\\n    for (const v of VARIANTS.values()) insert.run(v.sku, v.seedStock);\\n  }\\n\\n  /** Re-apply any persisted price changes to the in-memory catalogue. */\\n  applyPriceOverrides() {\\n    for (const row of this.db.prepare('SELECT sku, price_decimal FROM price_overrides').all()) {\\n      setVariantPrice(row.sku, row.price_decimal);\\n    }\\n  }\\n\\n  setPrice(sku, priceDecimal, now = new Date()) {\\n    if (!VARIANTS.has(sku)) return false;\\n    this.db\\n      .prepare(\\n        \`INSERT INTO price_overrides (sku, price_decimal, changed_at) VALUES (?,?,?)\\n         ON CONFLICT(sku) DO UPDATE SET price_decimal = excluded.price_decimal, changed_at = excluded.changed_at\`,\\n      )\\n      .run(sku, priceDecimal, now.toISOString());\\n    return setVariantPrice(sku, priceDecimal);\\n  }\\n\\n  // ── stock & reservations ──────────────────────────────────────────────────\\n\\n  onHand(sku) {\\n    const row = this.db.prepare('SELECT on_hand FROM stock WHERE sku = ?').get(sku);\\n    return row ? row.on_hand : 0;\\n  }\\n\\n  setStock(sku, onHand) {\\n    this.db\\n      .prepare('INSERT INTO stock (sku, on_hand) VALUES (?, ?) ON CONFLICT(sku) DO UPDATE SET on_hand = excluded.on_hand')\\n      .run(sku, Math.max(0, Math.trunc(onHand)));\\n  }\\n\\n  /** Expire any holds whose window has closed. Called before every stock read. */\\n  releaseExpiredReservations(now = new Date()) {\\n    return this.db\\n      .prepare(\\"UPDATE reservations SET state = 'released' WHERE state = 'held' AND expires_at <= ?\\")\\n      .run(now.toISOString()).changes;\\n  }\\n\\n  /**\\n   * Availability = on hand - units held by *other* carts' live reservations.\\n   * A cart's own hold does not reduce what that cart can see.\\n   */\\n  availability(excludeCartId = null, now = new Date()) {\\n    this.releaseExpiredReservations(now);\\n    const held = this.db\\n      .prepare(\\n        \`SELECT sku, SUM(quantity) AS qty FROM reservations\\n          WHERE state = 'held' AND expires_at > ? AND (? IS NULL OR cart_id <> ?)\\n          GROUP BY sku\`,\\n      )\\n      .all(now.toISOString(), excludeCartId, excludeCartId);\\n    const heldBySku = new Map(held.map((r) => [r.sku, r.qty]));\\n    const map = new Map();\\n    for (const row of this.db.prepare('SELECT sku, on_hand FROM stock').all()) {\\n      map.set(row.sku, Math.max(0, row.on_hand - (heldBySku.get(row.sku) ?? 0)));\\n    }\\n    return map;\\n  }\\n\\n  reserve(cartId, items, now = new Date(), minutes = RESERVATION_WINDOW_MINUTES) {\\n    const expires = new Date(now.getTime() + minutes * 60_000);\\n    this.db.prepare(\\"UPDATE reservations SET state = 'released' WHERE cart_id = ? AND state = 'held'\\").run(cartId);\\n    const insert = this.db.prepare(\\n      'INSERT INTO reservations (id, cart_id, sku, quantity, created_at, expires_at, state) VALUES (?,?,?,?,?,?,?)',\\n    );\\n    for (const it of items) {\\n      insert.run(randomUUID(), cartId, it.sku, it.quantity, now.toISOString(), expires.toISOString(), 'held');\\n    }\\n    return { expiresAt: expires.toISOString(), windowMinutes: minutes };\\n  }\\n\\n  activeReservation(cartId, now = new Date()) {\\n    this.releaseExpiredReservations(now);\\n    const rows = this.db\\n      .prepare(\\"SELECT sku, quantity, expires_at FROM reservations WHERE cart_id = ? AND state = 'held' ORDER BY expires_at DESC\\")\\n      .all(cartId);\\n    if (rows.length === 0) return null;\\n    return {\\n      expiresAt: rows[0].expires_at,\\n      items: rows.map((r) => ({ sku: r.sku, quantity: r.quantity })),\\n    };\\n  }\\n\\n  releaseReservations(cartId) {\\n    this.db.prepare(\\"UPDATE reservations SET state = 'released' WHERE cart_id = ? AND state = 'held'\\").run(cartId);\\n  }\\n\\n  consumeReservations(cartId) {\\n    this.db.prepare(\\"UPDATE reservations SET state = 'consumed' WHERE cart_id = ? AND state = 'held'\\").run(cartId);\\n  }\\n\\n  decrementStock(items) {\\n    const stmt = this.db.prepare('UPDATE stock SET on_hand = MAX(0, on_hand - ?) WHERE sku = ?');\\n    for (const it of items) stmt.run(it.quantity, it.sku);\\n  }\\n\\n  // ── carts ─────────────────────────────────────────────────────────────────\\n\\n  createCart({ accountId = null, email = null, now = new Date() } = {}) {\\n    const id = randomUUID();\\n    const token = randomUUID().replaceAll('-', '');\\n    const recovery = randomUUID().replaceAll('-', '');\\n    this.db\\n      .prepare(\\n        \`INSERT INTO carts (id, token, recovery_token, account_id, email, status, shipping_method, created_at, updated_at)\\n         VALUES (?,?,?,?,?, 'active', 'standard', ?, ?)\`,\\n      )\\n      .run(id, token, recovery, accountId, email, now.toISOString(), now.toISOString());\\n    return this.cartById(id);\\n  }\\n\\n  cartById(id) {\\n    const row = this.db.prepare('SELECT * FROM carts WHERE id = ?').get(id);\\n    return row ? this.#hydrate(row) : null;\\n  }\\n\\n  cartByToken(token) {\\n    if (!token) return null;\\n    const row = this.db.prepare('SELECT * FROM carts WHERE token = ?').get(token);\\n    return row ? this.#hydrate(row) : null;\\n  }\\n\\n  cartByRecoveryToken(token) {\\n    if (!token) return null;\\n    const row = this.db.prepare('SELECT * FROM carts WHERE recovery_token = ?').get(token);\\n    return row ? this.#hydrate(row) : null;\\n  }\\n\\n  activeCartForAccount(accountId) {\\n    const row = this.db\\n      .prepare(\\"SELECT * FROM carts WHERE account_id = ? AND status = 'active' ORDER BY updated_at DESC LIMIT 1\\")\\n      .get(accountId);\\n    return row ? this.#hydrate(row) : null;\\n  }\\n\\n  #hydrate(row) {\\n    const lines = this.db\\n      .prepare('SELECT * FROM cart_lines WHERE cart_id = ? ORDER BY added_at, line_id')\\n      .all(row.id)\\n      .map((l) => ({\\n        lineId: l.line_id,\\n        sku: l.sku,\\n        quantity: l.quantity,\\n        unitPriceMinorAtAdd: l.unit_price_minor_at_add,\\n        addedAt: l.added_at,\\n      }));\\n    const couponCodes = this.db\\n      .prepare('SELECT code FROM cart_coupons WHERE cart_id = ? ORDER BY applied_at, code')\\n      .all(row.id)\\n      .map((c) => c.code);\\n    return {\\n      id: row.id,\\n      token: row.token,\\n      recoveryToken: row.recovery_token,\\n      accountId: row.account_id,\\n      email: row.email,\\n      status: row.status,\\n      mergedInto: row.merged_into,\\n      destination: row.dest_country ? { country: row.dest_country, region: row.dest_region } : null,\\n      shippingMethodId: row.shipping_method,\\n      createdAt: row.created_at,\\n      updatedAt: row.updated_at,\\n      lines,\\n      couponCodes,\\n    };\\n  }\\n\\n  touch(cartId, now = new Date()) {\\n    this.db.prepare('UPDATE carts SET updated_at = ? WHERE id = ?').run(now.toISOString(), cartId);\\n  }\\n\\n  setDestination(cartId, destination) {\\n    this.db\\n      .prepare('UPDATE carts SET dest_country = ?, dest_region = ?, updated_at = ? WHERE id = ?')\\n      .run(destination?.country ?? null, destination?.region ?? null, new Date().toISOString(), cartId);\\n  }\\n\\n  setShippingMethod(cartId, methodId) {\\n    this.db\\n      .prepare('UPDATE carts SET shipping_method = ?, updated_at = ? WHERE id = ?')\\n      .run(methodId, new Date().toISOString(), cartId);\\n  }\\n\\n  setCartStatus(cartId, status, mergedInto = null) {\\n    this.db\\n      .prepare('UPDATE carts SET status = ?, merged_into = ?, updated_at = ? WHERE id = ?')\\n      .run(status, mergedInto, new Date().toISOString(), cartId);\\n  }\\n\\n  setCartAccount(cartId, accountId, email) {\\n    this.db\\n      .prepare('UPDATE carts SET account_id = ?, email = ?, updated_at = ? WHERE id = ?')\\n      .run(accountId, email, new Date().toISOString(), cartId);\\n  }\\n\\n  // ── lines ─────────────────────────────────────────────────────────────────\\n\\n  findLine(cartId, sku) {\\n    const row = this.db.prepare('SELECT * FROM cart_lines WHERE cart_id = ? AND sku = ?').get(cartId, sku);\\n    return row\\n      ? { lineId: row.line_id, sku: row.sku, quantity: row.quantity, unitPriceMinorAtAdd: row.unit_price_minor_at_add, addedAt: row.added_at }\\n      : null;\\n  }\\n\\n  lineById(cartId, lineId) {\\n    const row = this.db.prepare('SELECT * FROM cart_lines WHERE cart_id = ? AND line_id = ?').get(cartId, lineId);\\n    return row\\n      ? { lineId: row.line_id, sku: row.sku, quantity: row.quantity, unitPriceMinorAtAdd: row.unit_price_minor_at_add, addedAt: row.added_at }\\n      : null;\\n  }\\n\\n  insertLine(cartId, { sku, quantity, unitPriceMinor, now = new Date() }) {\\n    const lineId = randomUUID();\\n    this.db\\n      .prepare('INSERT INTO cart_lines (line_id, cart_id, sku, quantity, unit_price_minor_at_add, added_at) VALUES (?,?,?,?,?,?)')\\n      .run(lineId, cartId, sku, quantity, unitPriceMinor, now.toISOString());\\n    this.touch(cartId, now);\\n    return lineId;\\n  }\\n\\n  updateLineQuantity(cartId, lineId, quantity) {\\n    this.db.prepare('UPDATE cart_lines SET quantity = ? WHERE cart_id = ? AND line_id = ?').run(quantity, cartId, lineId);\\n    this.touch(cartId);\\n  }\\n\\n  deleteLine(cartId, lineId) {\\n    const res = this.db.prepare('DELETE FROM cart_lines WHERE cart_id = ? AND line_id = ?').run(cartId, lineId);\\n    this.touch(cartId);\\n    return res.changes > 0;\\n  }\\n\\n  clearLines(cartId) {\\n    this.db.prepare('DELETE FROM cart_lines WHERE cart_id = ?').run(cartId);\\n    this.touch(cartId);\\n  }\\n\\n  // ── coupons ───────────────────────────────────────────────────────────────\\n\\n  addCoupon(cartId, code, now = new Date()) {\\n    this.db\\n      .prepare('INSERT OR IGNORE INTO cart_coupons (cart_id, code, applied_at) VALUES (?,?,?)')\\n      .run(cartId, code, now.toISOString());\\n    this.touch(cartId, now);\\n  }\\n\\n  removeCoupon(cartId, code) {\\n    const res = this.db.prepare('DELETE FROM cart_coupons WHERE cart_id = ? AND code = ?').run(cartId, code);\\n    this.touch(cartId);\\n    return res.changes > 0;\\n  }\\n\\n  // ── accounts ──────────────────────────────────────────────────────────────\\n\\n  accountByEmail(email) {\\n    const row = this.db.prepare('SELECT * FROM accounts WHERE email = ?').get(email.toLowerCase());\\n    return row ? { id: row.id, email: row.email, createdAt: row.created_at } : null;\\n  }\\n\\n  accountById(id) {\\n    if (!id) return null;\\n    const row = this.db.prepare('SELECT * FROM accounts WHERE id = ?').get(id);\\n    return row ? { id: row.id, email: row.email, createdAt: row.created_at } : null;\\n  }\\n\\n  createAccount(email, now = new Date()) {\\n    const id = randomUUID();\\n    this.db.prepare('INSERT INTO accounts (id, email, created_at) VALUES (?,?,?)').run(id, email.toLowerCase(), now.toISOString());\\n    return { id, email: email.toLowerCase(), createdAt: now.toISOString() };\\n  }\\n\\n  orderCountForAccount(accountId) {\\n    if (!accountId) return 0;\\n    return this.db.prepare('SELECT COUNT(*) AS n FROM orders WHERE account_id = ?').get(accountId).n;\\n  }\\n\\n  recordOrder({ cartId, accountId, email, receipt, totalMinor, currency, now = new Date() }) {\\n    const id = \`ORD-\${now.toISOString().slice(0, 10).replaceAll('-', '')}-\${randomUUID().slice(0, 6).toUpperCase()}\`;\\n    this.db\\n      .prepare('INSERT INTO orders (id, cart_id, account_id, email, placed_at, total_minor, currency, receipt) VALUES (?,?,?,?,?,?,?,?)')\\n      .run(id, cartId, accountId, email, now.toISOString(), totalMinor, currency, JSON.stringify(receipt));\\n    return id;\\n  }\\n\\n  orderById(id) {\\n    const row = this.db.prepare('SELECT * FROM orders WHERE id = ?').get(id);\\n    if (!row) return null;\\n    return {\\n      id: row.id,\\n      cartId: row.cart_id,\\n      accountId: row.account_id,\\n      email: row.email,\\n      placedAt: row.placed_at,\\n      totalMinor: row.total_minor,\\n      currency: row.currency,\\n      receipt: JSON.parse(row.receipt),\\n    };\\n  }\\n\\n  // ── abandonment ───────────────────────────────────────────────────────────\\n\\n  /** Active carts that hold items and have not been touched for \`minutes\`. */\\n  abandonedCarts(minutes = ABANDONED_AFTER_MINUTES, now = new Date()) {\\n    const cutoff = new Date(now.getTime() - minutes * 60_000).toISOString();\\n    const rows = this.db\\n      .prepare(\\n        \`SELECT c.*, COUNT(l.line_id) AS line_count, SUM(l.quantity) AS unit_count\\n           FROM carts c JOIN cart_lines l ON l.cart_id = c.id\\n          WHERE c.status = 'active' AND c.updated_at <= ?\\n          GROUP BY c.id\\n          ORDER BY c.updated_at DESC\`,\\n      )\\n      .all(cutoff);\\n    return rows.map((r) => ({\\n      cartId: r.id,\\n      email: r.email,\\n      accountId: r.account_id,\\n      lineCount: r.line_count,\\n      unitCount: r.unit_count,\\n      updatedAt: r.updated_at,\\n      idleMinutes: Math.round((now.getTime() - new Date(r.updated_at).getTime()) / 60_000),\\n      recoveryUrl: \`/?recover=\${r.recovery_token}\`,\\n      recoveryToken: r.recovery_token,\\n    }));\\n  }\\n}\\n"},{"path":"src/tax.js","bytes":3923,"text":"/**\\n * Tax: a rate is a function of (destination, product class).\\n *\\n * Rates are integer basis points (bps): 2000 bps = 20.00%. Keeping them as\\n * integers means the whole tax calculation stays in integer arithmetic and only\\n * rounds once per line.\\n *\\n * Two things vary by destination, not just the rate:\\n *   - which classes are zero-rated / exempt (UK books, US grocery in many states)\\n *   - whether shipping itself is taxable\\n *\\n * This is a plausible, self-consistent rule set for a demo shop. It is not a\\n * substitute for a real tax service; see README \\"What this is not\\".\\n */\\n\\nimport { PRODUCT_CLASS } from './catalog.js';\\n\\nconst STANDARD = PRODUCT_CLASS.STANDARD;\\n\\n/**\\n * Jurisdictions keyed by \`\${country}\` or \`\${country}-\${region}\`.\\n * \`rates\` maps product class -> bps; \`default\` covers anything unlisted.\\n * \`shippingTaxable\` decides whether the shipping charge is taxed, and at what rate\\n * (the standard rate for the jurisdiction).\\n */\\nexport const JURISDICTIONS = {\\n  'GB': {\\n    label: 'United Kingdom',\\n    name: 'UK VAT',\\n    inclusive: false,\\n    default: 2000,\\n    rates: {\\n      [PRODUCT_CLASS.BOOK]: 0,\\n      [PRODUCT_CLASS.GROCERY]: 0,\\n      [PRODUCT_CLASS.CHILDRENS_APPAREL]: 0,\\n      [PRODUCT_CLASS.DIGITAL]: 2000,\\n    },\\n    shippingTaxable: true,\\n  },\\n  'DE': {\\n    label: 'Germany',\\n    name: 'German VAT',\\n    inclusive: false,\\n    default: 1900,\\n    rates: {\\n      [PRODUCT_CLASS.BOOK]: 700,\\n      [PRODUCT_CLASS.GROCERY]: 700,\\n    },\\n    shippingTaxable: true,\\n  },\\n  'US-CA': {\\n    label: 'California, United States',\\n    name: 'CA sales tax',\\n    inclusive: false,\\n    default: 875,\\n    rates: {\\n      [PRODUCT_CLASS.GROCERY]: 0,\\n      [PRODUCT_CLASS.DIGITAL]: 0,\\n    },\\n    shippingTaxable: false,\\n  },\\n  'US-NY': {\\n    label: 'New York, United States',\\n    name: 'NY sales tax',\\n    inclusive: false,\\n    default: 888,\\n    rates: {\\n      [PRODUCT_CLASS.GROCERY]: 0,\\n      // NY exempts clothing under $110 per item; modelled below in rateFor().\\n    },\\n    shippingTaxable: true,\\n  },\\n  'US-OR': {\\n    label: 'Oregon, United States',\\n    name: 'no sales tax',\\n    inclusive: false,\\n    default: 0,\\n    rates: {},\\n    shippingTaxable: false,\\n  },\\n  'US-TX': {\\n    label: 'Texas, United States',\\n    name: 'TX sales tax',\\n    inclusive: false,\\n    default: 825,\\n    rates: {\\n      [PRODUCT_CLASS.GROCERY]: 0,\\n    },\\n    shippingTaxable: true,\\n  },\\n};\\n\\nexport const DESTINATIONS = Object.entries(JURISDICTIONS).map(([key, j]) => ({\\n  key,\\n  label: j.label,\\n  country: key.split('-')[0],\\n  region: key.includes('-') ? key.split('-')[1] : null,\\n}));\\n\\nexport function jurisdictionKey(destination) {\\n  if (!destination?.country) return null;\\n  const withRegion = destination.region ? \`\${destination.country}-\${destination.region}\` : null;\\n  if (withRegion && JURISDICTIONS[withRegion]) return withRegion;\\n  if (JURISDICTIONS[destination.country]) return destination.country;\\n  return null;\\n}\\n\\nexport function jurisdictionFor(destination) {\\n  const key = jurisdictionKey(destination);\\n  return key ? { key, ...JURISDICTIONS[key] } : null;\\n}\\n\\n/**\\n * Rate in bps for one line. \`unitPrice\` is passed because a couple of real rules\\n * are price-banded (NY clothing under $110 an item is exempt).\\n */\\nexport function rateFor(jurisdiction, productClass, unitPriceMinor = 0) {\\n  if (!jurisdiction) return 0;\\n  if (jurisdiction.key === 'US-NY') {\\n    const clothing = productClass === PRODUCT_CLASS.APPAREL || productClass === PRODUCT_CLASS.CHILDRENS_APPAREL;\\n    if (clothing && unitPriceMinor < 11_000) return 0;\\n  }\\n  const cls = productClass ?? STANDARD;\\n  return Object.hasOwn(jurisdiction.rates, cls) ? jurisdiction.rates[cls] : jurisdiction.default;\\n}\\n\\nexport function shippingRateFor(jurisdiction) {\\n  if (!jurisdiction || !jurisdiction.shippingTaxable) return 0;\\n  return jurisdiction.default;\\n}\\n\\nexport function formatBps(bps) {\\n  return \`\${(bps / 100).toFixed(2).replace(/\\\\.00$/, '')}%\`;\\n}\\n"},{"path":"test/api.test.js","bytes":9841,"text":"/**\\n * End-to-end over HTTP, with a real cookie jar and a real database file, so the\\n * \\"survives reload and session end\\" claim is tested the way a browser sees it.\\n */\\n\\nimport test from 'node:test';\\nimport assert from 'node:assert/strict';\\nimport { mkdtempSync, rmSync } from 'node:fs';\\nimport { tmpdir } from 'node:os';\\nimport { join } from 'node:path';\\nimport { createApp } from '../src/server.js';\\n\\nfunction startServer(existing = null) {\\n  const dir = existing?.dir ?? mkdtempSync(join(tmpdir(), 'cart-test-'));\\n  const dbFile = existing?.dbFile ?? join(dir, 'cart.db');\\n  const { server, store } = createApp({ dbFile });\\n  return new Promise((resolve) => {\\n    server.listen(0, '127.0.0.1', () => {\\n      const base = \`http://127.0.0.1:\${server.address().port}\`;\\n      resolve({\\n        base,\\n        store,\\n        dir,\\n        dbFile,\\n        async stop({ keepFiles = false } = {}) {\\n          await new Promise((r) => server.close(r));\\n          if (keepFiles) return;\\n          try {\\n            rmSync(dir, { recursive: true, force: true });\\n          } catch {\\n            /* Windows may still hold the WAL file; the temp dir is disposable */\\n          }\\n        },\\n      });\\n    });\\n  });\\n}\\n\\n/** A browser: keeps whatever cookie the server sets. */\\nfunction browser(base) {\\n  let cookie = null;\\n  return {\\n    get cookie() {\\n      return cookie;\\n    },\\n    set cookie(v) {\\n      cookie = v;\\n    },\\n    async call(method, path, body) {\\n      const res = await fetch(base + path, {\\n        method,\\n        headers: {\\n          ...(body ? { 'Content-Type': 'application/json' } : {}),\\n          ...(cookie ? { Cookie: cookie } : {}),\\n        },\\n        body: body ? JSON.stringify(body) : undefined,\\n      });\\n      const setCookie = res.headers.get('set-cookie');\\n      if (setCookie) cookie = setCookie.split(';')[0];\\n      return { status: res.status, body: await res.json() };\\n    },\\n  };\\n}\\n\\ntest('a cart survives reload, a new session and a server restart', async (t) => {\\n  const first = await startServer();\\n\\n  const tab = browser(first.base);\\n  await tab.call('GET', '/api/state');\\n  await tab.call('POST', '/api/cart/items', { sku: 'TEE-M-SLATE', quantity: 3 });\\n  await tab.call('PUT', '/api/cart/destination', { country: 'US', region: 'CA' });\\n  await tab.call('POST', '/api/cart/coupons', { code: 'FREESHIP' });\\n  const cookie = tab.cookie;\\n\\n  // \\"Reload\\": a fresh request cycle carrying only the cookie.\\n  const reloaded = browser(first.base);\\n  reloaded.cookie = cookie;\\n  const after = await reloaded.call('GET', '/api/state');\\n  assert.equal(after.body.receipt.itemCount, 3);\\n  assert.equal(after.body.cart.destination.region, 'CA');\\n\\n  // \\"Session end\\" + server restart: same database file, brand new process state.\\n  await first.stop({ keepFiles: true });\\n  const second = await startServer(first);\\n  t.after(() => second.stop());\\n\\n  const tomorrow = browser(second.base);\\n  tomorrow.cookie = cookie;\\n  const back = await tomorrow.call('GET', '/api/state');\\n  assert.equal(back.body.receipt.itemCount, 3);\\n  assert.equal(back.body.cart.destination.region, 'CA');\\n  assert.deepEqual(back.body.receipt.promotions.activeCodes, ['FREESHIP']);\\n});\\n\\ntest('quantity change returns fresh totals in the same response', async (t) => {\\n  const s = await startServer();\\n  t.after(() => s.stop());\\n  const tab = browser(s.base);\\n\\n  const added = await tab.call('POST', '/api/cart/items', { sku: 'BOOK-TIDES-PB', quantity: 1 });\\n  const lineId = added.body.receipt.lines[0].lineId;\\n  assert.equal(added.body.receipt.totals.subtotal.decimal, '18.00');\\n\\n  const patched = await tab.call('PATCH', \`/api/cart/items/\${lineId}\`, { quantity: 4 });\\n  assert.equal(patched.status, 200);\\n  assert.equal(patched.body.receipt.totals.subtotal.decimal, '72.00');\\n  assert.equal(patched.body.receipt.lines[0].lineTotal.decimal, '72.00');\\n\\n  const removed = await tab.call('DELETE', \`/api/cart/items/\${lineId}\`);\\n  assert.equal(removed.body.receipt.lineCount, 0);\\n});\\n\\ntest('money crosses the wire as integers and pre-formatted text, never a float', async (t) => {\\n  const s = await startServer();\\n  t.after(() => s.stop());\\n  const tab = browser(s.base);\\n  const r = await tab.call('POST', '/api/cart/items', { sku: 'CAR-BOX24', quantity: 3 });\\n  const total = r.body.receipt.totals.subtotal;\\n  assert.equal(total.minor, 4350);\\n  assert.equal(total.decimal, '43.50');\\n  assert.equal(total.currency, 'USD');\\n  assert.match(total.display, /\\\\$43\\\\.50/);\\n});\\n\\ntest('guest cart merges into the account cart over HTTP', async (t) => {\\n  const s = await startServer();\\n  t.after(() => s.stop());\\n\\n  // Session one: sign in, add something, walk away.\\n  const first = browser(s.base);\\n  await first.call('POST', '/api/session/signin', { email: 'merge@example.com' });\\n  await first.call('POST', '/api/cart/items', { sku: 'BOOK-TIDES-HB', quantity: 1 });\\n\\n  // Session two: a different device, not signed in.\\n  const second = browser(s.base);\\n  await second.call('POST', '/api/cart/items', { sku: 'CAR-BOX24', quantity: 1 });\\n  const merged = await second.call('POST', '/api/session/signin', { email: 'merge@example.com' });\\n\\n  const skus = merged.body.receipt.lines.map((l) => l.sku).sort();\\n  assert.deepEqual(skus, ['BOOK-TIDES-HB', 'CAR-BOX24']);\\n  assert.equal(merged.body.customer.email, 'merge@example.com');\\n\\n  // The old guest cookie now follows the merged cart rather than a dead one.\\n  const stale = await second.call('GET', '/api/cart');\\n  assert.equal(stale.body.receipt.lineCount, 2);\\n});\\n\\ntest('an abandoned cart is retrievable from a recovery link', async (t) => {\\n  const s = await startServer();\\n  t.after(() => s.stop());\\n\\n  const shopper = browser(s.base);\\n  const state = await shopper.call('POST', '/api/cart/items', { sku: 'TEE-M-RUST', quantity: 2 });\\n  const recoveryToken = state.body.cart.recoveryToken;\\n\\n  const list = await shopper.call('GET', '/api/carts/abandoned?minutes=0');\\n  assert.ok(list.body.carts.some((c) => c.recoveryToken === recoveryToken));\\n\\n  // A different browser entirely — the recovery link is the only thing it has.\\n  const returning = browser(s.base);\\n  const recovered = await returning.call('POST', '/api/cart/recover', { recoveryToken });\\n  assert.equal(recovered.body.receipt.itemCount, 2);\\n  assert.equal(recovered.body.messages[0].kind, 'recovered');\\n});\\n\\ntest('out-of-stock adds are refused with a 409 and an explanation', async (t) => {\\n  const s = await startServer();\\n  t.after(() => s.stop());\\n  const tab = browser(s.base);\\n  const res = await tab.call('POST', '/api/cart/items', { sku: 'TEE-L-RUST', quantity: 1 });\\n  assert.equal(res.status, 409);\\n  assert.equal(res.body.error.code, 'out_of_stock');\\n});\\n\\ntest('checkout re-checks stock, holds it, then places the order', async (t) => {\\n  const s = await startServer();\\n  t.after(() => s.stop());\\n  const tab = browser(s.base);\\n\\n  await tab.call('POST', '/api/cart/items', { sku: 'TEE-S-SLATE', quantity: 2 });\\n  await tab.call('PUT', '/api/cart/destination', { country: 'US', region: 'CA' });\\n\\n  const begun = await tab.call('POST', '/api/checkout/begin');\\n  assert.equal(begun.status, 200);\\n  assert.ok(begun.body.reservation.expiresInSeconds > 0);\\n  assert.equal(begun.body.reservation.windowMinutes, 15);\\n\\n  const done = await tab.call('POST', '/api/checkout/confirm', {});\\n  assert.equal(done.status, 200);\\n  assert.match(done.body.order.id, /^ORD-/);\\n  assert.equal(done.body.receipt.lineCount, 0);\\n  assert.equal(s.store.onHand('TEE-S-SLATE'), 10);\\n});\\n\\ntest('stock going to zero mid-session blocks checkout with a 409 and a live view', async (t) => {\\n  const s = await startServer();\\n  t.after(() => s.stop());\\n  const tab = browser(s.base);\\n\\n  await tab.call('POST', '/api/cart/items', { sku: 'KID-6-YELLOW', quantity: 2 });\\n  await tab.call('POST', '/api/admin/stock', { sku: 'KID-6-YELLOW', onHand: 0 });\\n\\n  const begun = await tab.call('POST', '/api/checkout/begin');\\n  assert.equal(begun.status, 409);\\n  assert.equal(begun.body.receipt.checkoutReady, false);\\n  assert.match(begun.body.messages[0].message, /Stock changed/);\\n});\\n\\ntest('a price change mid-session is reflected and reported', async (t) => {\\n  const s = await startServer();\\n  t.after(() => s.stop());\\n  const tab = browser(s.base);\\n\\n  await tab.call('POST', '/api/cart/items', { sku: 'DIG-TIDES-1Y', quantity: 1 });\\n  const after = await tab.call('POST', '/api/admin/price', { sku: 'DIG-TIDES-1Y', price: '12.00' });\\n  assert.equal(after.body.receipt.totals.subtotal.decimal, '12.00');\\n  assert.equal(after.body.receipt.lines[0].priceChange.was.decimal, '9.00');\\n  assert.equal(after.body.receipt.lines[0].priceChange.direction, 'up');\\n});\\n\\ntest('coupons over HTTP: applied, listed, removed, and refused with a reason', async (t) => {\\n  const s = await startServer();\\n  t.after(() => s.stop());\\n  const tab = browser(s.base);\\n\\n  await tab.call('POST', '/api/cart/items', { sku: 'BOOK-TIDES-HB', quantity: 4 }); // $128\\n  const ok = await tab.call('POST', '/api/cart/coupons', { code: 'books20' }); // case-insensitive\\n  assert.deepEqual(ok.body.receipt.promotions.activeCodes, ['BOOKS20']);\\n  assert.equal(ok.body.receipt.totals.discountTotal.decimal, '25.60');\\n\\n  const clash = await tab.call('POST', '/api/cart/coupons', { code: 'SAVE15' });\\n  assert.deepEqual(clash.body.receipt.promotions.activeCodes, ['BOOKS20']);\\n  assert.match(clash.body.messages[0].message, /cannot be combined/);\\n\\n  const gone = await tab.call('DELETE', '/api/cart/coupons/BOOKS20');\\n  assert.deepEqual(gone.body.receipt.promotions.activeCodes, []);\\n});\\n\\ntest('product images are served for every SKU', async (t) => {\\n  const s = await startServer();\\n  t.after(() => s.stop());\\n  const res = await fetch(\`\${s.base}/img/TEE-M-RUST.svg\`);\\n  assert.equal(res.status, 200);\\n  assert.equal(res.headers.get('content-type'), 'image/svg+xml');\\n  assert.match(await res.text(), /<svg/);\\n});\\n"},{"path":"test/cart.test.js","bytes":12264,"text":"import test from 'node:test';\\nimport assert from 'node:assert/strict';\\nimport { Store } from '../src/store.js';\\nimport * as svc from '../src/cart-service.js';\\n\\nfunction fresh() {\\n  const store = new Store(':memory:');\\n  const cart = store.createCart({});\\n  return { store, cart };\\n}\\nconst reload = (store, cart) => store.cartById(cart.id);\\n\\ntest('add, update quantity, remove', () => {\\n  const { store, cart } = fresh();\\n  let v = svc.addItem(store, cart, { sku: 'TEE-M-SLATE', quantity: 2 });\\n  assert.equal(v.receipt.itemCount, 2);\\n\\n  const lineId = v.receipt.lines[0].lineId;\\n  v = svc.setQuantity(store, reload(store, cart), { lineId, quantity: 5 });\\n  assert.equal(v.receipt.lines[0].quantity, 5);\\n  assert.equal(v.receipt.totals.subtotal.toDecimalString(), '120.00');\\n\\n  v = svc.removeItem(store, reload(store, cart), { lineId });\\n  assert.equal(v.receipt.lineCount, 0);\\n  assert.equal(v.receipt.totals.grandTotal.minor, 0);\\n});\\n\\ntest('setting quantity to zero removes the line', () => {\\n  const { store, cart } = fresh();\\n  const v = svc.addItem(store, cart, { sku: 'TEE-M-SLATE', quantity: 1 });\\n  const after = svc.setQuantity(store, reload(store, cart), { lineId: v.receipt.lines[0].lineId, quantity: 0 });\\n  assert.equal(after.receipt.lineCount, 0);\\n});\\n\\ntest('adding the same variant twice merges into one line', () => {\\n  const { store, cart } = fresh();\\n  svc.addItem(store, cart, { sku: 'TEE-M-SLATE', quantity: 1 });\\n  const v = svc.addItem(store, reload(store, cart), { sku: 'TEE-M-SLATE', quantity: 2 });\\n  assert.equal(v.receipt.lineCount, 1);\\n  assert.equal(v.receipt.lines[0].quantity, 3);\\n  assert.ok(v.messages.some((m) => m.kind === 'merged'));\\n});\\n\\ntest('different variants of one product stay separate', () => {\\n  const { store, cart } = fresh();\\n  svc.addItem(store, cart, { sku: 'TEE-M-SLATE', quantity: 1 });\\n  svc.addItem(store, reload(store, cart), { sku: 'TEE-L-SLATE', quantity: 1 });\\n  const v = svc.addItem(store, reload(store, cart), { sku: 'TEE-M-RUST', quantity: 1 });\\n  assert.equal(v.receipt.lineCount, 3);\\n});\\n\\ntest('availability is checked at add time', () => {\\n  const { store, cart } = fresh();\\n  assert.throws(() => svc.addItem(store, cart, { sku: 'TEE-L-RUST', quantity: 1 }), /out of stock/i);\\n\\n  // Only 3 of TEE-L-SLATE exist: asking for 5 clamps and says so.\\n  const v = svc.addItem(store, cart, { sku: 'TEE-L-SLATE', quantity: 5 });\\n  assert.equal(v.receipt.lines[0].quantity, 3);\\n  assert.ok(v.messages.some((m) => m.kind === 'stock-clamped'));\\n});\\n\\ntest('the cart survives a \\"restart\\": state is in the database, not in memory', () => {\\n  const store = new Store(':memory:');\\n  const cart = store.createCart({});\\n  svc.addItem(store, cart, { sku: 'TEE-M-SLATE', quantity: 3 }); // $72 — clears WELCOME10's $50 minimum\\n  svc.setDestination(store, reload(store, cart), { country: 'GB' });\\n  svc.applyCoupon(store, reload(store, cart), { code: 'WELCOME10' });\\n\\n  // Nothing is cached: re-hydrate the cart by its token, as a new process would.\\n  const rehydrated = store.cartByToken(cart.token);\\n  const v = svc.view(store, rehydrated);\\n  assert.equal(v.receipt.itemCount, 3);\\n  assert.deepEqual(v.cart.destination, { country: 'GB', region: null });\\n  assert.deepEqual(v.receipt.promotions.activeCodes, ['WELCOME10']);\\n});\\n\\ntest('a coupon that cannot apply is not left sitting in the cart', () => {\\n  const { store, cart } = fresh();\\n  svc.addItem(store, cart, { sku: 'BOOK-TIDES-PB', quantity: 1 }); // $18, below WELCOME10's $50\\n  const v = svc.applyCoupon(store, reload(store, cart), { code: 'WELCOME10' });\\n  assert.equal(v.receipt.promotions.applied.length, 0);\\n  assert.equal(reload(store, cart).couponCodes.length, 0);\\n  assert.match(v.messages[0].message, /needs \\\\$50\\\\.00/);\\n});\\n\\ntest('guest cart merges into the account cart on sign-in', () => {\\n  const store = new Store(':memory:');\\n\\n  // A previous session on this account left a cart behind.\\n  const accountCart = store.createCart({});\\n  const account = store.createAccount('shopper@example.com');\\n  store.setCartAccount(accountCart.id, account.id, account.email);\\n  svc.addItem(store, reload(store, accountCart), { sku: 'BOOK-TIDES-HB', quantity: 1 });\\n  svc.addItem(store, reload(store, accountCart), { sku: 'TEE-M-SLATE', quantity: 1 });\\n\\n  // Today, as a guest, they add more.\\n  const guest = store.createCart({});\\n  svc.addItem(store, guest, { sku: 'CAR-BOX24', quantity: 2 });\\n  svc.addItem(store, reload(store, guest), { sku: 'TEE-M-SLATE', quantity: 3 });\\n  svc.setDestination(store, reload(store, guest), { country: 'GB' });\\n\\n  const v = svc.signIn(store, reload(store, guest), { email: 'shopper@example.com' });\\n\\n  const bySku = Object.fromEntries(v.receipt.lines.map((l) => [l.sku, l.quantity]));\\n  assert.equal(bySku['BOOK-TIDES-HB'], 1); // kept from the account cart\\n  assert.equal(bySku['CAR-BOX24'], 2);     // brought over from the guest cart\\n  assert.equal(bySku['TEE-M-SLATE'], 3);   // in both: the larger quantity wins, not the sum\\n  assert.deepEqual(v.cart.destination, { country: 'GB', region: null }); // the guest's choice wins\\n  assert.equal(v.customer.email, 'shopper@example.com');\\n  assert.equal(store.cartById(guest.id).status, 'merged');\\n  assert.equal(store.cartById(guest.id).mergedInto, accountCart.id);\\n});\\n\\ntest('signing in with no account cart simply keeps the guest cart', () => {\\n  const { store, cart } = fresh();\\n  svc.addItem(store, cart, { sku: 'TEE-M-SLATE', quantity: 1 });\\n  const v = svc.signIn(store, reload(store, cart), { email: 'new@example.com' });\\n  assert.equal(v.cart.id, cart.id);\\n  assert.equal(v.receipt.itemCount, 1);\\n  assert.equal(v.customer.signedIn, true);\\n});\\n\\ntest('the merge carries coupons across and re-checks them', () => {\\n  const store = new Store(':memory:');\\n  const account = store.createAccount('two@example.com');\\n  const accountCart = store.createCart({ accountId: account.id, email: account.email });\\n  svc.addItem(store, reload(store, accountCart), { sku: 'JKT-M-OLIVE', quantity: 1 });\\n  svc.applyCoupon(store, reload(store, accountCart), { code: 'TENOFF' });\\n\\n  const guest = store.createCart({});\\n  svc.addItem(store, guest, { sku: 'BOOK-TIDES-HB', quantity: 1 });\\n  svc.applyCoupon(store, reload(store, guest), { code: 'BOOKS20' });\\n\\n  const v = svc.signIn(store, reload(store, guest), { email: 'two@example.com' });\\n  assert.deepEqual(v.receipt.promotions.activeCodes.sort(), ['BOOKS20', 'TENOFF']); // different scopes, so both live\\n});\\n\\ntest('abandoned carts are listed and retrievable by recovery token', () => {\\n  const store = new Store(':memory:');\\n  const cart = store.createCart({});\\n  svc.addItem(store, cart, { sku: 'TEE-M-SLATE', quantity: 1 });\\n\\n  assert.equal(store.abandonedCarts(30).length, 0); // touched just now\\n  const stale = store.abandonedCarts(0);\\n  assert.equal(stale.length, 1);\\n  assert.equal(stale[0].unitCount, 1);\\n\\n  const recovered = store.cartByRecoveryToken(stale[0].recoveryToken);\\n  assert.equal(recovered.id, cart.id);\\n  assert.equal(svc.view(store, recovered).receipt.itemCount, 1);\\n});\\n\\ntest('no reservation while browsing; a hold only at checkout', () => {\\n  const store = new Store(':memory:');\\n  const a = store.createCart({});\\n  const b = store.createCart({});\\n\\n  svc.addItem(store, a, { sku: 'JKT-M-NAVY', quantity: 1 }); // stock: 1\\n  // Cart B can still add it — a cart does not reserve stock.\\n  const bView = svc.addItem(store, b, { sku: 'JKT-M-NAVY', quantity: 1 });\\n  assert.equal(bView.receipt.lineCount, 1);\\n  assert.equal(bView.policy.reservation.holdsStockInCart, false);\\n\\n  // B starts checkout and takes the 15-minute hold.\\n  const begun = svc.beginCheckout(store, reload(store, b));\\n  assert.equal(begun.ok, true);\\n  assert.ok(begun.view.reservation.expiresInSeconds > 0);\\n\\n  // Now A sees it as unavailable, and cannot check out.\\n  const aView = svc.view(store, reload(store, a));\\n  assert.equal(aView.receipt.lines[0].stockState, 'out_of_stock');\\n  assert.equal(svc.beginCheckout(store, reload(store, a)).ok, false);\\n});\\n\\ntest('the hold expires and the stock comes back', () => {\\n  const store = new Store(':memory:');\\n  const a = store.createCart({});\\n  const b = store.createCart({});\\n  svc.addItem(store, a, { sku: 'JKT-M-NAVY', quantity: 1 });\\n  svc.addItem(store, b, { sku: 'JKT-M-NAVY', quantity: 1 });\\n\\n  const now = new Date('2026-03-01T12:00:00Z');\\n  svc.beginCheckout(store, reload(store, b), { now });\\n\\n  const later = new Date(now.getTime() + 16 * 60_000); // past the 15-minute window\\n  const aView = svc.view(store, reload(store, a), { now: later });\\n  assert.equal(aView.receipt.lines[0].stockState, 'low');\\n  assert.equal(svc.beginCheckout(store, reload(store, a), { now: later }).ok, true);\\n});\\n\\ntest('stock is re-checked at checkout, not just at add', () => {\\n  const { store, cart } = fresh();\\n  svc.addItem(store, cart, { sku: 'TEE-M-SLATE', quantity: 4 });\\n\\n  store.setStock('TEE-M-SLATE', 1); // the world moved while they browsed\\n\\n  const view = svc.view(store, reload(store, cart));\\n  assert.equal(view.receipt.checkoutReady, false);\\n  const begun = svc.beginCheckout(store, reload(store, cart));\\n  assert.equal(begun.ok, false);\\n  assert.equal(begun.reason, 'stock');\\n  assert.match(begun.view.messages[0].message, /Stock changed while you were shopping/);\\n});\\n\\ntest('checkout decrements stock, writes an order and hands back an empty cart', () => {\\n  const { store, cart } = fresh();\\n  svc.addItem(store, cart, { sku: 'TEE-M-SLATE', quantity: 2 });\\n  svc.setDestination(store, reload(store, cart), { country: 'US', region: 'CA' });\\n\\n  const before = store.onHand('TEE-M-SLATE');\\n  assert.equal(svc.beginCheckout(store, reload(store, cart)).ok, true);\\n  const done = svc.confirmCheckout(store, reload(store, cart), { email: 'buyer@example.com' });\\n\\n  assert.equal(done.ok, true);\\n  assert.match(done.orderId, /^ORD-/);\\n  assert.equal(store.onHand('TEE-M-SLATE'), before - 2);\\n  assert.equal(done.view.receipt.lineCount, 0);          // a fresh cart\\n  assert.notEqual(done.view.cart.id, cart.id);\\n  assert.equal(store.cartById(cart.id).status, 'ordered');\\n\\n  const order = store.orderById(done.orderId);\\n  assert.equal(order.totalMinor, done.order.receipt.totals.grandTotal.minor);\\n  assert.ok(order.receipt.lines.length === 1);\\n});\\n\\ntest('price changes between add and checkout are surfaced, and the current price is charged', () => {\\n  const { store, cart } = fresh();\\n  svc.addItem(store, cart, { sku: 'CAR-BOX24', quantity: 1 }); // $14.50\\n  store.setPrice('CAR-BOX24', '16.00');\\n\\n  const v = svc.view(store, reload(store, cart));\\n  assert.equal(v.receipt.totals.subtotal.toDecimalString(), '16.00');\\n  assert.equal(v.receipt.lines[0].priceChange.was.toDecimalString(), '14.50');\\n\\n  const begun = svc.beginCheckout(store, reload(store, cart));\\n  assert.ok(begun.view.messages.some((m) => m.kind === 'price-change'));\\n  store.setPrice('CAR-BOX24', '14.50'); // put it back for other assertions in this file\\n});\\n\\ntest('confirm re-checks stock even if it was held, and charges nothing when it fails', () => {\\n  const { store, cart } = fresh();\\n  svc.addItem(store, cart, { sku: 'TEE-M-SLATE', quantity: 2 });\\n  svc.beginCheckout(store, reload(store, cart));\\n\\n  store.setStock('TEE-M-SLATE', 0); // a stocktake finds the shelf empty\\n\\n  const done = svc.confirmCheckout(store, reload(store, cart));\\n  assert.equal(done.ok, false);\\n  assert.match(done.view.messages[0].message, /Nothing has been charged/);\\n  assert.equal(store.orderById('nope'), null);\\n});\\n\\ntest('every mutation returns fully recomputed totals — nothing stale', () => {\\n  const { store, cart } = fresh();\\n  svc.addItem(store, cart, { sku: 'TEE-M-SLATE', quantity: 1 });\\n  const withDest = svc.setDestination(store, reload(store, cart), { country: 'GB' });\\n  assert.equal(withDest.receipt.tax.jurisdiction.key, 'GB');\\n\\n  const withQty = svc.setQuantity(store, reload(store, cart), {\\n    lineId: withDest.receipt.lines[0].lineId,\\n    quantity: 3,\\n  });\\n  assert.equal(withQty.receipt.totals.subtotal.toDecimalString(), '72.00');\\n  assert.equal(withQty.receipt.shipping.amount.toDecimalString(), '14.50'); // 12.00 + 2.50/kg to Europe\\n  assert.equal(withQty.receipt.totals.tax.toDecimalString(), '17.30'); // 20% of 72.00 + 20% of 14.50\\n  assert.equal(withQty.receipt.totals.grandTotal.toDecimalString(), '103.80');\\n});\\n"},{"path":"test/frontend.test.js","bytes":2447,"text":"/**\\n * Static checks on the shop front. There is no browser in the test environment,\\n * so this catches the failure that would otherwise be silent: app.js reaching for\\n * an element id that index.html does not have, which throws during boot and\\n * leaves a blank page.\\n */\\n\\nimport test from 'node:test';\\nimport assert from 'node:assert/strict';\\nimport { readFileSync } from 'node:fs';\\nimport { fileURLToPath } from 'node:url';\\n\\nconst read = (p) => readFileSync(fileURLToPath(new URL(\`../public/\${p}\`, import.meta.url)), 'utf8');\\nconst html = read('index.html');\\nconst app = read('app.js');\\nconst css = read('styles.css');\\n\\n// Ids in the page, plus the ones app.js renders itself (the demo panel).\\nconst idsAvailable = new Set(\\n  [...html.matchAll(/\\\\bid=\\"([^\\"]+)\\"/g), ...app.matchAll(/\\\\bid=\\"([^\\"]+)\\"/g)].map((m) => m[1]),\\n);\\nconst idsUsedByApp = new Set([...app.matchAll(/\\\\$\\\\('([^']+)'\\\\)/g)].map((m) => m[1]));\\n\\ntest('every element app.js reaches for exists in the page', () => {\\n  const missing = [...idsUsedByApp].filter((id) => !idsAvailable.has(id));\\n  assert.deepEqual(missing, []);\\n  assert.ok(idsUsedByApp.size > 20, 'sanity: the scan found the wiring it was meant to check');\\n});\\n\\ntest('the page is wired to its own stylesheet and module', () => {\\n  assert.match(html, /<link rel=\\"stylesheet\\" href=\\"\\\\/styles\\\\.css\\"/);\\n  assert.match(html, /<script type=\\"module\\" src=\\"\\\\/app\\\\.js\\">/);\\n  assert.ok(css.includes('.line__linetotal'));\\n});\\n\\ntest('the front end never computes money itself', () => {\\n  // No arithmetic on amounts: everything displayed comes from the server's receipt.\\n  assert.equal(/toFixed\\\\(/.test(app), false);\\n  assert.equal(/\\\\/\\\\s*100\\\\b/.test(app), false);\\n  assert.ok(app.includes('.display'));\\n});\\n\\ntest('user-supplied text is escaped before it reaches innerHTML', () => {\\n  assert.ok(app.includes('function esc('));\\n  // Coupon codes and emails are the only user-entered strings that get rendered.\\n  assert.ok(app.includes('esc(c.code)'));\\n  assert.ok(app.includes('esc(customer.email)'));\\n});\\n\\ntest('the UI states the things the spec asks to be stated', () => {\\n  assert.ok(app.includes('Estimate only'));           // shipping is an estimate\\n  assert.ok(app.includes('not</strong> reserved'));   // explicit lack of a cart-level hold\\n  assert.ok(app.includes('Stacking:'));               // the stacking policy is on screen\\n  assert.ok(app.includes('renderPolicies'));          // currency/rounding rules are on screen\\n});\\n"},{"path":"test/money.test.js","bytes":2295,"text":"import test from 'node:test';\\nimport assert from 'node:assert/strict';\\nimport { Money, allocate, roundHalfUp, sum } from '../src/money.js';\\n\\ntest('parses decimal strings into exact minor units', () => {\\n  assert.equal(Money.parse('12.99').minor, 1299);\\n  assert.equal(Money.parse('0.01').minor, 1);\\n  assert.equal(Money.parse('189').minor, 18_900);\\n  assert.equal(Money.parse('-4.50').minor, -450);\\n  assert.equal(Money.parse('1200', 'JPY').minor, 1200);\\n});\\n\\ntest('refuses precision the currency does not have', () => {\\n  assert.throws(() => Money.parse('1.234'), /precision/);\\n  assert.throws(() => Money.parse('1.5', 'JPY'), /precision/);\\n  assert.throws(() => new Money(1.5), /whole minor units/);\\n});\\n\\ntest('the 0.1 + 0.2 problem does not exist here', () => {\\n  assert.equal(Money.parse('0.10').plus(Money.parse('0.20')).toDecimalString(), '0.30');\\n  // ...whereas floats:\\n  assert.notEqual(0.1 + 0.2, 0.3);\\n});\\n\\ntest('refuses to mix currencies', () => {\\n  assert.throws(() => Money.parse('1.00', 'USD').plus(Money.parse('1.00', 'GBP')), /mismatch/);\\n});\\n\\ntest('rounds half away from zero', () => {\\n  assert.equal(roundHalfUp(5, 2), 3);\\n  assert.equal(roundHalfUp(-5, 2), -3);\\n  assert.equal(roundHalfUp(4, 2), 2);\\n  assert.equal(roundHalfUp(1, 3), 0);\\n  // 8.75% of $19.99 = 1.7491... -> 1.75\\n  assert.equal(Money.parse('19.99').percentBps(875).toDecimalString(), '1.75');\\n  // 20% of $0.025 rounds up, not down\\n  assert.equal(new Money(3).percentBps(5000).minor, 2);\\n});\\n\\ntest('allocation never loses or invents a cent', () => {\\n  const parts = allocate(Money.parse('10.00'), [1, 1, 1]);\\n  assert.deepEqual(parts.map((p) => p.minor), [334, 333, 333]);\\n  assert.equal(sum(parts).minor, 1000);\\n\\n  const weighted = allocate(Money.parse('0.05'), [7, 3]);\\n  assert.equal(sum(weighted).minor, 5);\\n\\n  const negative = allocate(Money.parse('-1.00'), [1, 1, 1]);\\n  assert.equal(sum(negative).minor, -100);\\n\\n  const noWeight = allocate(Money.parse('3.00'), [0, 0]);\\n  assert.equal(sum(noWeight).minor, 300);\\n});\\n\\ntest('formats and serialises without floats on the wire', () => {\\n  const m = Money.parse('1234.05');\\n  assert.equal(m.toDecimalString(), '1234.05');\\n  assert.equal(m.toJSON().minor, 123_405);\\n  assert.equal(m.toJSON().decimal, '1234.05');\\n  assert.match(m.format(), /1,234\\\\.05/);\\n});\\n"},{"path":"test/pricing.test.js","bytes":6007,"text":"import test from 'node:test';\\nimport assert from 'node:assert/strict';\\nimport { price } from '../src/pricing.js';\\nimport { Money } from '../src/money.js';\\n\\n/** Minimal cart literal — the same shape the store hydrates. */\\nfunction cart(lines, extra = {}) {\\n  return {\\n    lines: lines.map((l, i) => ({\\n      lineId: \`L\${i}\`,\\n      sku: l.sku,\\n      quantity: l.qty,\\n      unitPriceMinorAtAdd: l.addedAt ?? null,\\n      addedAt: '2026-01-01T00:00:00.000Z',\\n    })),\\n    destination: null,\\n    shippingMethodId: 'standard',\\n    couponCodes: [],\\n    customer: { isNewCustomer: true, accountId: null },\\n    ...extra,\\n  };\\n}\\n\\ntest('line subtotal, cart subtotal and grand total', () => {\\n  const r = price(cart([{ sku: 'TEE-M-SLATE', qty: 2 }, { sku: 'BOOK-TIDES-PB', qty: 1 }]));\\n  assert.equal(r.lines[0].lineSubtotal.toDecimalString(), '48.00'); // 24.00 x 2\\n  assert.equal(r.totals.subtotal.toDecimalString(), '66.00');\\n  // No destination yet: no tax, no shipping quote.\\n  assert.equal(r.totals.tax.minor, 0);\\n  assert.equal(r.shipping.quotable, false);\\n  assert.equal(r.totals.grandTotal.toDecimalString(), '66.00');\\n});\\n\\ntest('variants of one product are separate lines and are not merged', () => {\\n  const r = price(cart([{ sku: 'TEE-M-SLATE', qty: 1 }, { sku: 'TEE-M-RUST', qty: 1 }, { sku: 'TEE-L-SLATE', qty: 1 }]));\\n  assert.equal(r.lineCount, 3);\\n  assert.equal(new Set(r.lines.map((l) => l.variantLabel)).size, 3);\\n});\\n\\ntest('tax varies by destination and by product class', () => {\\n  const lines = [{ sku: 'TEE-M-SLATE', qty: 1 }, { sku: 'BOOK-TIDES-HB', qty: 1 }, { sku: 'CAR-BOX24', qty: 1 }];\\n\\n  const uk = price(cart(lines, { destination: { country: 'GB' } }));\\n  const byClass = Object.fromEntries(uk.lines.map((l) => [l.productClass, l.taxRateBps]));\\n  assert.equal(byClass.apparel, 2000); // 20% VAT\\n  assert.equal(byClass.book, 0); // zero-rated\\n  assert.equal(byClass.grocery, 0); // zero-rated\\n\\n  const or = price(cart(lines, { destination: { country: 'US', region: 'OR' } }));\\n  assert.equal(or.totals.tax.minor, 0); // no sales tax in Oregon\\n\\n  const ca = price(cart(lines, { destination: { country: 'US', region: 'CA' } }));\\n  assert.equal(ca.lines.find((l) => l.productClass === 'grocery').taxRateBps, 0);\\n  assert.equal(ca.lines.find((l) => l.productClass === 'apparel').taxRateBps, 875);\\n\\n  // NY exempts clothing under $110 an item but taxes the book.\\n  const ny = price(cart(lines, { destination: { country: 'US', region: 'NY' } }));\\n  assert.equal(ny.lines.find((l) => l.productClass === 'apparel').taxRateBps, 0);\\n  assert.equal(ny.lines.find((l) => l.productClass === 'book').taxRateBps, 888);\\n});\\n\\ntest('tax is charged on the discounted amount, not the list price', () => {\\n  const base = price(cart([{ sku: 'JKT-M-OLIVE', qty: 1 }], { destination: { country: 'GB' } }));\\n  const discounted = price(\\n    cart([{ sku: 'JKT-M-OLIVE', qty: 1 }], { destination: { country: 'GB' }, couponCodes: ['SAVE15'] }),\\n  );\\n  assert.equal(base.totals.tax.toDecimalString(), '37.80'); // 20% of 189.00\\n  assert.equal(discounted.totals.discountTotal.toDecimalString(), '28.35');\\n  assert.equal(discounted.totals.tax.toDecimalString(), '32.13'); // 20% of 160.65\\n});\\n\\ntest('shipping is estimated before checkout, and free over the threshold', () => {\\n  const light = price(cart([{ sku: 'BOOK-TIDES-PB', qty: 1 }], { destination: { country: 'US', region: 'OR' } }));\\n  assert.equal(light.shipping.quotable, true);\\n  assert.equal(light.shipping.amount.toDecimalString(), '5.85'); // 4.95 + 0.90 x 1kg\\n\\n  const heavy = price(cart([{ sku: 'JKT-M-OLIVE', qty: 1 }], { destination: { country: 'US', region: 'OR' } }));\\n  assert.equal(heavy.shipping.amount.minor, 0); // over the $75 free-shipping line\\n  assert.match(heavy.shipping.reason, /Free standard shipping/);\\n\\n  const express = price(\\n    cart([{ sku: 'BOOK-TIDES-PB', qty: 1 }], { destination: { country: 'US', region: 'OR' }, shippingMethodId: 'express' }),\\n  );\\n  assert.equal(express.shipping.amount.toDecimalString(), '14.75');\\n  assert.equal(express.shipping.options.length, 2);\\n});\\n\\ntest('digital-only carts do not ship', () => {\\n  const r = price(cart([{ sku: 'DIG-TIDES-1Y', qty: 1 }], { destination: { country: 'GB' } }));\\n  assert.equal(r.shipping.amount.minor, 0);\\n  assert.equal(r.shipping.label, 'Digital delivery');\\n});\\n\\ntest('totals are recomputed from current prices, and the change is surfaced', () => {\\n  const stale = cart([{ sku: 'TEE-M-SLATE', qty: 1 }]);\\n  stale.lines[0].unitPriceMinorAtAdd = 1999; // was added at $19.99, list is now $24.00\\n  const r = price(stale);\\n  assert.equal(r.totals.subtotal.toDecimalString(), '24.00');\\n  assert.equal(r.lines[0].priceChange.direction, 'up');\\n  assert.ok(r.lines[0].notices.some((n) => n.kind === 'price-change'));\\n});\\n\\ntest('stock shortfalls block checkout and say why', () => {\\n  const availability = new Map([['TEE-M-SLATE', 1], ['TEE-L-RUST', 0]]);\\n  const r = price(cart([{ sku: 'TEE-M-SLATE', qty: 3 }, { sku: 'TEE-L-RUST', qty: 1 }]), { availability });\\n  assert.equal(r.checkoutReady, false);\\n  assert.equal(r.blockers.length, 2);\\n  assert.equal(r.lines[0].stockState, 'partial');\\n  assert.equal(r.lines[1].stockState, 'out_of_stock');\\n});\\n\\ntest('an empty cart is a well-formed zero receipt', () => {\\n  const r = price(cart([]));\\n  assert.equal(r.totals.grandTotal.minor, 0);\\n  assert.equal(r.checkoutReady, false);\\n});\\n\\ntest('rounding stays honest across many small lines', () => {\\n  // Ten $0.33-ish lines with a 15% order discount: the parts must sum to the whole.\\n  const lines = Array.from({ length: 7 }, () => ({ sku: 'CAR-BOX24', qty: 1 }));\\n  const r = price(cart(lines, { couponCodes: ['SAVE15'], destination: { country: 'US', region: 'CA' } }));\\n  const perLine = r.lines.reduce((acc, l) => acc.plus(l.discount), Money.zero('USD'));\\n  assert.equal(perLine.minor, r.totals.discountTotal.minor);\\n  const recomputed = r.lines.reduce((acc, l) => acc.plus(l.lineTotal), Money.zero('USD'));\\n  assert.equal(recomputed.minor, r.totals.merchandiseTotal.minor);\\n});\\n"},{"path":"test/promotions.test.js","bytes":5442,"text":"import test from 'node:test';\\nimport assert from 'node:assert/strict';\\nimport { price } from '../src/pricing.js';\\n\\nfunction cart(lines, extra = {}) {\\n  return {\\n    lines: lines.map((l, i) => ({ lineId: \`L\${i}\`, sku: l.sku, quantity: l.qty, unitPriceMinorAtAdd: null, addedAt: '2026-01-01T00:00:00.000Z' })),\\n    destination: { country: 'US', region: 'OR' },\\n    shippingMethodId: 'standard',\\n    couponCodes: [],\\n    customer: { isNewCustomer: true, accountId: null },\\n    ...extra,\\n  };\\n}\\n\\nconst codes = (r, list) => r.promotions[list].map((x) => x.code);\\n\\ntest('percentage coupon comes off the order and off the tax base', () => {\\n  const r = price(cart([{ sku: 'JKT-M-OLIVE', qty: 1 }], { couponCodes: ['SAVE15'] }));\\n  assert.deepEqual(codes(r, 'applied'), ['SAVE15']);\\n  assert.equal(r.totals.discountTotal.toDecimalString(), '28.35');\\n  assert.equal(r.totals.merchandiseTotal.toDecimalString(), '160.65');\\n});\\n\\ntest('minimum-spend eligibility is enforced with a useful reason', () => {\\n  const r = price(cart([{ sku: 'BOOK-TIDES-PB', qty: 1 }], { couponCodes: ['WELCOME10'] }));\\n  assert.deepEqual(codes(r, 'applied'), []);\\n  assert.match(r.promotions.rejected[0].reason, /needs \\\\$50\\\\.00 .*\\\\$32\\\\.00 more to go/);\\n});\\n\\ntest('first-order coupons are refused to returning customers', () => {\\n  const returning = { isNewCustomer: false, accountId: 'acct-1' };\\n  const r = price(cart([{ sku: 'JKT-M-OLIVE', qty: 1 }], { couponCodes: ['WELCOME10'], customer: returning }));\\n  assert.match(r.promotions.rejected[0].reason, /first orders only/);\\n});\\n\\ntest('expired coupons are refused', () => {\\n  const r = price(cart([{ sku: 'JKT-M-OLIVE', qty: 1 }], { couponCodes: ['SPRING24'] }));\\n  assert.match(r.promotions.rejected[0].reason, /expired/);\\n});\\n\\ntest('item-scope coupons only touch matching lines', () => {\\n  const r = price(cart([{ sku: 'BOOK-TIDES-HB', qty: 1 }, { sku: 'TEE-M-SLATE', qty: 1 }], { couponCodes: ['BOOKS20'] }));\\n  const book = r.lines.find((l) => l.productClass === 'book');\\n  const tee = r.lines.find((l) => l.productClass === 'apparel');\\n  assert.equal(book.discount.toDecimalString(), '6.40'); // 20% of 32.00\\n  assert.equal(tee.discount.minor, 0);\\n});\\n\\ntest('item + order + shipping coupons stack, one per scope', () => {\\n  const r = price(\\n    cart([{ sku: 'BOOK-TIDES-HB', qty: 2 }, { sku: 'TEE-M-SLATE', qty: 2 }], {\\n      couponCodes: ['BOOKS20', 'TENOFF', 'SHIPHALF'],\\n      shippingMethodId: 'express', // express is never free, so the shipping coupon has something to bite on\\n    }),\\n  );\\n  assert.deepEqual(codes(r, 'applied').sort(), ['BOOKS20', 'SHIPHALF', 'TENOFF']);\\n  assert.equal(r.promotions.rejected.length, 0);\\n  // 64.00 books - 12.80 + 48.00 tees = 99.20, then $10 off = 89.20\\n  assert.equal(r.totals.merchandiseTotal.toDecimalString(), '89.20');\\n  assert.ok(r.totals.shippingDiscount.minor > 0);\\n});\\n\\ntest('a second coupon in the same scope is refused, naming the incumbent', () => {\\n  const r = price(cart([{ sku: 'JKT-M-OLIVE', qty: 1 }], { couponCodes: ['TENOFF', 'WELCOME10'] }));\\n  assert.deepEqual(codes(r, 'applied'), ['TENOFF']);\\n  assert.match(r.promotions.rejected[0].reason, /Only one order offer at a time — TENOFF/);\\n});\\n\\ntest('an exclusive coupon refuses to share the cart, in either order', () => {\\n  const a = price(cart([{ sku: 'BOOK-TIDES-HB', qty: 4 }], { couponCodes: ['BOOKS20', 'SAVE15'] }));\\n  assert.deepEqual(codes(a, 'applied'), ['BOOKS20']);\\n  assert.match(a.promotions.rejected[0].reason, /SAVE15 cannot be combined/);\\n\\n  const b = price(cart([{ sku: 'BOOK-TIDES-HB', qty: 4 }], { couponCodes: ['SAVE15', 'BOOKS20'] }));\\n  assert.deepEqual(codes(b, 'applied'), ['SAVE15']);\\n  assert.match(b.promotions.rejected[0].reason, /SAVE15 cannot be combined with other offers/);\\n});\\n\\ntest('application order does not depend on typing order', () => {\\n  const one = price(cart([{ sku: 'BOOK-TIDES-HB', qty: 3 }], { couponCodes: ['BOOKS20', 'TENOFF'] }));\\n  const two = price(cart([{ sku: 'BOOK-TIDES-HB', qty: 3 }], { couponCodes: ['TENOFF', 'BOOKS20'] }));\\n  assert.equal(one.totals.grandTotal.minor, two.totals.grandTotal.minor);\\n});\\n\\ntest('free shipping applies to its method only', () => {\\n  const std = price(cart([{ sku: 'TEE-M-SLATE', qty: 3 }], { couponCodes: ['FREESHIP'] }));\\n  assert.deepEqual(codes(std, 'applied'), ['FREESHIP']);\\n  assert.equal(std.totals.shippingNet.minor, 0);\\n\\n  const exp = price(cart([{ sku: 'TEE-M-SLATE', qty: 3 }], { couponCodes: ['FREESHIP'], shippingMethodId: 'express' }));\\n  assert.deepEqual(codes(exp, 'applied'), []);\\n  assert.match(exp.promotions.rejected[0].reason, /standard shipping only/);\\n  assert.ok(exp.totals.shippingNet.minor > 0);\\n});\\n\\ntest('shipping coupons are refused on a digital-only cart', () => {\\n  const r = price(cart([{ sku: 'DIG-TIDES-1Y', qty: 1 }], { couponCodes: ['SHIPHALF'] }));\\n  assert.match(r.promotions.rejected[0].reason, /nothing to ship/);\\n});\\n\\ntest('a fixed discount can never exceed the goods, nor make a line negative', () => {\\n  const r = price(cart([{ sku: 'TEE-M-SLATE', qty: 1 }], { couponCodes: ['TEE5'] }));\\n  assert.equal(r.lines[0].lineTotal.toDecimalString(), '19.00');\\n  assert.ok(!r.lines[0].lineTotal.isNegative());\\n  assert.ok(!r.totals.grandTotal.isNegative());\\n});\\n\\ntest('unknown codes are reported, not swallowed', () => {\\n  const r = price(cart([{ sku: 'TEE-M-SLATE', qty: 1 }], { couponCodes: ['NOPE'] }));\\n  assert.match(r.promotions.rejected[0].reason, /not a valid code/);\\n});\\n"}]`),a={slug:e,selfReport:n,files:t};export{a as default,t as files,n as selfReport,e as slug};
